-- runtime/coords.lua is the single coordinate authority, localised here because the
-- tangent transform below runs once per mesh vertex and a table lookup per vertex is
-- not free. coords.lua is dependency-free, so loading it at module scope is safe
-- regardless of where render.lua sits in the load order
local runtime_coords = runtime_require("coords.lua")
local tangent_to_world_basis = runtime_coords.tangent_to_world_basis
local authored_color3_to_gpu = runtime_coords.color3_to_gpu
local SurfaceAppearance = runtime_require("surface_appearance.lua")
local ExactIndex = runtime_require("exact_index.lua")
-- keep integration state on the existing runtime namespace: this very large
-- chunk sits on LuaJIT's 200-local parser boundary
RBX._material_registry = RBX._material_registry
    or runtime_require("material_registry.lua")
RBX._material_variants = RBX._material_variants
    or runtime_require("material_variants.lua")
RBX._atmosphere = RBX._atmosphere or runtime_require("atmosphere.lua")
RBX._uniform_packets = RBX._uniform_packets
    or runtime_require("uniform_packet.lua")
RBX._contact_ao = RBX._contact_ao or runtime_require("contact_ao.lua")
RBX._constraint_visuals = RBX._constraint_visuals or runtime_require("constraint_visuals.lua")

local function release_render_resource(resource)
    if resource and type(resource.release) == "function" then
        pcall(resource.release, resource)
    end
end

-- exact indexing is a load-time optimization, not an unbounded preprocessing
-- job. Large authored batches retain the proven flat path, spatial/mega batch
-- partitioning normally keeps production candidates well below this ceiling
-- keep every helper behind one module local: this runtime chunk is deliberately
-- large and LuaJIT caps a main function at 200 active locals
local StaticExact = {
    vertex_components = 20,
    vertex_stride_bytes = 20 * 4,
    source_vertex_limit = 65536,
}

function StaticExact.new_stats()
    return {
        immutable_call_count = 0,
        candidate_count = 0,
        indexed_batch_count = 0,
        uint16_batch_count = 0,
        uint32_batch_count = 0,
        partitioned_batch_count = 0,
        flat_fallback_count = 0,
        backend_failure_fallback_count = 0,
        unsafe_rejection_count = 0,
        ineligible_batch_count = 0,
        source_vertex_count = 0,
        base_vertex_count = 0,
        index_count = 0,
        flat_vertex_bytes = 0,
        uploaded_vertex_bytes = 0,
        uploaded_index_bytes = 0,
        uploaded_bytes = 0,
        bytes_saved = 0,
        compaction_ms = 0,
        fallback_reasons = {},
        ineligible_reasons = {},
        rejection_reasons = {},
    }
end

function RBX:_reset_static_textured_index_stats()
    self._static_textured_index_stats =
        StaticExact.new_stats()
    return self._static_textured_index_stats
end

function StaticExact.stats(renderer)
    local stats = renderer._static_textured_index_stats
    if type(stats) ~= "table" then
        stats = renderer:_reset_static_textured_index_stats()
    end
    return stats
end

function StaticExact.note_reason(stats, field, reason)
    local reasons = stats[field]
    if type(reasons) ~= "table" then
        reasons = {}
        stats[field] = reasons
    end
    reason = tostring(reason or "unspecified")
    reasons[reason] = (reasons[reason] or 0) + 1
end

-- the backend identity is copied once during renderer creation. Derive the
-- exact-static contract once as well: get_identity() allocates a copy and must
-- never become a per-batch hot-path probe
function RBX:_get_static_textured_index_capability()
    local cached = rawget(self, "_static_textured_index_capability")
    if type(cached) == "table" then
        return cached
    end

    local backend = rawget(self, "_render_backend")
    local identity = rawget(self, "_render_backend_identity")
    local capability = {
        enabled = false,
        reason = "backend_unavailable",
        uint16 = false,
        uint32 = false,
    }
    if self.render_backend_name ~= "menori" or type(backend) ~= "table" then
        capability.reason = "not_menori"
    elseif type(identity) ~= "table" then
        capability.reason = "identity_unavailable"
    elseif identity.static_mesh_resources ~= true then
        capability.reason = "static_mesh_resources_unavailable"
    elseif identity.indexed_geometry ~= true then
        capability.reason = "indexed_geometry_unavailable"
    elseif type(backend.create_static_mesh_batch) ~= "function"
        and type(backend.create_static_batch) ~= "function" then
        capability.reason = "static_mesh_factory_unavailable"
    else
        capability.uint16 = identity.uint16_indices == true
        capability.uint32 = identity.uint32_indices == true
        capability.enabled = capability.uint16 or capability.uint32
        capability.reason = capability.enabled
            and nil or "index_width_unavailable"
    end
    self._static_textured_index_capability = capability
    return capability
end

function StaticExact.part_ranges_cover_source(part_ranges, source_count)
    if part_ranges == nil then
        return true
    end
    if type(part_ranges) ~= "table" or #part_ranges == 0
        or #part_ranges % 3 ~= 0 then
        return false
    end
    local expected_first = 1
    for index = 1, #part_ranges, 3 do
        local part_id = rawget(part_ranges, index)
        local first = tonumber(rawget(part_ranges, index + 1))
        local count = tonumber(rawget(part_ranges, index + 2))
        if part_id == nil
            or first == nil or first ~= math.floor(first)
            or count == nil or count <= 0 or count ~= math.floor(count)
            or count % 3 ~= 0
            or first ~= expected_first then
            return false
        end
        expected_first = first + count
        if expected_first - 1 > source_count then
            return false
        end
    end
    return expected_first == source_count + 1
end

function StaticExact.ineligible_reason(
    renderer, batch, source_vertex_count, reuse_by_key,
    defer_mesh_creation, capture_cpu_vertices, immutable_static)
    if immutable_static ~= true then
        return "not_immutable"
    end
    if renderer.enable_static_textured_indexing == false then
        return "disabled"
    end
    if reuse_by_key ~= nil then
        return "reuse_enabled"
    end
    if defer_mesh_creation == true then
        return "mesh_deferred"
    end
    if capture_cpu_vertices == true then
        return "cpu_capture"
    end
    if batch.source_kind == "SurfaceGui" then
        return "surface_gui"
    end
    if batch.source_transparent_part == true
        or batch.transparent == true
        or batch.surface_route == "transparent_blend" then
        return "transparent"
    end
    if source_vertex_count > StaticExact.source_vertex_limit then
        return "source_vertex_limit"
    end
    if source_vertex_count % 3 ~= 0 then
        return "triangle_alignment"
    end
    if not StaticExact.part_ranges_cover_source(
        batch.part_ranges, source_vertex_count) then
        -- Partial range metadata is valid for the legacy incremental-release
        -- path, but cannot partition a compact base buffer safely. keep that
        -- batch flat rather than allowing one part to share mutable vertices
        -- with another
        return "part_ranges_not_dense"
    end
    local capability = renderer:_get_static_textured_index_capability()
    if capability.enabled ~= true then
        return capability.reason or "backend_capability_unavailable"
    end
    return nil
end

function StaticExact.create_backend_batch(
    renderer, batch, bounds, source_vertex_count, packed,
    compacted, fallback_reason)
    local backend = renderer._render_backend
    local create = backend and (
        backend.create_static_mesh_batch or backend.create_static_batch)
    if type(create) ~= "function" then
        return nil, "static mesh factory unavailable"
    end

    local vertex_data = compacted and compacted.vertex_data or packed
    local vertex_count = compacted and compacted.vertex_count
        or source_vertex_count
    local spec = {
        base_vertex_format = renderer._textured_vertex_format,
        vertex_data = vertex_data,
        vertex_count = vertex_count,
        source_vertex_count = source_vertex_count,
        vertex_stride_bytes = StaticExact.vertex_stride_bytes,
        indices = compacted and compacted.indices or nil,
        indices_tsize = compacted and compacted.indices_tsize or nil,
        mode = "triangles",
        usage = "static",
        kind = compacted
            and "rbx_exact_static_textured"
            or "rbx_flat_static_textured_fallback",
        opaque = true,
        textured = true,
        texture = batch.texture or renderer._white_texture,
        bound = bounds,
        fallback = fallback_reason ~= nil,
        fallback_reason = fallback_reason,
    }
    local ok, resource_or_error = pcall(create, backend, spec)
    if not ok or not resource_or_error
        or not resource_or_error.draw_mesh then
        return nil, resource_or_error
            or "Menori static resource returned no draw mesh"
    end
    return resource_or_error
end

function StaticExact.note_index_success(stats, compacted)
    stats.indexed_batch_count = stats.indexed_batch_count + 1
    if compacted.indices_tsize == 2 then
        stats.uint16_batch_count = stats.uint16_batch_count + 1
    else
        stats.uint32_batch_count = stats.uint32_batch_count + 1
    end
    if compacted.part_compact_ranges ~= nil then
        stats.partitioned_batch_count =
            stats.partitioned_batch_count + 1
    end
    stats.base_vertex_count =
        stats.base_vertex_count + compacted.vertex_count
    stats.index_count = stats.index_count + compacted.index_count
    stats.uploaded_vertex_bytes =
        stats.uploaded_vertex_bytes + compacted.compact_vertex_bytes
    stats.uploaded_index_bytes =
        stats.uploaded_index_bytes + compacted.index_bytes
    stats.uploaded_bytes =
        stats.uploaded_bytes + compacted.indexed_bytes
    stats.bytes_saved = stats.bytes_saved + compacted.bytes_saved
end

function StaticExact.note_flat_fallback(
    stats, source_vertex_count, reason, backend_failure)
    local bytes = source_vertex_count * StaticExact.vertex_stride_bytes
    stats.flat_fallback_count = stats.flat_fallback_count + 1
    stats.base_vertex_count = stats.base_vertex_count + source_vertex_count
    stats.uploaded_vertex_bytes = stats.uploaded_vertex_bytes + bytes
    stats.uploaded_bytes = stats.uploaded_bytes + bytes
    if backend_failure then
        stats.backend_failure_fallback_count =
            stats.backend_failure_fallback_count + 1
    end
    StaticExact.note_reason(
        stats, "fallback_reasons", reason)
end

function StaticExact.snapshot(source)
    source = type(source) == "table" and source or {}
    local snapshot = {}
    for key, value in pairs(source) do
        if type(value) == "table" then
            local copy = {}
            for child_key, child_value in pairs(value) do
                copy[child_key] = child_value
            end
            snapshot[key] = copy
        else
            snapshot[key] = value
        end
    end
    return snapshot
end

function get_scaled_bounds_extent(bounds, scale_x, scale_y, scale_z)
    local safe_bounds = bounds or UNIT_PART_BOUNDS
    return math.max(
        math.abs((safe_bounds.max_x or 0.5) - (safe_bounds.min_x or -0.5)) * math.abs(scale_x or 1),
        math.abs((safe_bounds.max_y or 0.5) - (safe_bounds.min_y or -0.5)) * math.abs(scale_y or 1),
        math.abs((safe_bounds.max_z or 0.5) - (safe_bounds.min_z or -0.5)) * math.abs(scale_z or 1)
    )
end

function RBX._get_render_family(part, mesh_data)
    if is_csg_part_class(part and part.ClassName) then
        return "csg"
    end

    if type(part) == "table" and part.MeshOwner == "CylinderMesh" then
        return "decorative_builtin"
    end

    if type(part) == "table" and part.MeshOwner == "SpecialMesh" then
        local mesh_type = normalize_special_mesh_type(part.SpecialMeshType, part.MeshId)
        if mesh_type == "FileMesh" then
            return "decorative_filemesh"
        end
        if mesh_type == nil then
            return "primitive"
        end
        return "decorative_builtin"
    end

    if type(part) == "table" and part.ClassName == "MeshPart" then
        return "mesh_asset"
    end

    if type(mesh_data) == "table" and (mesh_data.source_kind == "csg_mesh" or mesh_data.source_kind == "csg_physics") then
        return "csg"
    end

    return "primitive"
end

-- hoisted: the inline literal allocated a fresh table per call, per face per part at map load
local DECAL_FAMILY_DEPTH_BIAS_SCALE = {
    primitive = 1.0,
    decorative_builtin = 1.05,
    decorative_filemesh = 1.1,
    mesh_asset = 1.1,
    csg = 1.15,
}

function RBX._get_dynamic_depth_bias(renderer, category, part, extent, mesh_data)
    if category == "decal" then
        local configured = math.max(0, tonumber(renderer and renderer.decal_depth_bias) or 0)
        if configured <= 0 then
            return 0
        end

        local family = RBX._get_render_family(part, mesh_data)
        local family_scale = DECAL_FAMILY_DEPTH_BIAS_SCALE[family] or 1.0

        return clamp(configured * family_scale, 0, 0.0015)
    end
    if category == "mesh" then
        return clamp(tonumber(renderer and renderer.mesh_depth_bias) or 0, 0, 0.0005)
    end
    if category == "material" then
        return clamp(tonumber(renderer and renderer.material_depth_bias) or 0, 0, 0.0005)
    end
    return 0
end

