    self._active_near_clip = self.camera.near_clip
    self._active_far_clip = self.camera.far_clip
    self._projection_flip_y = 1
    self._last_width = 0
    self._last_height = 0

    self:set_sun_direction(self.sun_direction[1], self.sun_direction[2], self.sun_direction[3])
    self:_load_skybox(DEFAULT_SKYBOX)
    checkpoint('renderer:sky-ready')

    if type(options.map_path) == "string" and trim(options.map_path) ~= "" then
        -- opt-in: time-slices the build across update() ticks instead of freezing ~17s. poll is_map_loading()
        if options.async_map_load and self.load_map_async then
            -- parse on main: cyclic/shared refs cant cross a love.thread channel. only the build is sliced
            local started, status_or_err = self:load_map_async(options.map_path, {
                parse_on_main = true,
                on_complete = options.on_map_load_complete,
                build_slice_seconds = options.async_map_build_slice_seconds,
                skip_workspace_subtrees = options.skip_workspace_subtrees,
            })
            if not started then
                pcall(public_datamodel.Destroy, public_datamodel)
                return nil, status_or_err
            end
        else
            -- optional per-project loading visual drawn from the sync pump
            if type(options.sync_load_draw) == "function" then
                self.sync_load_draw = options.sync_load_draw
            end
            local ok, err = self:load_map(options.map_path, {
                skip_workspace_subtrees = options.skip_workspace_subtrees,
            })
            self.sync_load_draw = nil
            if not ok then
                pcall(public_datamodel.Destroy, public_datamodel)
                return nil, err
            end
        end
    end

    RBX._active_datamodel = public_datamodel
    return public_datamodel
end

-- the default path retains synchronous behavior. optional cooperative loading
-- records native handles before any yield and publishes only a complete owner
function RBX.new(options, loading)
    if loading==nil then return RBX._construct(options)end
    local Owner=runtime_require('loading_owner.lua')
    local owner=Owner.new(loading)
    local ok,world,err=xpcall(function()return RBX._construct(options,owner)end,debug.traceback)
    if ok and world then
        local committed,errors=owner:commit()
        if committed then return world end
        err='Constructor staging release failed: '..table.concat(errors,'; ')
    elseif not ok then err=world end
    local _,cleanup_errors=owner:cancel()
    if cleanup_errors and #cleanup_errors>0 then err=tostring(err)..'\nConstructor cleanup: '..table.concat(cleanup_errors,'; ')end
    if not ok then error(err,0)end
    return nil,err
end

function RBX:set_sun_direction(x, y, z)
    local nx, ny, nz = normalize_or_fallback(x or 0.4, y or 1.0, z or 0.25, 0.4, 1.0, 0.25)
    if self.sun_direction[1] ~= nx or self.sun_direction[2] ~= ny or self.sun_direction[3] ~= nz then
        self.sun_direction[1] = nx
        self.sun_direction[2] = ny
        self.sun_direction[3] = nz
        if self.lighting_state then
            self.lighting_state.sun_direction = { nx, ny, nz }
            self.lighting_state.light_direction = { nx, ny, nz }
            self:_rebuild_lighting_uniform_pack()
        end
        self._lighting_uniform_revision = (self._lighting_uniform_revision or 0) + 1
    end
end

function RBX:_rebuild_fast_common_shader_set()
    local shaders = {
        [self._fast_textured_shader] = true,
        [self._opaque_fast_textured_shader] = true,
        [self._alpha_fast_textured_shader] = true,
        [self._surface_overlay_fast_textured_shader] = true,
    }
    if self.high_fps_shaders then
        shaders[self._instanced_shader] = true
        shaders[self._static_shader] = true
    end
    self._fast_common_shader = shaders
end

-- the regular receiver shaders retain a dynamic Atmosphere branch even when
-- a map has no Atmosphere instance. this walks only prepared textured items
-- on the rare representation switch, it never becomes a per-frame census
function RBX:_refresh_atmosphere_textured_shader_bindings()
    local seen = {}
    local rebound = 0
    local function visit_item(item)
        if type(item) ~= "table" or seen[item] or item.shader == nil then
            return
        end
        seen[item] = true
        local before = item.shader
        self:_select_textured_shader_for_batch(
            item, item.source_transparent_part == true)
        if item.shader ~= before then
            rebound = rebound + 1
        end
    end
    local function visit_list(list)
        for index = 1, #(list or {}) do
            visit_item(list[index])
        end
    end
    local function visit_chunk(chunk)
        if type(chunk) ~= "table" then return end
        visit_list(chunk.textured_batches)
        visit_list(chunk.overlay_textured_batches)
        visit_list(chunk.transparent_draw_items)
        visit_list(chunk.surface_gui_batches)
    end
    for index = 1, #(self._scene_chunks or {}) do
        visit_chunk(self._scene_chunks[index])
    end
    for _, chunk in pairs(self._dormant_dynamic_scene_chunk_map or {}) do
        visit_chunk(chunk)
    end
    for index = 1, #(self._settled_merge_chunks or {}) do
        visit_chunk(self._settled_merge_chunks[index])
    end
    visit_chunk(self._settled_merge_chunk)
    local pending = self._settled_merge_pending
    if type(pending) == "table" then
        for index = 1, #(pending.chunks or {}) do
            visit_chunk(pending.chunks[index])
        end
        visit_chunk(pending.current_chunk or pending.chunk)
    end
    visit_list(self._textured_batches)
    visit_list(self._mega_textured_batches)
    visit_list(self._mega_overlay_textured_batches)
    visit_list(self._transparent_draw_items)
    visit_list(self._visible_textured_batches)
    visit_list(self._visible_overlay_textured_batches)
    visit_list(self._visible_transparent_draw_items)
    if self._sever_transparent_textured_range_groups then
        self:_sever_transparent_textured_range_groups()
    end
    if self._invalidate_scene_frame_packet_state then
        self:_invalidate_scene_frame_packet_state()
    end
    self._transparent_sort_cache_state = nil
    self._atmosphere_no_receiver_rebound_items =
        (self._atmosphere_no_receiver_rebound_items or 0) + rebound
    return rebound
end

function RBX:_install_atmosphere_receiver_programs(programs, variant)
    local fields = self._atmosphere_receiver_shader_fields
    if type(programs) ~= "table" or type(fields) ~= "table"
        or #programs ~= #fields then
        return false
    end
    local changed = false
    for index = 1, #fields do
        local field = fields[index]
        if self[field] ~= programs[index] then
            self[field] = programs[index]
            changed = true
        end
    end
    self._atmosphere_receiver_variant = variant
    if not changed then
        return false
    end
    self:_rebuild_fast_common_shader_set()
    -- Uniform caches key by native shader identity. Recreate the bounded maps
    -- so a fresh receiver cannot inherit an earlier program's payload
    self._common_camera_uniform_send_state = {}
    self._common_lighting_uniform_send_state = {}
    self._lighting_debug_uniform_send_state = {}
    self._textured_uniform_states = nil
    self._minimal_textured_common_uniform_send_state = nil
    self._rigid_chunk_uniform_states = nil
    self._local_light_uniform_support = {}
    self._local_light_uniform_state = {}
    self._local_light_uniform_uploaded_counts = {}
    self._local_light_uniform_packet_shader_support = {}
    self._local_light_uniform_packet_available = false
    self._local_light_uniform_packet_last_shader_error = nil
    self:_refresh_atmosphere_textured_shader_bindings()
    self._atmosphere_no_receiver_variant_switches =
        (self._atmosphere_no_receiver_variant_switches or 0) + 1
    return true
end

function RBX:_sync_no_atmosphere_receiver_variant(state)
    if self.no_atmosphere_receiver_variant ~= true
        or self._atmosphere_receiver_supported == false
        or self._atmosphere_shader_supported == false then
        return false
    end
    -- Face-array retention has a separate receiver program. keep the ordinary
    -- receiver cohort full while that path is active, but never let this
    -- eligibility decision prevent restoration after a live Atmosphere write
    local wants_no_atmosphere = state and state.atmosphere_present ~= true
        and self.retain_face_texture_array ~= true
    if not wants_no_atmosphere then
        return self:_install_atmosphere_receiver_programs(
            self._atmosphere_full_receiver_programs, "full")
    end
    local programs = self._atmosphere_no_receiver_programs
    if not programs then
        local stripped_sources = {}
        for index = 1, #(self._atmosphere_receiver_sources or {}) do
            stripped_sources[index] = RBX._without_atmosphere_glsl(
                self._atmosphere_receiver_sources[index])
        end
        self._atmosphere_no_receiver_compile_attempts =
            (self._atmosphere_no_receiver_compile_attempts or 0) + 1
        local compile_error
        programs, compile_error = RBX._try_compile_shader_group(stripped_sources)
        if not programs then
            self._atmosphere_no_receiver_variant_failure =
                tostring(compile_error or "unknown shader compiler failure")
            return false
        end
        self._atmosphere_no_receiver_programs = programs
    end
    return self:_install_atmosphere_receiver_programs(
        programs, "no_atmosphere")
end

function RBX:apply_lighting_settings(settings)
    if not settings then
        return
    end

    local state = settings.kind == "LightingState" and settings or RBX._build_lighting_state(settings)
    self.lighting_state = state
    if state.sun_direction then
        self.sun_direction = clone3(state.sun_direction)
    end
    self.sun_color = {
        clamp(1.0 + ((state.color_shift_top and state.color_shift_top[1]) or 0) * 0.45, 0, 1.5),
        clamp(1.0 + ((state.color_shift_top and state.color_shift_top[2]) or 0) * 0.45, 0, 1.5),
        clamp(1.0 + ((state.color_shift_top and state.color_shift_top[3]) or 0) * 0.45, 0, 1.5),
    }
    self.sky_color = clone3(state.sky_color)
    self.ground_color = clone3(state.ground_color)
    self.fog_color = clone3(state.fog_color)
    self.ambient = state.ambient or self.ambient
    self.diffuse_strength = state.diffuse_strength or self.diffuse_strength
    self.specular_strength = state.specular_strength or self.specular_strength
    self.rim_strength = state.rim_strength or self.rim_strength
    self:_rebuild_lighting_uniform_pack()
    self:_sync_no_atmosphere_receiver_variant(state)

    self._lighting_uniform_revision = (self._lighting_uniform_revision or 0) + 1
    self.lighting_loaded = true
    self.lighting_info = state
    -- re-blend so env color tracks clocktime w/o re-sampling texels
    if self._refresh_sky_environment_average_color then
        self:_refresh_sky_environment_average_color()
    end
    -- the caster list depends only on the part set and GlobalShadows -- NOT on
    -- clock/sun/colors. Rebuilding it on every lighting write meant a full O(parts)
    -- scan per ClockTime tick (~30-300ms hitches every 0.28s on a 63k-part map with
    -- a day/night clock). Scene builds refresh the list on part changes, here we
    -- only rebuild when GlobalShadows actually flips
    if self._rebuild_shadow_caster_list then
        local gs = state.global_shadows ~= false
        if self._shadow_casters_built_for_gs ~= gs then
            self._shadow_casters_built_for_gs = gs
            self:_rebuild_shadow_caster_list()
        end
    end
end

local LIGHTING_PROPERTY_ALIASES = {
    Ambient = "ambient",
    ambient = "ambient",
    OutdoorAmbient = "outdoor_ambient",
    outdoor_ambient = "outdoor_ambient",
    Brightness = "brightness",
    brightness = "brightness",
    ClockTime = "clock_time",
    clock_time = "clock_time",
    TimeOfDay = "time_of_day",
    time_of_day = "time_of_day",
    GeographicLatitude = "geographic_latitude",
    geographic_latitude = "geographic_latitude",
    GlobalShadows = "global_shadows",
    global_shadows = "global_shadows",
    ColorShift_Top = "color_shift_top",
    color_shift_top = "color_shift_top",
    ColorShift_Bottom = "color_shift_bottom",
    color_shift_bottom = "color_shift_bottom",
    ExposureCompensation = "exposure_compensation",
    exposure_compensation = "exposure_compensation",
    EnvironmentDiffuseScale = "environment_diffuse_scale",
    environment_diffuse_scale = "environment_diffuse_scale",
    EnvironmentSpecularScale = "environment_specular_scale",
    environment_specular_scale = "environment_specular_scale",
    FogStart = "fog_start",
    fog_start = "fog_start",
    FogEnd = "fog_end",
    fog_end = "fog_end",
    FogColor = "fog_color",
    fog_color = "fog_color",
    ShadowSoftness = "shadow_softness",
    shadow_softness = "shadow_softness",
    LightingStyle = "lighting_style",
    PrioritizeLightingQuality = "prioritize_lighting_quality",
    lighting_style = "lighting_style",
    Technology = "technology",
    technology = "technology",
    Outlines = "outlines",
    outlines = "outlines",
    ColorCorrection = "color_correction",
    color_correction = "color_correction",
    ColorCorrectionEffect = "color_correction",
}

-- Shape-checks a runtime ColorCorrection write into the parser's
-- color_correction_settings shape (_build_lighting_uniform_pack reads
-- Enabled/Brightness/Contrast/Saturation/TintColor and clamps the values)
-- returns nil for a reset, a normalized copy for a table, nil+error for junk
local function normalize_color_correction_override(value)
    if value == nil then
        return nil
    end
    if type(value) ~= "table" then
        return nil, "ColorCorrection expects a table {Brightness=, Contrast=, Saturation=, TintColor=} or nil"
    end
    local tint = value.TintColor or value.tint_color
    local tint_rgb
    if tint ~= nil then
        if type(tint) ~= "table" then
            return nil, "ColorCorrection.TintColor expects a table color"
        end
        tint_rgb = {
            tonumber(tint[1] or tint.r or tint.R) or 1,
            tonumber(tint[2] or tint.g or tint.G) or 1,
            tonumber(tint[3] or tint.b or tint.B) or 1,
        }
    end
    return {
        Enabled = value.Enabled ~= false,
        Brightness = tonumber(value.Brightness or value.brightness) or 0,
        Contrast = tonumber(value.Contrast or value.contrast) or 0,
        Saturation = tonumber(value.Saturation or value.saturation) or 0,
        TintColor = tint_rgb,
    }
end

local function color_correction_override_equal(a, b)
    if a == nil or b == nil then
        return a == b
    end
    if a.Enabled ~= b.Enabled
        or a.Brightness ~= b.Brightness
        or a.Contrast ~= b.Contrast
        or a.Saturation ~= b.Saturation then
        return false
    end
    local at, bt = a.TintColor, b.TintColor
    if (at == nil) ~= (bt == nil) then
        return false
    end
    if at and bt and (at[1] ~= bt[1] or at[2] ~= bt[2] or at[3] ~= bt[3]) then
        return false
    end
    return true
end

-- Lossless authored inputs for rebuilding one Lighting facet.  keeping this
-- in one place prevents a live Atmosphere edit from dropping the map's Sky,
-- post effects, legacy fog range, or day/night controls
function RBX._lighting_state_to_raw(current_state)
    current_state = current_state or {}
    local raw = {
        source = current_state.source or "lighting",
        ambient = current_state.ambient_color,
        outdoor_ambient = current_state.outdoor_ambient,
        brightness = current_state.brightness,
        clock_time = current_state.clock_time,
        time_of_day = current_state.time_of_day,
        geographic_latitude = current_state.geographic_latitude,
        global_shadows = current_state.global_shadows,
        color_shift_top = current_state.color_shift_top,
        color_shift_bottom = current_state.color_shift_bottom,
        exposure_compensation = current_state.exposure_compensation,
        environment_diffuse_scale = current_state.environment_diffuse_scale,
        environment_specular_scale = current_state.environment_specular_scale,
        fog_color = current_state.fog_color,
        fog_start = current_state.fog_start,
        fog_end = current_state.fog_end,
        shadow_softness = current_state.shadow_softness,
        lighting_style = current_state.lighting_style,
        prioritize_lighting_quality = current_state.prioritize_lighting_quality,
        technology = current_state.technology,
        outlines = current_state.outlines,
        sky = current_state.sky,
        post_effects = current_state.post_effects,
    }
    if current_state.atmosphere then
        raw.atmosphere = current_state.atmosphere
        raw.atmosphere_present = true
    elseif current_state.atmosphere_present == true then
        raw.atmosphere_present = true
    end
    return raw
end

function RBX._atmosphere_state_equal(a, b)
    if a == nil or b == nil then
        return a == b
    end
    local ac, bc = a.color, b.color
    local ad, bd = a.decay, b.decay
    return tonumber(a.density) == tonumber(b.density)
        and tonumber(a.offset) == tonumber(b.offset)
        and tonumber(a.haze) == tonumber(b.haze)
        and tonumber(a.glare) == tonumber(b.glare)
        and ac and bc
        and ac[1] == bc[1] and ac[2] == bc[2] and ac[3] == bc[3]
        and ad and bd
        and ad[1] == bd[1] and ad[2] == bd[2] and ad[3] == bd[3]
end

-- DataModel Atmosphere lifecycle seam. `settings == nil` removes the effective
-- child and therefore restores legacy Lighting.Fog*. Identical facade writes
-- return before state construction, uniform packing, or revision advancement
function RBX:set_atmosphere_settings(settings)
    local current_state = self.lighting_state
        or RBX._build_lighting_state({ source = "default_lighting" })
    local incoming
    if settings ~= nil then
        local normalized = RBX._atmosphere.normalize(settings)
        incoming = {
            density = normalized.density,
            offset = normalized.offset,
            color = {
                normalized.color[1], normalized.color[2], normalized.color[3],
            },
            decay = {
                normalized.decay[1], normalized.decay[2], normalized.decay[3],
            },
            haze = normalized.haze,
            glare = normalized.glare,
        }
    end
    if RBX._atmosphere_state_equal(current_state.atmosphere, incoming)
        and ((incoming ~= nil) == (current_state.atmosphere_present == true)) then
        return false
    end

    local raw = RBX._lighting_state_to_raw(current_state)
    raw.atmosphere = incoming
    raw.atmosphere_present = incoming ~= nil
    self:apply_lighting_settings(RBX._build_lighting_state(raw))
    return true
end

-- Event-driven child publication. only the small Lighting child descriptor set
-- is compared, no per-frame scene traversal or geometry rebake is involved
local function lighting_descriptor_equal(a, b)
    if a == b then return true end
    if type(a) ~= "table" or type(b) ~= "table" then return false end
    for k, v in pairs(a) do
        if k ~= "source" and not lighting_descriptor_equal(v, b[k]) then return false end
    end
    for k in pairs(b) do if k ~= "source" and a[k] == nil then return false end end
    return true
end

function RBX:set_lighting_children(post_effects, sky)
    local state = self.lighting_state
    if not state then return false end
    if self._runtime_color_correction then
        self._map_authored_color_correction = post_effects.color_correction
        post_effects.color_correction = self._runtime_color_correction
    end
    local sky_changed = not lighting_descriptor_equal(state.sky, sky)
    if not self._lighting_children_pending and not sky_changed
        and lighting_descriptor_equal(state.post_effects or {}, post_effects) then return false end
    local raw = RBX._lighting_state_to_raw(state)
    raw.post_effects, raw.sky = post_effects, sky
    -- a failed resource publication must not turn an identical retry into a
    -- no-op. this marker owns no resources and is committed only after success
    local retry = self._lighting_children_pending
    self._lighting_children_pending = true
    if sky_changed or retry then self:_load_skybox(sky) end
    self:apply_lighting_settings(RBX._build_lighting_state(raw))
    self._lighting_children_pending = nil
    return true
end

function RBX:set_lighting_property(name, value)
    local key = LIGHTING_PROPERTY_ALIASES[name or ""]
    if not key then
        return false, "unknown lighting property: " .. tostring(name)
    end
    local current_state = self.lighting_state or RBX._build_lighting_state({ source = "default_lighting" })
    local raw = RBX._lighting_state_to_raw(current_state)
    if key == "color_correction" then
        -- Runtime override for the frame ColorCorrection pass. nil resets to
        -- the map-authored effect. Rides the same carry-forward + full-state
        -- rebuild as every other lighting property, the dedupe below keeps
        -- repeated identical writes O(1), matching clock_time's epsilon guard
        local override, invalid = normalize_color_correction_override(value)
        if invalid then
            return false, invalid
        end
        local base = type(current_state.post_effects) == "table" and current_state.post_effects or nil
        local live_cc = base and base.color_correction or nil
        -- identity check: our override is only "live" if the current state still
        -- carries the exact table we installed (a map load replaces the state
        -- wholesale and _reset_map_lighting_to_defaults clears the bookkeeping)
        local override_live = self._runtime_color_correction ~= nil
            and live_cc == self._runtime_color_correction
        if override == nil then
            if not override_live then
                -- never set, or already reset: the live state is map-authored
                self._runtime_color_correction = nil
                self._map_authored_color_correction = nil
                return true
            end
            local merged = {}
            if base then
                for k, v in pairs(base) do merged[k] = v end
            end
            merged.color_correction = self._map_authored_color_correction
            self._runtime_color_correction = nil
            self._map_authored_color_correction = nil
            raw.post_effects = merged
        else
            if override_live and color_correction_override_equal(self._runtime_color_correction, override) then
                return true -- identical write: skip the full lighting-state rebuild
            end
            if not override_live then
                -- first override since load: remember the map-authored effect so
                -- a nil write can restore it (bloom/blur/etc. stay untouched)
                self._map_authored_color_correction = live_cc
            end
            local merged = {}
            if base then
                for k, v in pairs(base) do merged[k] = v end
            end
            merged.color_correction = override
            self._runtime_color_correction = override
            raw.post_effects = merged
        end
        self:apply_lighting_settings(RBX._build_lighting_state(raw))
        return true
    end
    -- setting either must clear the other
    if key == "clock_time" then
        -- only identical writes are no-ops, small authored clock changes remain authoritative
        local current = tonumber(current_state.clock_time)
        local incoming = tonumber(value)
        if current and incoming and current == incoming then
            return true
        end
        raw.time_of_day = nil
    elseif key == "time_of_day" then
        raw.clock_time = nil
    end
    raw[key] = value
    self:apply_lighting_settings(RBX._build_lighting_state(raw))
    return true
end

function RBX:get_lighting_state_snapshot()
    local state = self.lighting_state or {}
    local function vec3(value)
        value = type(value) == "table" and value or { 0, 0, 0 }
        return { tonumber(value[1]) or 0, tonumber(value[2]) or 0, tonumber(value[3]) or 0 }
    end
    return {
        clock_time = tonumber(state.clock_time) or 14,
        time_of_day = tostring(state.time_of_day or "14:00:00"),
        brightness = tonumber(state.brightness) or 1,
        global_shadows = state.global_shadows == true,
        ambient = vec3(state.ambient_color),
        outdoor_ambient = vec3(state.outdoor_ambient),
        effective_ambient = vec3(state.effective_ambient),
        effective_outdoor_ambient = vec3(state.effective_outdoor_ambient),
        color_shift_top = vec3(state.color_shift_top),
        color_shift_bottom = vec3(state.color_shift_bottom),
        exposure_compensation = tonumber(state.exposure_compensation) or 0,
        exposure_multiplier = tonumber(state.exposure_multiplier) or 1,
        environment_diffuse_scale = tonumber(state.environment_diffuse_scale) or 0,
        environment_specular_scale = tonumber(state.environment_specular_scale) or 0,
        effective_environment_diffuse_scale = tonumber(state.effective_environment_diffuse_scale) or 0,
        effective_environment_specular_scale = tonumber(state.effective_environment_specular_scale) or 0,
        computed_environment_diffuse = vec3(state.computed_environment_diffuse),
        computed_environment_specular = vec3(state.computed_environment_specular),
        geographic_latitude = tonumber(state.geographic_latitude) or 35,
        sun_direction = vec3(state.sun_direction),
        moon_direction = vec3(state.moon_direction),
        sun_elevation = tonumber(state.sun_elevation) or 0,
        moon_elevation = tonumber(state.moon_elevation) or 0,
        light_direction = vec3(state.light_direction),
        daylight_factor = tonumber(state.daylight_factor) or 0,
        moonlight_factor = tonumber(state.moonlight_factor) or 0,
        night_factor = tonumber(state.night_factor) or 0,
        use_moon = state.use_moon == true,
        sky_color = vec3(state.sky_color),
        ground_color = vec3(state.ground_color),
        fog_color = vec3(state.fog_color),
        fog_start = tonumber(state.fog_start) or 0,
        fog_end = tonumber(state.fog_end) or 100000,
        fog_enabled = state.fog_enabled == true,
        legacy_fog_suppressed_by_atmosphere =
            state.legacy_fog_suppressed_by_atmosphere == true,
        shadow_softness = tonumber(state.shadow_softness) or 0,
        lighting_style = state.lighting_style,
        technology = state.technology,
        prioritize_lighting_quality = state.prioritize_lighting_quality,
        outlines = state.outlines,
        atmosphere_present = state.atmosphere_present == true,
        atmosphere_supported = state.atmosphere_supported == true,
        atmosphere = state.atmosphere and {
            density = tonumber(state.atmosphere.density) or 0,
            offset = tonumber(state.atmosphere.offset) or 0,
            color = vec3(state.atmosphere.color),
            decay = vec3(state.atmosphere.decay),
            haze = tonumber(state.atmosphere.haze) or 0,
            glare = tonumber(state.atmosphere.glare) or 0,
        } or nil,
        post_effects = state.post_effects,
        scene_revision = tonumber(self._lighting_uniform_revision) or 0,
        scene_lighting_hash = self._lighting_uniform_pack and self:_compute_lighting_pack_hash() or 0,
    }
end

function RBX:get_lighting_diagnostics()
    local state = self.lighting_state or {}
    local snapshot = self:get_lighting_state_snapshot()
    local sky_diag = self:get_sky_diagnostics()
    local light_diag = self:get_local_lights_diagnostics()
    local post_diag = self._post_process
        and self._post_process:diagnostics(state)
        or {
            requested = false,
            available = false,
            active = false,
            failure_reason = "post_process_not_initialized",
        }
    post_diag.material_hdr_output_active =
        self._frame_post_material_mode == true
    post_diag.last_target_error = self._last_post_target_error
    post_diag.last_resolve_error = self._last_post_resolve_error
    return {
        clock_time = snapshot.clock_time,
        time_of_day = snapshot.time_of_day,
        sun_direction = snapshot.sun_direction,
        moon_direction = snapshot.moon_direction,
        sun_elevation = snapshot.sun_elevation,
        moon_elevation = snapshot.moon_elevation,
        night_factor = snapshot.night_factor,
        daylight_factor = snapshot.daylight_factor,
        moonlight_factor = snapshot.moonlight_factor,
        use_moon = snapshot.use_moon,
        environment_diffuse_scale = snapshot.environment_diffuse_scale,
        environment_specular_scale = snapshot.environment_specular_scale,
        effective_environment_diffuse_scale = snapshot.effective_environment_diffuse_scale,
        effective_environment_specular_scale = snapshot.effective_environment_specular_scale,
        computed_environment_diffuse = snapshot.computed_environment_diffuse,
        computed_environment_specular = snapshot.computed_environment_specular,
        ambient = snapshot.ambient,
        outdoor_ambient = snapshot.outdoor_ambient,
        effective_ambient = snapshot.effective_ambient,
        effective_outdoor_ambient = snapshot.effective_outdoor_ambient,
        color_shift_top = snapshot.color_shift_top,
        color_shift_bottom = snapshot.color_shift_bottom,
        exposure_compensation = snapshot.exposure_compensation,
        global_shadows = snapshot.global_shadows,
        brightness = snapshot.brightness,
        fog_color = snapshot.fog_color,
        fog_start = snapshot.fog_start,
        fog_end = snapshot.fog_end,
        fog_enabled = snapshot.fog_enabled,
        legacy_fog_suppressed_by_atmosphere =
            snapshot.legacy_fog_suppressed_by_atmosphere,
        atmosphere_present = snapshot.atmosphere_present,
        atmosphere_supported = snapshot.atmosphere_supported,
        atmosphere = snapshot.atmosphere,
        post_effects = snapshot.post_effects,
        post_process = post_diag,
        lighting_style = snapshot.lighting_style,
        technology = snapshot.technology,
        prioritize_lighting_quality = snapshot.prioritize_lighting_quality,
        lighting_policy_limitations = {
            Technology = "preserved legacy value; no Roblox technology backend selection",
            LightingStyle = "preserved; renderer uses its existing lighting model",
            PrioritizeLightingQuality = "preserved; no Roblox distance/quality policy",
            OutdoorAmbient = "normal/contact-occlusion approximation when GlobalShadows is enabled; no voxel sky visibility",
            EnvironmentSpecularScale = "full material/primitive reflection approximation; legacy diffuse-only mesh routes omit reflections",
        },
        outlines = snapshot.outlines,
        scene_revision = snapshot.scene_revision,
        scene_lighting_hash = snapshot.scene_lighting_hash,
        lighting_uniform_sends_per_frame = self._frame_lighting_uniform_send_count or 0,
        sky_draw_ms_per_frame = self._frame_sky_draw_ms or 0,
        celestial_draw_ms_per_frame = self._frame_celestial_draw_ms or 0,
        celestial_draws_per_frame = self._frame_celestial_draw_count or 0,
        skybox_draw_calls_per_frame = self._frame_skybox_draw_call_count or 0,
        sky = sky_diag,
        local_lights = light_diag,
        shadows = self:get_shadow_diagnostics(),
        contact = self:get_contact_separation_diagnostics(),
    }
end

function RBX:_compute_lighting_pack_hash()
    local pack = self._lighting_uniform_pack
    if type(pack) ~= "table" then
        return 0
    end
    local h = 0
    for slot_index = 1, #pack do
        local slot = pack[slot_index]
        if type(slot) == "table" then
            for k = 1, 4 do
                h = (h * 1009 + math.floor((tonumber(slot[k]) or 0) * 65536 + 0.5)) % 2147483647
            end
        end
    end
    return h
end

local SYNTHETIC_LIGHT_ORIGIN = "synthetic"

function RBX:_sync_instanced_mesh_light_partition_requirement(light_count, dirty_on_change)
    local max_lights = math.max(
        0,
        math.min(
            4,
            math.floor(
                tonumber(self.max_lights_per_batch) or 4)))
    local span = math.max(
        1,
        math.floor(
            tonumber(self.local_light_cluster_supercell_span) or 2))
    local cell_size = math.max(
        8,
        tonumber(self.local_light_grid_cell_size) or 64)
    local partition_size = cell_size * span
    local required =
        self.enable_local_lights ~= false
        and max_lights > 0
        and math.max(0, tonumber(light_count) or 0) > max_lights
    local previous_required =
        self._instanced_mesh_requires_light_partition
    local previous_size =
        self._instanced_mesh_light_partition_size
    local previous_cell_size = self._instanced_mesh_light_cell_size
    local changed =
        previous_required ~= nil
        and (
            previous_required ~= required
            or (required and (previous_size ~= partition_size
                or previous_cell_size ~= cell_size))
        )

    self._instanced_mesh_requires_light_partition = required
    self._instanced_mesh_light_partition_size = partition_size
    -- Material primitives consume the raw grid cell, imported meshes its
    -- supercell product. Changing64x2 to32x4 must invalidate the former even
    -- though the latter retains the same128-stud partition width
    self._instanced_mesh_light_cell_size = cell_size
    if changed and dirty_on_change == true then
        -- the light-cell id is part of the repeated-mesh bucket identity
        -- Directly mutable renderer options and runtime-created lights must
        -- therefore rebuild groups when the topology gate changes
        self._parts_dirty = true
        self._parts_dirty_mode = "full"
    end
    return changed
end

function RBX:_make_synthetic_light(spec)
    spec = type(spec) == "table" and spec or {}
    local class_name = spec.class_name or spec.ClassName or "PointLight"
    if class_name ~= "PointLight" and class_name ~= "SpotLight" and class_name ~= "SurfaceLight" then
        return nil
    end
    local color = spec.color
    if type(color) ~= "table" then
        color = { 1, 1, 1 }
    end
    local color_r = clamp(tonumber(color[1] or color.r) or 1, 0, 1)
    local color_g = clamp(tonumber(color[2] or color.g) or 1, 0, 1)
    local color_b = clamp(tonumber(color[3] or color.b) or 1, 0, 1)
    local position = type(spec.position) == "table" and spec.position or { 0, 0, 0 }
    local px = tonumber(position[1] or position.x) or 0
    local py = tonumber(position[2] or position.y) or 0
    local pz = tonumber(position[3] or position.z) or 0
    local size = type(spec.size) == "table" and spec.size or {}
    local sx = tonumber(size[1] or size.x) or 2
    local sy = tonumber(size[2] or size.y) or 2
    local sz = tonumber(size[3] or size.z) or 2
    local entry = {
        class_name = class_name,
        name = spec.name or class_name,
        origin = SYNTHETIC_LIGHT_ORIGIN,
        enabled = spec.enabled ~= false,
        brightness = math.max(0, tonumber(spec.brightness) or 1),
        color = { color_r, color_g, color_b },
        color_r = color_r,
        color_g = color_g,
        color_b = color_b,
        shadows = spec.shadows == true,
        range = math.max(0, tonumber(spec.range) or (class_name == "PointLight" and 8 or 16)),
        angle = clamp(tonumber(spec.angle) or (class_name == "PointLight" and 0 or 90), 0, 180),
        face = spec.face or "Front",
        parent_kind = spec.parent_kind or "Part",
        parent_class = spec.parent_class or "Part",
        parent_name = spec.parent_name or "synthetic-emitter",
        parent_path = spec.parent_path or "Workspace.synthetic-emitter",
        parent_transparency = tonumber(spec.parent_transparency) or 0,
        parent_transparent_at_load = spec.parent_transparent_at_load == true,
        parent_transform_runtime = true,
        parent_transform = {
            x = px, y = py, z = pz,
            sx = sx, sy = sy, sz = sz,
            r00 = 1, r01 = 0, r02 = 0,
            r10 = 0, r11 = 1, r12 = 0,
            r20 = 0, r21 = 0, r22 = 1,
        },
    }
    return entry
end

function RBX:add_synthetic_local_light(spec)
    if self.enable_local_lights == false then
        return nil
    end
    local entry = self:_make_synthetic_light(spec)
    if not entry then
        return nil
    end
    self.local_lights = self.local_lights or {}
    entry.id = #self.local_lights + 1
    if self:_compute_local_light_world(entry) and entry.active then
        self.local_light_count = (self.local_light_count or 0) + 1
        if entry.shadows == true then
            self.local_light_shadow_request_count = (self.local_light_shadow_request_count or 0) + 1
        end
    end
    self.local_lights[entry.id] = entry
    self._local_light_revision = (self._local_light_revision or 0) + 1
    self:_rebuild_local_light_grid()
    self:_sync_instanced_mesh_light_partition_requirement(
        self.local_light_count or 0, true)
    return entry.id
end

function RBX:update_synthetic_local_light(id, props)
    if type(id) ~= "number" then
        return false
    end
    local entry = self.local_lights and self.local_lights[id]
    if not entry or entry.origin ~= SYNTHETIC_LIGHT_ORIGIN then
        return false
    end
    if type(props) == "table" then
        if props.position then
            local position = props.position
            entry.parent_transform.x = tonumber(position[1] or position.x) or entry.parent_transform.x
            entry.parent_transform.y = tonumber(position[2] or position.y) or entry.parent_transform.y
            entry.parent_transform.z = tonumber(position[3] or position.z) or entry.parent_transform.z
        end
        if props.brightness ~= nil then
            entry.brightness = math.max(0, tonumber(props.brightness) or 0)
        end
        if props.range ~= nil then
            entry.range = math.max(0, tonumber(props.range) or entry.range)
        end
        if props.angle ~= nil then
            entry.angle = clamp(tonumber(props.angle) or entry.angle, 0, 180)
        end
        if props.color then
            local color = props.color
            entry.color_r = clamp(tonumber(color[1] or color.r) or entry.color_r, 0, 1)
            entry.color_g = clamp(tonumber(color[2] or color.g) or entry.color_g, 0, 1)
            entry.color_b = clamp(tonumber(color[3] or color.b) or entry.color_b, 0, 1)
            entry.color = { entry.color_r, entry.color_g, entry.color_b }
        end
        if props.enabled ~= nil then
            entry.enabled = props.enabled == true
        end
        if props.shadows ~= nil then
            entry.shadows = props.shadows == true
        end
        if props.face then
            entry.face = props.face
        end
    end
    entry.dirty = true
    self._local_lights_dirty = true
    self._local_light_revision = (self._local_light_revision or 0) + 1
    return true
end

function RBX:remove_synthetic_local_lights()
    if type(self.local_lights) ~= "table" then
        return
    end
    local kept = {}
    local active_count = 0
    local shadow_count = 0
    for index = 1, #self.local_lights do
        local entry = self.local_lights[index]
        if entry and entry.origin ~= SYNTHETIC_LIGHT_ORIGIN then
            entry.id = #kept + 1
            kept[entry.id] = entry
            if entry.active then
                active_count = active_count + 1
                if entry.shadows == true then
                    shadow_count = shadow_count + 1
                end
            end
        end
    end
    self.local_lights = kept
    self.local_light_count = active_count
    self.local_light_shadow_request_count = shadow_count
    self._local_light_revision = (self._local_light_revision or 0) + 1
    self:_rebuild_local_light_grid()
    self:_sync_instanced_mesh_light_partition_requirement(
        active_count, true)
end

function RBX:set_lighting_debug_mode(mode)
    if mode == nil or mode == "" or mode == false then
        self._lighting_debug_mode = nil
        return
    end
    self._lighting_debug_mode = tostring(mode)
end

function RBX:get_lighting_debug_mode()
    return self._lighting_debug_mode
end

local SHADING_SEPARATION_DEBUG_VIEW_IDS = {
    off = 0,
    final = 0,
    part_id = 1,
    part = 1,
    batch_id = 2,
    batch = 2,
}

local function debug_hash_color(value)
    local text = tostring(value or "")
    local hash = 0
    for index = 1, #text do
        hash = (hash * 131 + text:byte(index)) % 2147483647
    end
    local r = ((hash % 251) / 250) * 0.72 + 0.18
    local g = (((math.floor(hash / 251)) % 251) / 250) * 0.72 + 0.18
    local b = (((math.floor(hash / 63001)) % 251) / 250) * 0.72 + 0.18
    return { clamp(r, 0.08, 0.95), clamp(g, 0.08, 0.95), clamp(b, 0.08, 0.95) }
end

function RBX:_part_batch_debug_token(part)
    if type(part) ~= "table" then
        return "nil"
    end
    local bounds = nil
    local ok, result = pcall(function()
        return self:_get_part_render_bounds(part)
    end)
    if ok then
        bounds = result
    end
    local cx, cy, cz = 0, 0, 0
    if bounds then
        cx = ((bounds.min_x or 0) + (bounds.max_x or 0)) * 0.5
        cy = ((bounds.min_y or 0) + (bounds.max_y or 0)) * 0.5
        cz = ((bounds.min_z or 0) + (bounds.max_z or 0)) * 0.5
    end
    local chunk_x, chunk_y, chunk_z = get_spatial_chunk_coords(self.visibility_cell_size or 96, cx, cy, cz)
    local geometry_key = get_runtime_part_render_geometry_key(part)
    local alpha_bucket = math.floor((get_runtime_render_alpha(part) or 1) * 16 + 0.5)
    local material = tostring(part.Material or "nil")
    local mesh_owner = tostring(part.MeshOwner or "")
    local texture_key = tostring(part.TextureContent or part.TextureId or part.MeshId or "")
    return table.concat({
        tostring(chunk_x), tostring(chunk_y), tostring(chunk_z),
        tostring(geometry_key), material, mesh_owner, texture_key, tostring(alpha_bucket),
    }, "|")
end

function RBX:_apply_shading_separation_debug_colors()
    local view_id = self._shading_separation_debug_view_id or 0
    for i = 1, #(self.parts or {}) do
        local part = self.parts[i]
        if part then
            if view_id == 1 then
                part._render_color_override = debug_hash_color(part._id or part._runtime_id or part._map_referent or i)
            elseif view_id == 2 then
                part._render_color_override = debug_hash_color(self:_part_batch_debug_token(part))
            else
                part._render_color_override = nil
            end
        end
    end
end

function RBX:set_shading_separation_debug_view(view)
    local key = type(view) == "string" and safe_lower(view) or tostring(view or "off")
    local view_id = SHADING_SEPARATION_DEBUG_VIEW_IDS[key] or tonumber(view) or 0
    view_id = clamp(view_id, 0, 2)
    local changed = self._shading_separation_debug_view_id ~= view_id
    self._shading_separation_debug_view_id = view_id
    self:_apply_shading_separation_debug_colors()
    if changed or view_id > 0 then
        self._parts_dirty = true
        self._parts_dirty_mode = "full"
    end
end

