function RBX:set_lighting_component_debug_view(view, light_type)
    local key = type(view) == "string" and safe_lower(view) or tostring(view or "final")
    local view_id = LIGHTING_COMPONENT_DEBUG_VIEW_IDS[key] or tonumber(view) or 0
    self._lighting_debug_view_id = clamp(view_id, 0, 17)
