-- Uniform ownership is per shader. Re-entering a static draw must clear the
-- previous dynamic pose even when it shares the same material state key
function RBX:_send_rigid_chunk_uniforms(shader,item)
    local states=self._rigid_chunk_uniform_states or{}
    self._rigid_chunk_uniform_states=states
    local state=states[shader]or{};states[shader]=state
    if state.supported==nil then state.supported=not shader.hasUniform or shader:hasUniform('uRigidEnabled')end
    if not state.supported then return end
    local pose=item and item.rigid_pose
    local enabled=pose and (pose.affine and 2 or 1) or 0
    if state.enabled~=enabled then
        shader:send('uRigidEnabled',enabled);self:_note_uniform_send()
        state.enabled=enabled
    end
    if pose and(state.pose~=pose or state.revision~=pose.revision)then
        shader:send('uRigidRows',unpack(pose.rows));self:_note_uniform_send()
        state.pose,state.revision=pose,pose.revision
    elseif not pose then state.pose,state.revision=nil,nil end
end

function RBX:_send_textured_draw_uniforms(item, shader)
    shader = shader or self:_get_textured_shader_for_item(item)
    self:_send_rigid_chunk_uniforms(shader,item)
    if rawequal(shader, self._constant_textured_shader) then
        self:_send_constant_textured_draw_uniforms(item, shader)
        return
    end
    if rawequal(shader, self._overlay_textured_shader) then
        self:_send_overlay_textured_draw_uniforms(item, shader)
        return
    end
    if rawequal(shader, self._face_array_overlay_shader) then
        self:_send_face_array_overlay_textured_draw_uniforms(item, shader)
        return
    end
    if rawequal(shader, self._opaque_fast_textured_shader) then
        self:_send_opaque_fast_textured_draw_uniforms(item, shader)
        return
    end
    if rawequal(shader, self._surface_overlay_fast_textured_shader) then
        self:_send_surface_overlay_fast_textured_draw_uniforms(item, shader)
        return
    end
    if rawequal(shader, self._fast_textured_shader) then
        self:_send_fast_textured_draw_uniforms(item, shader)
        return
    end
    if rawequal(shader, self._alpha_fast_textured_shader) then
        self:_send_fast_textured_draw_uniforms(item, shader)
        return
    end

    local cache = self:_get_textured_uniform_cache(shader)
    -- this is resource data, not part of the material key. two meshes sharing
    -- that key may have different alpha payloads, so publish before its return
    local vertex_alpha_is_one = item.vertex_alpha_is_one == true
    if cache.vertex_alpha_is_one ~= vertex_alpha_is_one then
        shader:send("uVertexAlphaIsOne", vertex_alpha_is_one)
        self:_note_uniform_send()
        cache.vertex_alpha_is_one = vertex_alpha_is_one
    end

    local uniform_state_key = item.uniform_state_key or item.key
    if uniform_state_key ~= nil and cache.uniform_state_key == uniform_state_key then
        return
    end
    cache.uniform_state_key = uniform_state_key

    local flip_v = item.flip_v and 1 or 0
    if cache.flip_v ~= flip_v then
        shader:send("uFlipV", flip_v)
        self:_note_uniform_send()
        cache.flip_v = flip_v
    end

    local flip_u = item.flip_u and 1 or 0
    if cache.flip_u ~= flip_u then
        shader:send("uFlipU", flip_u)
        self:_note_uniform_send()
        cache.flip_u = flip_u
    end

    local mesh_debug_mode = item.mesh_debug_mode_id
    if mesh_debug_mode == nil then
        mesh_debug_mode = RBX._get_mesh_debug_mode_id(item.mesh_debug_mode)
        item.mesh_debug_mode_id = mesh_debug_mode
    end
    if cache.mesh_debug_mode ~= mesh_debug_mode then
        shader:send("uMeshDebugMode", mesh_debug_mode)
        self:_note_uniform_send()
        cache.mesh_debug_mode = mesh_debug_mode
    end

    local use_material_maps = item.use_material_maps and 1 or 0
    if cache.use_material_maps ~= use_material_maps then
        shader:send("uUseMaterialMaps", use_material_maps)
        self:_note_uniform_send()
        cache.use_material_maps = use_material_maps
    end
    self:_send_textured_material_uniforms(item, shader, cache)

    local use_textured_lighting = item.use_textured_lighting ~= false and 1 or 0
    if cache.use_textured_lighting ~= use_textured_lighting then
        shader:send("uUseTexturedLighting", use_textured_lighting)
        self:_note_uniform_send()
        cache.use_textured_lighting = use_textured_lighting
    end

    local light_influence = clamp(tonumber(item.light_influence) or 1, 0, 1)
    if cache.light_influence ~= light_influence then
        shader:send("uLightInfluence", light_influence)
        self:_note_uniform_send()
        cache.light_influence = light_influence
    end

    local brightness = math.max(0, tonumber(item.brightness) or 1)
    if cache.brightness ~= brightness then
        shader:send("uBrightness", brightness)
        self:_note_uniform_send()
        cache.brightness = brightness
    end

    local use_normal_map = item.use_normal_map and 1 or 0
    if cache.use_normal_map ~= use_normal_map then
        shader:send("uUseNormalMap", use_normal_map)
        self:_note_uniform_send()
        cache.use_normal_map = use_normal_map
    end

    local detail_normal_mix = item.detail_normal_mix or 0
    if cache.detail_normal_mix ~= detail_normal_mix then
        shader:send("uDetailNormalMix", detail_normal_mix)
        self:_note_uniform_send()
        cache.detail_normal_mix = detail_normal_mix
    end

    local detail_contrast = item.detail_contrast or 1
    if cache.detail_contrast ~= detail_contrast then
        shader:send("uDetailContrast", detail_contrast)
        self:_note_uniform_send()
        cache.detail_contrast = detail_contrast
    end

    local texture_color_mix = item.texture_color_mix or 1
    if cache.texture_color_mix ~= texture_color_mix then
        shader:send("uTextureColorMix", texture_color_mix)
        self:_note_uniform_send()
        cache.texture_color_mix = texture_color_mix
    end

    local depth_bias = item.depth_bias or 0
    if cache.depth_bias ~= depth_bias then
        shader:send("uDepthBias", depth_bias)
        self:_note_uniform_send()
        cache.depth_bias = depth_bias
    end

    local ignore_texture_alpha = item.ignore_texture_alpha and 1 or 0
    if cache.ignore_texture_alpha ~= ignore_texture_alpha then
        shader:send("uIgnoreTextureAlpha", ignore_texture_alpha)
        self:_note_uniform_send()
        cache.ignore_texture_alpha = ignore_texture_alpha
    end

    local use_surface_appearance = item.surface_appearance == true and 1 or 0
    local mesh_layer = item.mesh_texture_layer
    local use_mesh_layer = mesh_layer and 1 or 0
    if cache.use_mesh_texture_layer ~= use_mesh_layer then
        shader:send("uUseMeshTextureLayer", use_mesh_layer)
        self:_note_uniform_send()
        cache.use_mesh_texture_layer = use_mesh_layer
    end
    if mesh_layer and cache.mesh_texture_layer ~= mesh_layer.texture then
        shader:send("uMeshTextureLayer", mesh_layer.texture)
        self:_note_uniform_send()
        cache.mesh_texture_layer = mesh_layer.texture
    end
    if cache.use_surface_appearance ~= use_surface_appearance then
        shader:send("uUseSurfaceAppearance", use_surface_appearance)
        self:_note_uniform_send()
        cache.use_surface_appearance = use_surface_appearance
    end
    local use_material_variant = item.material_variant_surface == true and 1 or 0
    if cache.use_material_variant ~= use_material_variant then
        shader:send("uUseMaterialVariant", use_material_variant)
        self:_note_uniform_send()
        cache.use_material_variant = use_material_variant
    end
    if use_surface_appearance > 0 then
        local alpha_mode = tonumber(item.surface_alpha_mode)
            or SurfaceAppearance.ALPHA_OVERLAY
        if cache.surface_alpha_mode ~= alpha_mode then
            shader:send("uSurfaceAlphaMode", alpha_mode)
            self:_note_uniform_send()
            cache.surface_alpha_mode = alpha_mode
        end
        local color_map_active = item.surface_color_map_active and 1 or 0
        if cache.surface_color_map_active ~= color_map_active then
            shader:send("uSurfaceColorMapActive", color_map_active)
            self:_note_uniform_send()
            cache.surface_color_map_active = color_map_active
        end
        local surface_color = item.surface_color or { 1, 1, 1 }
        local surface_color_key = table.concat({
            tostring(surface_color[1] or 1),
            tostring(surface_color[2] or 1),
            tostring(surface_color[3] or 1),
        }, ":")
        if cache.surface_color_key ~= surface_color_key then
            shader:send("uSurfaceColor", surface_color)
            self:_note_uniform_send()
            cache.surface_color_key = surface_color_key
        end
        local cutout_threshold = item.surface_route == "opaque_cutout"
            and clamp(tonumber(item.surface_cutout_threshold)
                or SurfaceAppearance.DEFAULT_CUTOUT_THRESHOLD, 0, 1)
            or -1
        if cache.surface_cutout_threshold ~= cutout_threshold then
            shader:send("uSurfaceCutoutThreshold", cutout_threshold)
            self:_note_uniform_send()
            cache.surface_cutout_threshold = cutout_threshold
        end
        local emissive_strength = math.max(
            0, tonumber(item.surface_emissive_strength) or 1)
        if cache.surface_emissive_strength ~= emissive_strength then
            shader:send("uSurfaceEmissiveStrength", emissive_strength)
            self:_note_uniform_send()
            cache.surface_emissive_strength = emissive_strength
        end
        local emissive_tint = item.surface_emissive_tint or { 1, 1, 1 }
        local emissive_tint_key = table.concat({
            tostring(emissive_tint[1] or 1),
            tostring(emissive_tint[2] or 1),
            tostring(emissive_tint[3] or 1),
        }, ":")
        if cache.surface_emissive_tint_key ~= emissive_tint_key then
            shader:send("uSurfaceEmissiveTint", emissive_tint)
            self:_note_uniform_send()
            cache.surface_emissive_tint_key = emissive_tint_key
        end
        local emissive_texture = item.emissive_texture or self._black_texture
        if cache.emissive_texture ~= emissive_texture then
            shader:send("uEmissiveMap", emissive_texture)
            self:_note_uniform_send()
            cache.emissive_texture = emissive_texture
        end
    end

    local normal_texture = item.normal_texture or self._flat_normal_texture
    if cache.normal_texture ~= normal_texture then
        shader:send("uNormalMap", normal_texture)
        self:_note_uniform_send()
        cache.normal_texture = normal_texture
    end

    local detail_normal_texture = item.detail_normal_texture or self._flat_normal_texture
    if cache.detail_normal_texture ~= detail_normal_texture then
        shader:send("uDetailNormalMap", detail_normal_texture)
        self:_note_uniform_send()
        cache.detail_normal_texture = detail_normal_texture
    end

    local roughness_texture = item.roughness_texture
        or (item.surface_appearance == true and self._roughness_half_texture)
        or self._white_texture
    if cache.roughness_texture ~= roughness_texture then
        shader:send("uRoughnessMap", roughness_texture)
        self:_note_uniform_send()
        cache.roughness_texture = roughness_texture
    end

    local metalness_texture = item.metalness_texture or self._black_texture
    if cache.metalness_texture ~= metalness_texture then
        shader:send("uMetalnessMap", metalness_texture)
        self:_note_uniform_send()
        cache.metalness_texture = metalness_texture
    end
end

function RBX:_sort_transparent_draw_items(items)
    items = items or self._transparent_draw_items
    if not items or #items <= 1 then
        return
    end

    local view_matrix = self._view_matrix
    if not view_matrix then
        return
    end
    local cache = self._transparent_sort_cache_state or {}
    local camera = self.camera.cframe
    local camera_x, camera_y, camera_z, look_x, look_y, look_z =
        get_camera_pose_components(camera)
    if cache.items == items
        and cache.item_count == #items
        and cache.visible_transparent_signature == self._visible_transparent_signature
        and cache.visible_scene_revision == self._visible_scene_revision
        and cache.dynamic_scene_revision == self._dynamic_scene_revision
        and cache.x == camera_x
        and cache.y == camera_y
        and cache.z == camera_z
        and cache.look_x == look_x
        and cache.look_y == look_y
        and cache.look_z == look_z then
        return
    end
    -- Transparent depth is exact, not a camera-motion LOD. Dynamic items can
    -- exchange order while keeping the same list identity/count/signature, and
    -- even a sub-threshold camera move can cross an overlap boundary. Sorting is
    -- cheap enough to invalidate on the exact pose and scene revisions
    self._transparent_sort_count = (self._transparent_sort_count or 0) + 1
    local vzx = view_matrix and view_matrix[9] or 0
    local vzy = view_matrix and view_matrix[10] or 0
    local vzz = view_matrix and view_matrix[11] or 1

    for i = 1, #items do
        local item = items[i]
        local bounds = item.bounds
        local sx = item.sort_x or (bounds and bounds.center_x) or 0
        local sy = item.sort_y or (bounds and bounds.center_y) or 0
        local sz = item.sort_z or (bounds and bounds.center_z) or 0
        local _, _, view_z = transform_point4(view_matrix, sx, sy, sz, 1)
        local nearest_depth = view_z
        if bounds and bounds.extent_x and bounds.extent_y and bounds.extent_z then
            local view_extent = math.abs(vzx) * bounds.extent_x +
                math.abs(vzy) * bounds.extent_y +
                math.abs(vzz) * bounds.extent_z
            nearest_depth = view_z + view_extent
        end
        item._sort_view_z = view_z
        item._sort_depth = nearest_depth
    end

    table.sort(items, function(a, b)
        if a._sort_depth == b._sort_depth then
            local ap = a.render_priority or 0
            local bp = b.render_priority or 0
            if ap ~= bp then
                return ap < bp
            end
            if a._sort_view_z ~= b._sort_view_z then
                return a._sort_view_z < b._sort_view_z
            end
            return (a.sort_id or 0) > (b.sort_id or 0)
        end
        return a._sort_depth < b._sort_depth
    end)

    self:_order_same_face_surface_gui_items(items)
    cache.items = items
    cache.item_count = #items
    cache.visible_transparent_signature = self._visible_transparent_signature
    cache.visible_scene_revision = self._visible_scene_revision
    cache.dynamic_scene_revision = self._dynamic_scene_revision
    cache.x, cache.y, cache.z = camera_x, camera_y, camera_z
    cache.look_x, cache.look_y, cache.look_z = look_x, look_y, look_z
    self._transparent_sort_cache_state = cache
end

local function normalized_transparent_depth_compare(item)
    return item and item.depth_compare == "always" and "always"
        or (item and item.depth_compare == "lequal" and "lequal" or "less")
end

local TRANSPARENT_ADJACENCY_HASH_MOD = 2147483647

local function transparent_adjacency_hash(text, multiplier, seed)
    local hash = seed or 0
    text = tostring(text or "")
    for index = 1, #text do
        hash = (
            hash * multiplier + text:byte(index)
        ) % TRANSPARENT_ADJACENCY_HASH_MOD
    end
    return hash
end

local function transparent_adjacency_signature(text)
    return string.format(
        "%08x-%08x",
        transparent_adjacency_hash(text, 131, 17),
        transparent_adjacency_hash(text, 137, 29))
end

local function transparent_adjacency_item_identity(item)
    if type(item) ~= "table" then
        return "missing"
    end
    local parts = {
        tostring(item.kind or ""),
        tostring(item.source_kind or "BasePart"),
        tostring(item.key or ""),
        tostring(item.uniform_state_key or ""),
        tostring(item.render_priority or 0),
    }
    local source_ids = item.source_transparent_part_ids
    if type(source_ids) == "table" and #source_ids > 0 then
        parts[#parts + 1] = "sources"
        for index = 1, #source_ids do
            parts[#parts + 1] = tostring(source_ids[index])
        end
    elseif item.source_part_id ~= nil then
        parts[#parts + 1] = "source"
        parts[#parts + 1] = tostring(item.source_part_id)
    else
        -- a few renderer-owned transparent helpers do not have a BasePart id
        -- exact bounds keep their identities deterministic across processes
        -- without depending on userdata addresses
        local bounds = item.bounds
        parts[#parts + 1] = "sort"
        parts[#parts + 1] = tostring(item.sort_id or "")
        parts[#parts + 1] = "bounds"
        for _, value in ipairs({
            bounds and bounds.min_x,
            bounds and bounds.min_y,
            bounds and bounds.min_z,
            bounds and bounds.max_x,
            bounds and bounds.max_y,
            bounds and bounds.max_z,
        }) do
            parts[#parts + 1] =
                string.format("%.17g", tonumber(value) or 0)
        end
    end
    return transparent_adjacency_signature(
        table.concat(parts, "\30"))
end

local function transparent_adjacency_mesh_vertex_count(item)
    local mesh = type(item) == "table" and item.mesh or nil
    if not mesh or type(mesh.getVertexCount) ~= "function" then
        return nil
    end
    local ok, count = pcall(mesh.getVertexCount, mesh)
    count = ok and tonumber(count) or nil
    if not count or count < 0 then
        return nil
    end
    return math.floor(count)
end

-- read-only opportunity probe used by the profiler/debug overlay before any
-- transparent aggregation is enabled. it runs on the actual post-SurfaceGui,
-- back-to-front list, so every reported boundary is order-preserving rather
-- than an estimate from the unsorted visibility list
function RBX:_measure_transparent_adjacency_candidates(
    items, get_textured_shader, include_textured)
    local stats = self._transparent_adjacency_stats or {}
    self._transparent_adjacency_stats = stats
    for key in pairs(stats) do stats[key] = nil end
    items = items or {}

    local spatial_cell = math.max(
        8,
        tonumber(self.local_light_grid_cell_size) or 64)
        * math.max(
            1,
            math.floor(
                tonumber(self.local_light_cluster_supercell_span) or 2))
    local no_local_light_payload = "no-local-light-uniform"
    for index = 1, #items do
        local item = items[index]
        if type(item) == "table" then
            local shader
            if item.kind == "static" then
                shader = self._static_shader
            elseif get_textured_shader then
                shader = get_textured_shader(item)
            else
                shader = item.shader
            end
            item._transparent_adjacency_shader = shader
            if shader and self:_shader_supports_local_lights(shader) then
                item._transparent_adjacency_light_payload =
                    RBX._local_light_pack_payload_key(
                        self:_get_local_light_pack_for_item(item))
            else
                item._transparent_adjacency_light_payload =
                    no_local_light_payload
            end
            local bounds = item.bounds
            local x = item.sort_x
                or (bounds and bounds.center_x) or 0
            local y = item.sort_y
                or (bounds and bounds.center_y) or 0
            local z = item.sort_z
                or (bounds and bounds.center_z) or 0
            item._transparent_adjacency_cell_x =
                math.floor(x / spatial_cell)
            item._transparent_adjacency_cell_y =
                math.floor(y / spatial_cell)
            item._transparent_adjacency_cell_z =
                math.floor(z / spatial_cell)
            item._transparent_adjacency_depth_compare =
                normalized_transparent_depth_compare(item)
            item._transparent_adjacency_depth_bias =
                item.depth_bias or self.transparent_depth_bias or 0
            item._transparent_adjacency_stable_id =
                transparent_adjacency_item_identity(item)
            if item.kind == "textured" then
                item._transparent_adjacency_cull_mode =
                    item.resolved_cull_mode or self:_resolve_cull_mode(
                        item.cull_mode or "none",
                        item.mirror_cull_swap == true,
                        item.force_cull == true)
                item._transparent_adjacency_blend =
                    (shader == self._overlay_textured_shader
                        or shader == self._face_array_overlay_shader)
                        and "premultiplied" or "alphamultiply"
            end
        end
    end

    local function same_spatial_cell(a, b)
        return a._transparent_adjacency_cell_x
                == b._transparent_adjacency_cell_x
            and a._transparent_adjacency_cell_y
                == b._transparent_adjacency_cell_y
            and a._transparent_adjacency_cell_z
                == b._transparent_adjacency_cell_z
    end

    local function compatible_static(a, b, conservative)
        if not a or not b
            or a.kind ~= "static" or b.kind ~= "static"
            or a.transparent_static_batch ~= true
            or b.transparent_static_batch ~= true
            or (a.render_priority or 0) ~= (b.render_priority or 0)
            or a._transparent_adjacency_depth_compare
                ~= b._transparent_adjacency_depth_compare
            or a._transparent_adjacency_depth_bias
                ~= b._transparent_adjacency_depth_bias
            or a._transparent_adjacency_light_payload
                ~= b._transparent_adjacency_light_payload then
            return false
        end
        if conservative then
            return a.key == b.key and same_spatial_cell(a, b)
        end
        return true
    end

    local function compatible_textured(a, b, conservative)
        if include_textured == false
            or not a or not b
            or a.kind ~= "textured" or b.kind ~= "textured"
            or a._transparent_adjacency_shader
                ~= b._transparent_adjacency_shader
            or a.texture ~= b.texture
            or a.uniform_state_key ~= b.uniform_state_key
            or (a.render_priority or 0) ~= (b.render_priority or 0)
            or a._transparent_adjacency_depth_compare
                ~= b._transparent_adjacency_depth_compare
            or a._transparent_adjacency_depth_bias
                ~= b._transparent_adjacency_depth_bias
            or a._transparent_adjacency_cull_mode
                ~= b._transparent_adjacency_cull_mode
            or a._transparent_adjacency_blend
                ~= b._transparent_adjacency_blend
            or a._transparent_adjacency_light_payload
                ~= b._transparent_adjacency_light_payload then
            return false
        end
        return not conservative or same_spatial_cell(a, b)
    end

    local function measure_runs(prefix, compatible)
        local run_length = 0
        local run_count = 0
        local source_count = 0
        local ideal_savings = 0
        local pair_savings = 0
        local max_run = 0
        local previous = nil
        local function finish_run()
            if run_length >= 2 then
                run_count = run_count + 1
                source_count = source_count + run_length
                ideal_savings = ideal_savings + run_length - 1
                pair_savings =
                    pair_savings + math.floor(run_length / 2)
                max_run = math.max(max_run, run_length)
            end
        end
        for index = 1, #items do
            local item = items[index]
            if previous and compatible(previous, item, false) then
                run_length = run_length + 1
            else
                finish_run()
                run_length = item and (
                    (prefix == "static"
                        and item.kind == "static"
                        and item.transparent_static_batch == true)
                    or (prefix == "textured"
                        and include_textured ~= false
                        and item.kind == "textured")
                ) and 1 or 0
            end
            previous = run_length > 0 and item or nil
        end
        finish_run()
        stats[prefix .. "_run_count"] = run_count
        stats[prefix .. "_source_draw_count"] = source_count
        stats[prefix .. "_ideal_saved_draw_count"] = ideal_savings
        stats[prefix .. "_pair_saved_draw_count"] = pair_savings
        stats[prefix .. "_max_run_length"] = max_run

        local conservative_pairs = 0
        local conservative_source_vertices = 0
        local conservative_duplicate_bytes = 0
        local conservative_unknown_vertex_source_count = 0
        local conservative_pair_ids = {}
        local index = 1
        while index < #items do
            if compatible(items[index], items[index + 1], true) then
                local first = items[index]
                local second = items[index + 1]
                conservative_pairs = conservative_pairs + 1
                local pair_id = table.concat({
                    tostring(
                        first._transparent_adjacency_stable_id
                            or transparent_adjacency_item_identity(first)),
                    ">",
                    tostring(
                        second._transparent_adjacency_stable_id
                            or transparent_adjacency_item_identity(second)),
                })
                conservative_pair_ids[#conservative_pair_ids + 1] =
                    pair_id
                local first_vertices =
                    transparent_adjacency_mesh_vertex_count(first)
                local second_vertices =
                    transparent_adjacency_mesh_vertex_count(second)
                if first_vertices == nil then
                    conservative_unknown_vertex_source_count =
                        conservative_unknown_vertex_source_count + 1
                    first_vertices = 0
                end
                if second_vertices == nil then
                    conservative_unknown_vertex_source_count =
                        conservative_unknown_vertex_source_count + 1
                    second_vertices = 0
                end
                local pair_vertices =
                    first_vertices + second_vertices
                conservative_source_vertices =
                    conservative_source_vertices + pair_vertices
                conservative_duplicate_bytes =
                    conservative_duplicate_bytes
                        + pair_vertices
                        * (prefix == "static" and 12 or 20)
                        * 4
                index = index + 2
            else
                index = index + 1
            end
        end
        stats[prefix .. "_conservative_pair_saved_draw_count"] =
            conservative_pairs
        stats[prefix .. "_conservative_pair_source_vertex_count"] =
            conservative_source_vertices
        stats[prefix .. "_conservative_pair_duplicate_vertex_bytes"] =
            conservative_duplicate_bytes
        stats[prefix .. "_conservative_pair_unknown_vertex_source_count"] =
            conservative_unknown_vertex_source_count
        stats[prefix .. "_conservative_ordered_pair_ids"] =
            conservative_pair_ids
        stats[prefix .. "_conservative_ordered_pair_signature"] =
            transparent_adjacency_signature(
                table.concat(conservative_pair_ids, "\31"))
        local sorted_pair_ids = {}
        for pair_index = 1, #conservative_pair_ids do
            sorted_pair_ids[pair_index] =
                conservative_pair_ids[pair_index]
        end
        table.sort(sorted_pair_ids)
        stats[prefix .. "_conservative_pair_set_signature"] =
            transparent_adjacency_signature(
                table.concat(sorted_pair_ids, "\31"))
    end

    measure_runs("static", compatible_static)
    measure_runs("textured", compatible_textured)
    return stats
end

-- sort transparent SurfaceGui, BillboardGui and sprite draws together so depth order crosses batch types
function RBX:_order_same_face_surface_gui_items(items)
    if not items or #items<2 then return end
    local groups={}
    for index,item in ipairs(items) do
        if item.source_kind=="SurfaceGui" and item.surface_gui_part_ref and item.surface_gui_face then
            local part=item.surface_gui_part_ref
            local faces=groups[part];if not faces then faces={};groups[part]=faces end
            local key=tostring(item.surface_gui_face)..":"..tostring(item.render_priority or 0)
            local group=faces[key];if not group then group={slots={},items={}};faces[key]=group end
            group.slots[#group.slots+1]=index;group.items[#group.items+1]=item
        end
    end
    for _,faces in pairs(groups) do for _,group in pairs(faces) do
        if #group.items>1 then
            table.sort(group.items,function(a,b)
                local az,bz=a.surface_gui_z_offset or 0,b.surface_gui_z_offset or 0
                if az~=bz then return az<bz end
                local ao,bo=a.surface_gui_order or 0,b.surface_gui_order or 0
                if ao~=bo then return ao<bo end
                return (a.stable_sort_id or a.sort_id or 0)<(b.stable_sort_id or b.sort_id or 0)
            end)
            for i,index in ipairs(group.slots) do items[index]=group.items[i] end
        end
    end end
end

function RBX:_sort_transparent_gui_draw_items(items)
    if not items or #items <= 1 then
        return
    end

    local view_matrix = self._view_matrix
    if not view_matrix then
        return
    end

    self._transparent_gui_sort_count = (self._transparent_gui_sort_count or 0) + 1
    local vzx = view_matrix[9] or 0
    local vzy = view_matrix[10] or 0
    local vzz = view_matrix[11] or 1

    for index = 1, #items do
        local item = items[index]
        local bounds = item.bounds
        local sx = item.sort_x or (bounds and bounds.center_x) or 0
        local sy = item.sort_y or (bounds and bounds.center_y) or 0
        local sz = item.sort_z or (bounds and bounds.center_z) or 0
        local _, _, view_z = transform_point4(view_matrix, sx, sy, sz, 1)
        local nearest_depth = view_z
        if bounds and bounds.extent_x and bounds.extent_y and bounds.extent_z then
            local view_extent = math.abs(vzx) * bounds.extent_x +
                math.abs(vzy) * bounds.extent_y +
                math.abs(vzz) * bounds.extent_z
            nearest_depth = view_z + view_extent
        end
        item._sort_view_z = view_z
        item._sort_depth = nearest_depth
        -- Lua's table.sort is not stable.  preserve the already-correct order within
        -- sprite stream meshes and provide deterministic ties across all three streams
        item._transparent_gui_stable_order = index
    end

    table.sort(items, function(a, b)
        -- RenderPriority is a paint-order band.  in particular AlwaysOnTop uses
        -- priority 6 and must be submitted after regular world GUIs (priority 4),
        -- independent of their relative depth
        local ap = a.render_priority or 0
        local bp = b.render_priority or 0
        if ap ~= bp then
            return ap < bp
        end
        if a._sort_depth ~= b._sort_depth then
            return a._sort_depth < b._sort_depth
        end
        if a._sort_view_z ~= b._sort_view_z then
            return a._sort_view_z < b._sort_view_z
        end
        return a._transparent_gui_stable_order < b._transparent_gui_stable_order
    end)
    self:_order_same_face_surface_gui_items(items)
end

-- Depth-tested world GUI canvases participate in the same alpha composition
-- as glass, trails and particles. only the authored AlwaysOnTop path belongs
-- after that composition. preserve the cached source vectors: opaque splits
-- are retained across frames, while billboard vertices can change in place
function RBX:_compose_world_gui_draw_items(regular, face_items, gui_items)
    local world_items=self._physical_gui_transparent_items or {}
    local top_items=self._always_on_top_gui_items or {}
    self._physical_gui_transparent_items=world_items
    self._always_on_top_gui_items=top_items
    local count,top_count,physical_count=0,0,0
    for i=1,#regular do count=count+1;world_items[count]=regular[i] end
    for stream=1,2 do
        local source=stream==1 and face_items or gui_items
        for i=1,#source do
            local item=source[i]
            if item.depth_compare=='always' then
                top_count=top_count+1;top_items[top_count]=item
            else
                count=count+1;physical_count=physical_count+1;world_items[count]=item
            end
        end
    end
    for i=#world_items,count+1,-1 do world_items[i]=nil end
    for i=#top_items,top_count+1,-1 do top_items[i]=nil end
    if physical_count>0 then
        self._transparent_sort_cache_state=nil
        regular=world_items
    end
    return regular,top_items
end

local function clear_draw_list(list)
    for index = #list, 1, -1 do
        list[index] = nil
    end
end

local function opaque_local_light_state_key(item)
    if type(item) ~= "table" then
        return ""
    end
    -- Handedness is the state that can change closed-solid culling. the
    -- remaining fields make the helper useful for raw/static fallback items
    -- without coupling it to one scene packet representation
    return table.concat({
        tostring(item.closed_primitive_handedness or ""),
        tostring(item.cull_mode or ""),
        tostring(item.mirror_cull_swap == true),
        tostring(item.force_cull == true),
    }, "|")
end

local function opaque_local_light_geometry_group_key(renderer, item)
    if type(item) ~= "table" then
        return ""
    end
    local span = math.max(
        1,
        math.floor(
            tonumber(renderer.local_light_cluster_supercell_span) or 2))
    local gx = tonumber(item._scene_chunk_grid_x)
        or tonumber(item.grid_x)
    local gy = tonumber(item._scene_chunk_grid_y)
        or tonumber(item.grid_y)
    local gz = tonumber(item._scene_chunk_grid_z)
        or tonumber(item.grid_z)
    local spatial_key = "none"
    if gx ~= nil and gy ~= nil and gz ~= nil then
        spatial_key = table.concat({
            math.floor(gx / span), ":",
            math.floor(gy / span), ":",
            math.floor(gz / span),
        })
    end
    local batch_key = item.batch_key
        or item.closed_primitive_batch_key
        or item.shape_name
        or ""
    return table.concat({
        tostring(item.dynamic_chunk == true),
        "|", opaque_local_light_state_key(item),
        "|", tostring(batch_key),
        "|", spatial_key,
    })
end

local function opaque_local_light_source_order_key(item)
    if type(item) ~= "table" then
        return ""
    end
    return table.concat({
        tostring(item._scene_chunk_key or item.key or ""),
        "|",
        tostring(item.batch_key
            or item.closed_primitive_batch_key
            or item.shape_name
            or ""),
    })
end

function RBX:_sort_opaque_draw_list_by_local_light_pack(list)
    if type(list) ~= "table" or #list <= 0 then
        return list or {}, 0
    end

    local unique_pack_keys = self._opaque_local_light_unique_pack_scratch
    if not unique_pack_keys then
        unique_pack_keys = {}
        self._opaque_local_light_unique_pack_scratch = unique_pack_keys
    else
        for key in pairs(unique_pack_keys) do
            unique_pack_keys[key] = nil
        end
    end

    local unique_pack_count = 0
    for index = 1, #list do
        local item = list[index]
        local pack = self:_get_local_light_pack_for_item(item)
        local pack_key = RBX._local_light_pack_payload_key(pack)
        item._opaque_local_light_sort_pack_key = pack_key
        item._opaque_local_light_sort_state_key =
            opaque_local_light_geometry_group_key(self, item)
        item._opaque_local_light_sort_source_key =
            opaque_local_light_source_order_key(item)
        item._opaque_local_light_sort_original_index = index
        if unique_pack_keys[pack_key] ~= true then
            unique_pack_keys[pack_key] = true
            unique_pack_count = unique_pack_count + 1
        end
    end

    table.sort(list, function(a, b)
        local a_pack = a._opaque_local_light_sort_pack_key
        local b_pack = b._opaque_local_light_sort_pack_key
        if a_pack ~= b_pack then
            return a_pack < b_pack
        end
        local a_state = a._opaque_local_light_sort_state_key
        local b_state = b._opaque_local_light_sort_state_key
        if a_state ~= b_state then
            return a_state < b_state
        end
        local a_source = a._opaque_local_light_sort_source_key
        local b_source = b._opaque_local_light_sort_source_key
        if a_source ~= b_source then
            return a_source < b_source
        end
        return (a._opaque_local_light_sort_original_index or 0)
            < (b._opaque_local_light_sort_original_index or 0)
    end)

    return list, unique_pack_count
end

function RBX:_copy_and_sort_opaque_draw_list_by_local_light_pack(source, buffer)
    buffer = buffer or {}
    clear_draw_list(buffer)
    for index = 1, #(source or {}) do
        buffer[index] = source[index]
    end
    return self:_sort_opaque_draw_list_by_local_light_pack(buffer)
end

function RBX:_static_local_light_clusters_invalid_reason()
    local clusters = self._static_local_light_clusters
    if self.enable_static_local_light_clusters == false then
        return "disabled"
    elseif self.enable_local_lights == false then
        return "local_lights_disabled"
    elseif self.enable_local_light_pack_sorting == false then
        return "pack_sorting_disabled"
    elseif self.use_instancing ~= true then
        return "instancing_unavailable"
    elseif self.constant_fragment_shader == true then
        return "constant_shader"
    elseif self.render_backend_name ~= "menori"
        or not self._render_backend then
        return "backend_unavailable"
    elseif type(clusters) == "table"
        and clusters.backend ~= nil
        and (
            clusters.backend ~= self._render_backend
            or (clusters.backend_generation
                    or (clusters.backend and clusters.backend.generation)
                    or 0)
                ~= (self._render_backend.generation or 0)
        ) then
        return "backend_generation_changed"
    elseif self.enable_occlusion_culling == true then
        return "occlusion_active"
    elseif type(clusters)~='table'and (tonumber(self.local_light_count) or 0)
        <= math.max(0, tonumber(self.max_lights_per_batch) or 0) then
        return "light_slots_sufficient"
    elseif type(clusters) ~= "table" then
        return "not_built"
    elseif clusters.instance_generation ~= (self._instance_generation or 0) then
        return "instance_generation_changed"
    elseif clusters.static_scene_revision
        ~= (self._static_scene_revision or 0) then
        return "static_scene_revision_changed"
    elseif clusters.build_signature ~= nil
        and clusters.build_signature
            ~= self:_static_local_light_cluster_build_signature() then
        return "configuration_changed"
    elseif clusters.light_revision ~= (self._local_light_revision or 0) then
        return "light_revision_changed"
    end
    return nil
end

function RBX:_static_local_light_clusters_are_valid()
    return self:_static_local_light_clusters_invalid_reason() == nil
end

function RBX:_static_local_light_cluster_retry_is_ready(signature)
    if self._static_local_light_cluster_failure_signature ~= signature then
        return false
    end
    local failure_count = math.max(
        0,
        tonumber(self._static_local_light_cluster_failure_count) or 0)
    local retry_limit = math.max(
        0,
        math.floor(
            tonumber(self.local_light_cluster_failure_retry_limit) or 3))
    if failure_count <= 0 or failure_count > retry_limit then
        return false
    end
    return love.timer.getTime()
        >= (tonumber(self._static_local_light_cluster_retry_at) or math.huge)
end

function RBX:_maintain_static_local_light_clusters()
    local reason = self:_static_local_light_clusters_invalid_reason()
    if reason=='light_revision_changed'then
        self:_refresh_static_local_light_cluster_packs()
        return false
    end
    if reason == nil then
        self._static_local_light_cluster_pending_signature = nil
        self._static_local_light_cluster_pending_since = nil
        local signature =
            self:_static_local_light_cluster_build_signature()
        if self:_static_local_light_cluster_retry_is_ready(signature) then
            self:_rebuild_static_local_light_clusters({
                maintenance = true,
            })
            return self._static_local_light_clusters ~= nil
        end
        return false
    end

    -- an ineligible generation has no submission value and can be large. retire
    -- it immediately for every gate (including reversible runtime toggles), then
    -- let a later eligible/stable signature rebuild after the normal delay
    if self._static_local_light_clusters then
        self:_release_static_local_light_clusters(true)
        reason = self:_static_local_light_clusters_invalid_reason()
    end
    if reason ~= "not_built" then
        return false
    end

    local signature =
        self:_static_local_light_cluster_build_signature()
    if self._static_local_light_cluster_last_attempt_signature
        == signature then
        if self:_static_local_light_cluster_retry_is_ready(signature) then
            self:_rebuild_static_local_light_clusters({
                maintenance = true,
            })
            return self._static_local_light_clusters ~= nil
        end
        return false
    end
    local now = love.timer.getTime()
    if self._static_local_light_cluster_pending_signature
        ~= signature then
        self._static_local_light_cluster_pending_signature = signature
        self._static_local_light_cluster_pending_since = now
        return false
    end
    local delay = math.max(
        0,
        tonumber(self.local_light_cluster_rebuild_delay) or 0.15)
    if now - (self._static_local_light_cluster_pending_since or now)
        < delay then
        return false
    end

    self._static_local_light_cluster_pending_signature = nil
    self._static_local_light_cluster_pending_since = nil
    self:_rebuild_static_local_light_clusters({
        maintenance = true,
    })
    return self._static_local_light_clusters ~= nil
end

function RBX:_compose_static_local_light_cluster_draw_list(
    source, source_to_cluster, buffer)
    source = source or {}
    buffer = buffer or {}
    clear_draw_list(buffer)
    if type(source_to_cluster) ~= "table" or #source <= 0 then
        for index = 1, #source do
            buffer[index] = source[index]
        end
        return buffer, 0, 0
    end

    local visible_counts =
        self._local_light_cluster_visible_count_scratch
    local visible_order_valid =
        self._local_light_cluster_visible_order_valid_scratch
    local visible_last_source_order =
        self._local_light_cluster_visible_last_source_order_scratch
    local emitted = self._local_light_cluster_emitted_scratch
    if not visible_counts then
        visible_counts = {}
        self._local_light_cluster_visible_count_scratch = visible_counts
    else
        for cluster in pairs(visible_counts) do
            visible_counts[cluster] = nil
        end
    end
    if not emitted then
        emitted = {}
        self._local_light_cluster_emitted_scratch = emitted
    else
        for cluster in pairs(emitted) do
            emitted[cluster] = nil
        end
    end
    if not visible_order_valid then
        visible_order_valid = {}
        self._local_light_cluster_visible_order_valid_scratch =
            visible_order_valid
    else
        for cluster in pairs(visible_order_valid) do
            visible_order_valid[cluster] = nil
        end
    end
    if not visible_last_source_order then
        visible_last_source_order = {}
        self._local_light_cluster_visible_last_source_order_scratch =
            visible_last_source_order
    else
        for cluster in pairs(visible_last_source_order) do
            visible_last_source_order[cluster] = nil
        end
    end

    for index = 1, #source do
        local source_item = source[index]
        local cluster = source_to_cluster[source_item]
        if cluster then
            visible_counts[cluster] =
                (visible_counts[cluster] or 0) + 1
            local source_order = cluster.source_order_by_item
                and cluster.source_order_by_item[source_item] or nil
            local last_order = visible_last_source_order[cluster]
            if source_order ~= nil then
                if last_order ~= nil and source_order <= last_order then
                    visible_order_valid[cluster] = false
                elseif visible_order_valid[cluster] == nil then
                    visible_order_valid[cluster] = true
                end
                visible_last_source_order[cluster] = source_order
            end
        end
    end

    local clustered_source_draws = 0
    local cluster_draws = 0
    local index = 1
    while index <= #source do
        local item = source[index]
        local cluster = source_to_cluster[item]
        local visible_count = cluster and visible_counts[cluster] or 0
        if cluster and cluster.light_payload_valid~=false and visible_count >= 2
            and visible_order_valid[cluster] ~= false then
            -- one aggregate draw is order-equivalent only when every visible
            -- source it replaces forms one uninterrupted run. Pulling instances
            -- across an unrelated opaque draw changes coplanar/equal-depth tie
            -- ownership even though the geometry and light payload are exact
            local run_end = index + 1
            while run_end <= #source
                and source_to_cluster[source[run_end]] == cluster do
                run_end = run_end + 1
            end
            local run_count = run_end - index
            if run_count == visible_count and emitted[cluster] ~= true then
                emitted[cluster] = true
                buffer[#buffer + 1] = cluster
                clustered_source_draws =
                    clustered_source_draws + run_count
                cluster_draws = cluster_draws + 1
                index = run_end
            else
                buffer[#buffer + 1] = item
                index = index + 1
            end
        else
            buffer[#buffer + 1] = item
            index = index + 1
        end
    end

    return buffer,
        math.max(0, clustered_source_draws - cluster_draws),
        cluster_draws
end

local function split_draw_list_by_source_kind(source, source_kind, rest_buffer, matched_buffer)
    rest_buffer = rest_buffer or {}
    matched_buffer = matched_buffer or {}
    clear_draw_list(rest_buffer)
    clear_draw_list(matched_buffer)
    local matched_count = 0
    for index = 1, #(source or {}) do
        local item = source[index]
        if item and item.source_kind == source_kind then
            matched_buffer[#matched_buffer + 1] = item
            matched_count = matched_count + 1
        elseif item then
            rest_buffer[#rest_buffer + 1] = item
        end
    end
    if matched_count <= 0 then
        return source or rest_buffer, matched_buffer, false
    end
    return rest_buffer, matched_buffer, true
end

function RBX:_compose_mega_static_draw_list(mega_items, visible_items, buffer)
    buffer = buffer or {}
    clear_draw_list(buffer)
    local covered_keys = self._mega_static_covered_keys_buffer or {}
    self._mega_static_covered_keys_buffer = covered_keys
    for key in pairs(covered_keys) do
        covered_keys[key] = nil
    end

    for index = 1, #(mega_items or {}) do
        local item = mega_items[index]
        if item then
            buffer[#buffer + 1] = item
            if item.key ~= nil then
                covered_keys[item.key] = true
            end
        end
    end

    for index = 1, #(visible_items or {}) do
        local item = visible_items[index]
        if item and (item.dynamic_chunk == true
            or item.key == nil
            or covered_keys[item.key] ~= true) then
            buffer[#buffer + 1] = item
        end
    end

    return buffer
end

function RBX:_compose_mega_textured_draw_list(mega_batches, visible_batches, buffer)
    buffer = buffer or {}
    clear_draw_list(buffer)

    for index = 1, #(mega_batches or {}) do
        buffer[#buffer + 1] = mega_batches[index]
    end

    for index = 1, #(visible_batches or {}) do
        local batch = visible_batches[index]
        if batch and (batch.source_kind == "SurfaceGui"
            or batch.dynamic_chunk == true) then
            buffer[#buffer + 1] = batch
        end
    end

    return buffer
end

function RBX:_should_use_opaque_depth_prepass()
    if self.enable_opaque_depth_prepass ~= true then
        return false
    end

    if self.opaque_depth_prepass_mode == "full"
        or self.opaque_depth_prepass_mode == "static"
        or self.opaque_depth_prepass_mode == "textured" then
        return true
    end
    if self.opaque_depth_prepass_mode ~= "auto" then
        return false
    end

    local culling = self._culling_stats or {}
    local visible_opaque_parts = culling.visible_opaque_part_count or 0
    local visible_textured_batches = (self._visible_textured_batches and #self._visible_textured_batches or 0)
        + (self._visible_overlay_textured_batches and #self._visible_overlay_textured_batches or 0)

    return visible_opaque_parts >= (self.opaque_depth_prepass_min_visible_parts or 160)
        or visible_textured_batches >= (self.opaque_depth_prepass_min_textured_batches or 48)
end

function RBX:_get_active_opaque_depth_prepass_mode()
    if not self:_should_use_opaque_depth_prepass() then
        return "off"
    end
    if self.opaque_depth_prepass_mode == "static" or self.opaque_depth_prepass_mode == "textured" then
        return self.opaque_depth_prepass_mode
    end
    return "full"
end

function RBX:_is_debug_overlay_enabled()
    return type(G) == "table" and type(G.debug) == "table" and G.debug.on == true
        and not (G.pipeline and G.pipeline.hide_overlays)
end

function RBX:_record_draw_time(draw_start)
    if type(draw_start) ~= "number" then
        return
    end

    local elapsed_ms = math.max(0, (love.timer.getTime() - draw_start) * 1000)
    local sample_count = self._draw_time_sample_count or 0

    self._last_draw_ms = elapsed_ms

    if sample_count <= 0 then
        self._avg_draw_ms = elapsed_ms
        self._draw_time_sample_count = 1
        return
    end

    if sample_count < 24 then
        local next_count = sample_count + 1
        self._avg_draw_ms = (((self._avg_draw_ms or 0) * sample_count) + elapsed_ms) / next_count
        self._draw_time_sample_count = next_count
        return
    end

    local average = self._avg_draw_ms or elapsed_ms
    local smoothing = self._draw_time_smoothing or 0.06
    self._avg_draw_ms = average + (elapsed_ms - average) * smoothing
    self._draw_time_sample_count = sample_count + 1
end

function RBX:_build_debug_overlay_lines()
    -- expensive (~200-key get_stats + draw-list scan) so ~5hz, safe to skip, draw pass already runs its side effect
    local now = (love.timer and love.timer.getTime()) or 0
    local cached = self._debug_overlay_lines_cache
    if cached and (now - (self._debug_overlay_lines_at or -1)) < 0.2 then
        return cached
    end
    local stats = self:get_stats()
    local map_name = "runtime scene"
    if type(stats.map_path) == "string" and stats.map_path ~= "" then
        map_name = normalize_asset_path(stats.map_path):match("([^/]+)$") or stats.map_path
    end

    local frustum_culled_opaque = math.max(0,
        (stats.opaque_part_count or 0) - (stats.frustum_visible_opaque_part_count or 0))

    local lines = {
        "RBX renderer",
        string.format("map: %s", map_name),
        string.format("render: avg %.2f ms", stats.render_time_avg_ms or 0),
        string.format(
            "parts: %d total | opaque %d visible %d | transparent %d visible %d",
            stats.part_count or 0,
            stats.opaque_part_count or 0,
            stats.visible_opaque_part_count or 0,
            stats.transparent_part_count or 0,
            stats.visible_transparent_part_count or 0
        ),
        string.format(
            "culling: chunks %d | frustum %d | occluders %d | occluded %d | drawn %d",
            stats.chunk_count or 0,
            stats.frustum_visible_chunk_count or 0,
            stats.occluder_chunk_count or 0,
            stats.occluded_chunk_count or 0,
            stats.visible_chunk_count or 0
        ),
        string.format(
            "opaque culled: frustum %d | occlusion %d",
            frustum_culled_opaque,
            stats.occlusion_culled_opaque_part_count or 0
        ),
        string.format(
            "draws: textured %d | static %d | transparent items %d visible %d",
            stats.textured_batch_count or 0,
            stats.opaque_static_batch_count or 0,
            stats.transparent_draw_count or 0,
            stats.visible_transparent_draw_count or 0
        ),
        string.format(
            "instancing: %s | cell %d | near %.2f | far %.2f",
            stats.instancing and "on" or "off",
            stats.visibility_cell_size or 0,
            stats.active_near_clip or 0,
            stats.active_far_clip or 0
        ),
        string.format(
            "flags: frustum %s | occlusion %s | mesh parts %d | material parts %d",
            stats.frustum_culling and "on" or "off",
            stats.occlusion_culling and "on" or "off",
            stats.mesh_part_count or 0,
            stats.material_part_count or 0
        ),
    }
    self._debug_overlay_lines_cache = lines
    self._debug_overlay_lines_at = now
    return lines
end

function RBX:_project_world_to_screen(x, y, z, target_width, target_height)
    if not (self._view_matrix and self._projection_matrix) then
        return nil
    end
    local vx, vy, vz, vw = transform_point4(self._view_matrix, x or 0, y or 0, z or 0, 1)
    local cx, cy, cz, cw = transform_point4(self._projection_matrix, vx, vy, vz, vw)
    if cw == nil or cw <= 0.0001 then
        return nil
    end
    local ndc_x = cx / cw
    local ndc_y = cy / cw
    local sx = (ndc_x * 0.5 + 0.5) * target_width
    local sy = (1 - (ndc_y * 0.5 + 0.5)) * target_height
    return sx, sy, vz
end

-- opt-in collider audit: aabb wire per broadphase proxy. read-only, never mutates physics
function RBX:_draw_collider_wireboxes(world, target_width, target_height, opts)
    if not (world and world.audit_proxies) then return end
    if not (self._view_matrix and self._projection_matrix) then return end
    opts = opts or {}
    local highlight_id = opts.highlight_id
    local ok, entries = pcall(function() return world:audit_proxies() end)
    if not ok or type(entries) ~= "table" then return end

    love.graphics.push("all")
    love.graphics.origin()
    love.graphics.setShader()
    love.graphics.setDepthMode("always", false)
    love.graphics.setMeshCullMode("none")
    love.graphics.setBlendMode("alpha", "alphamultiply")
    love.graphics.setLineWidth(1.5)
    if opts.font then love.graphics.setFont(opts.font) end

    local function project(x, y, z)
        return self:_project_world_to_screen(x, y, z, target_width, target_height)
    end
    local function seg(ax, ay, az, bx, by, bz)
        local sx0, sy0 = project(ax, ay, az)
        local sx1, sy1 = project(bx, by, bz)
        if sx0 and sx1 then love.graphics.line(sx0, sy0, sx1, sy1) end
    end

    for _, e in ipairs(entries) do
        local a = e.aabb
        if a then
            local lx, ly, lz, rx, ry, rz = a[1], a[2], a[3], a[4], a[5], a[6]
            if e.id == highlight_id then
                love.graphics.setColor(1, 0.92, 0.2, 1)          -- yellow: the blocker
            elseif e.source == "stale-orphan" then
                love.graphics.setColor(1, 0.2, 0.2, 1)           -- red: phantom/orphan
            elseif e.source == "runtime-created" then
                love.graphics.setColor(0.3, 0.85, 1, 1)          -- cyan: runtime/debug
            else
                love.graphics.setColor(0.3, 1, 0.4, 0.85)        -- green: real map
            end
            -- bottom rectangle
            seg(lx, ly, lz, rx, ly, lz); seg(rx, ly, lz, rx, ly, rz)
            seg(rx, ly, rz, lx, ly, rz); seg(lx, ly, rz, lx, ly, lz)
            -- top rectangle
            seg(lx, ry, lz, rx, ry, lz); seg(rx, ry, lz, rx, ry, rz)
            seg(rx, ry, rz, lx, ry, rz); seg(lx, ry, rz, lx, ry, lz)
            -- vertical edges
            seg(lx, ly, lz, lx, ry, lz); seg(rx, ly, lz, rx, ry, lz)
            seg(rx, ly, rz, rx, ry, rz); seg(lx, ly, rz, lx, ry, rz)

            if opts.font then
                local rec = e.record
                local trans = rec and tonumber(rec.Transparency) or 0
                local invisible = (trans or 0) >= 1
                if invisible or e.id == highlight_id then
                    local cxp, cyp = project((lx + rx) * 0.5, ry, (lz + rz) * 0.5)
                    if cxp then
                        local label = (e.id == highlight_id and "BLOCKER " or "")
                            .. (rec and tostring(rec.Name) or ("#" .. tostring(e.id)))
                        if invisible then label = label .. " [INVISIBLE]" end
                        love.graphics.print(label, cxp + 3, cyp - 8)
                    end
                end
            end
        end
    end

    love.graphics.pop()
end

-- physics debug viz (G.debug.on): hitboxes green=active red=sleeping gray=static. read-only
function RBX:_physics_debug_enabled()
    local g = rawget(_G, "G")
    if g and g.pipeline and g.pipeline.hide_overlays then return false end
    if self._physics_debug_override ~= nil then
        return self._physics_debug_override == true
    end
    return (g and g.debug and g.debug.on) == true
end

local _debug_draw_module = nil
local function _get_debug_draw()
    if _debug_draw_module == nil then
        _debug_draw_module = runtime_require("debug_draw.lua") or false
    end
    return _debug_draw_module or nil
end

-- World geometry is drawn while the existing scene depth attachment is live,
-- before HDR resolve / screen GUI. the screen legend remains display-space
function RBX:_draw_world_debug()
    if not self:_physics_debug_enabled() then return end
    _get_debug_draw().world(self)
    self._debug_raycasts, self._debug_regions = nil, nil
end

function RBX:_draw_physics_debug(world)
    self:_draw_world_debug()
end

local function _draw_debug_circle_arc(samples_x, samples_y, cx, cy, radius)
    local count = 24
    local prev_x, prev_y
    for i = 0, count do
        local theta = (i / count) * math.pi * 2
        local px = cx + math.cos(theta) * radius
        local py = cy + math.sin(theta) * radius
        if prev_x then
            love.graphics.line(prev_x, prev_y, px, py)
        end
        prev_x, prev_y = px, py
    end
end

function RBX:_draw_lighting_debug_visualizations(target_width, target_height)
    local mode = self._lighting_debug_mode
    if not mode or mode == "off" then
        return
    end
    local lights = self.local_lights or {}
    if #lights == 0 and not (mode == "sun" or mode == "grid" or mode == "all") then
        return
    end

    love.graphics.push("all")
    love.graphics.origin()
    love.graphics.setShader()
    love.graphics.setDepthMode("always", false)
    love.graphics.setMeshCullMode("none")
    love.graphics.setBlendMode("alpha", "alphamultiply")
    love.graphics.setLineWidth(1.5)

    local function project(x, y, z)
        return self:_project_world_to_screen(x, y, z, target_width, target_height)
    end

    local function draw_segment(ax, ay, az, bx, by, bz)
        local sx0, sy0, vz0 = project(ax, ay, az)
        local sx1, sy1, vz1 = project(bx, by, bz)
        if sx0 and sx1 and (vz0 or 0) < 0 and (vz1 or 0) < 0 then
            love.graphics.line(sx0, sy0, sx1, sy1)
        end
    end

    local function draw_wire_box(min_x, min_y, min_z, max_x, max_y, max_z)
        local corners = {
            { min_x, min_y, min_z }, { max_x, min_y, min_z },
            { max_x, min_y, max_z }, { min_x, min_y, max_z },
            { min_x, max_y, min_z }, { max_x, max_y, min_z },
            { max_x, max_y, max_z }, { min_x, max_y, max_z },
        }
        local edges = {
            {1,2},{2,3},{3,4},{4,1},
            {5,6},{6,7},{7,8},{8,5},
            {1,5},{2,6},{3,7},{4,8}
        }
        for i = 1, #edges do
            local a, b = corners[edges[i][1]], corners[edges[i][2]]
            draw_segment(a[1], a[2], a[3], b[1], b[2], b[3])
        end
    end

    local function draw_wire_sphere(cx, cy, cz, radius)
        local rings = 3
        local segments = 16
        for ring = 0, rings do
            local t = ring / rings - 0.5
            local height = math.sin(t * math.pi) * radius
            local ring_radius = math.cos(t * math.pi) * radius
            local prev_x, prev_y, prev_z
            for seg = 0, segments do
                local theta = (seg / segments) * math.pi * 2
                local px = cx + math.cos(theta) * ring_radius
                local py = cy + height
                local pz = cz + math.sin(theta) * ring_radius
                if prev_x then
                    draw_segment(prev_x, prev_y, prev_z, px, py, pz)
                end
                prev_x, prev_y, prev_z = px, py, pz
            end
        end
        for seg = 0, segments - 1, 4 do
            local theta = (seg / segments) * math.pi * 2
            local prev_x, prev_y, prev_z
            for slice = 0, 12 do
                local phi = (slice / 12) * math.pi - math.pi / 2
                local r = math.cos(phi) * radius
                local h = math.sin(phi) * radius
                local px = cx + math.cos(theta) * r
                local py = cy + h
                local pz = cz + math.sin(theta) * r
                if prev_x then
                    draw_segment(prev_x, prev_y, prev_z, px, py, pz)
                end
                prev_x, prev_y, prev_z = px, py, pz
            end
        end
    end

    local function draw_cone(cx, cy, cz, dx, dy, dz, length, half_angle_rad)
        local tip_x = cx + dx * length
        local tip_y = cy + dy * length
        local tip_z = cz + dz * length
        local radius = math.tan(half_angle_rad) * length
        local ux, uy, uz
        if math.abs(dy) < 0.95 then
            ux, uy, uz = -dz, 0, dx
        else
            ux, uy, uz = 1, 0, 0
        end
        local len = math.sqrt(ux*ux + uy*uy + uz*uz)
        if len > 0 then
            ux, uy, uz = ux / len, uy / len, uz / len
        end
        local vx, vy, vz = dy*uz - dz*uy, dz*ux - dx*uz, dx*uy - dy*ux
        local segments = 16
        local prev_x, prev_y, prev_z
        for i = 0, segments do
            local theta = (i / segments) * math.pi * 2
            local rx = math.cos(theta) * radius
            local ry = math.sin(theta) * radius
            local px = tip_x + ux * rx + vx * ry
            local py = tip_y + uy * rx + vy * ry
            local pz = tip_z + uz * rx + vz * ry
            if prev_x then
                draw_segment(prev_x, prev_y, prev_z, px, py, pz)
            end
            prev_x, prev_y, prev_z = px, py, pz
            if i % 4 == 0 then
                draw_segment(cx, cy, cz, px, py, pz)
            end
        end
    end

    local function draw_surface_rect(light)
        local sx, sy, sz = light.x or 0, light.y or 0, light.z or 0
        local ux, uy, uz, uh = light.axis_u_x or 1, light.axis_u_y or 0, light.axis_u_z or 0, light.axis_u_half or 0
        local vx, vy, vz, vh = light.axis_v_x or 0, light.axis_v_y or 1, light.axis_v_z or 0, light.axis_v_half or 0
        local corners = {
            { sx + ux * -uh + vx * -vh, sy + uy * -uh + vy * -vh, sz + uz * -uh + vz * -vh },
            { sx + ux *  uh + vx * -vh, sy + uy *  uh + vy * -vh, sz + uz *  uh + vz * -vh },
            { sx + ux *  uh + vx *  vh, sy + uy *  uh + vy *  vh, sz + uz *  uh + vz *  vh },
            { sx + ux * -uh + vx *  vh, sy + uy * -uh + vy *  vh, sz + uz * -uh + vz *  vh },
        }
        for i = 1, 4 do
            local a, b = corners[i], corners[(i % 4) + 1]
            draw_segment(a[1], a[2], a[3], b[1], b[2], b[3])
        end
    end

    local show_bounds = mode == "bounds" or mode == "all"
    local show_sphere = mode == "point" or mode == "all" or mode == "bounds"
    local show_cone = mode == "cone" or mode == "spot" or mode == "all"
    local show_surface = mode == "surface" or mode == "all"
    local show_selected = mode == "selected"
    local show_grid = mode == "grid"
    local show_sun = mode == "sun" or mode == "all"

    for index = 1, #lights do
        local light = lights[index]
        if light and light.active then
            local class_name = light.class_name
            local cr = light.color_r or 1
            local cg = light.color_g or 1
            local cb = light.color_b or 1
            if show_bounds and light.bounds then
                love.graphics.setColor(cr * 0.85, cg * 0.85, cb * 0.85, 0.65)
                draw_wire_box(light.bounds.min_x, light.bounds.min_y, light.bounds.min_z,
                    light.bounds.max_x, light.bounds.max_y, light.bounds.max_z)
            end
            if show_sphere and class_name == "PointLight" then
                love.graphics.setColor(cr, cg, cb, 0.85)
                draw_wire_sphere(light.x, light.y, light.z, light.range or 0)
            end
            if show_cone and (class_name == "SpotLight" or class_name == "SurfaceLight") then
                love.graphics.setColor(cr, cg, cb, 0.9)
                local half_angle = math.rad(math.max(1, math.min(89, (light.angle or 0) * 0.5)))
                draw_cone(light.x, light.y, light.z,
                    light.dir_x or 0, light.dir_y or 0, light.dir_z or -1,
                    light.range or 0, half_angle)
            end
            if show_surface and class_name == "SurfaceLight" then
                love.graphics.setColor(1, 1, 0.4, 0.95)
                draw_surface_rect(light)
            end
        end
    end

    if show_selected and self._scene_bounds then
        local pack_lights = self:_collect_local_lights_for_bounds(self._scene_bounds, {})
        love.graphics.setColor(1, 0.8, 0.2, 0.85)
        for index = 1, math.min(#pack_lights, self.max_lights_per_batch or 4) do
            local light = pack_lights[index]
            if light and light.bounds then
                draw_wire_box(light.bounds.min_x, light.bounds.min_y, light.bounds.min_z,
                    light.bounds.max_x, light.bounds.max_y, light.bounds.max_z)
            end
        end
    end

    if show_grid then
        local cell_size = self.local_light_grid_cell_size or 64
        love.graphics.setColor(0.4, 0.8, 1.0, 0.45)
        local grid = self._local_light_grid or {}
        local count = 0
        local stride = LIGHT_GRID_KEY_STRIDE
        local bias = LIGHT_GRID_KEY_BIAS
        for key, bucket in pairs(grid) do
            if bucket and #bucket > 0 then
                count = count + 1
                local cz = math.floor(key / (stride * stride))
                local rem = key - cz * stride * stride
                local cy = math.floor(rem / stride)
                local cx = rem - cy * stride
                cx = cx - bias
                cy = cy - bias
                cz = cz - bias
                local min_x = cx * cell_size
                local min_y = cy * cell_size
                local min_z = cz * cell_size
                draw_wire_box(min_x, min_y, min_z, min_x + cell_size, min_y + cell_size, min_z + cell_size)
                if count >= 256 then break end
            end
        end
    end

    if show_sun and self.lighting_state then
        local sun_dir = self.lighting_state.sun_direction or { 0.4, 1.0, 0.25 }
        local moon_dir = self.lighting_state.moon_direction or { -0.4, -1.0, -0.25 }
        local cam = self.camera and self.camera.cframe
        if cam then
            local cx, cy, cz = cam.x or 0, cam.y or 0, cam.z or 0
            local arrow_length = 12
            love.graphics.setColor(1, 0.9, 0.5, 0.9)
            draw_segment(cx + sun_dir[1] * 4, cy + sun_dir[2] * 4 + 3, cz + sun_dir[3] * 4,
                cx + sun_dir[1] * arrow_length, cy + sun_dir[2] * arrow_length + 3, cz + sun_dir[3] * arrow_length)
            love.graphics.setColor(0.7, 0.85, 1.0, 0.9)
            draw_segment(cx + moon_dir[1] * 4, cy + moon_dir[2] * 4 + 3, cz + moon_dir[3] * 4,
                cx + moon_dir[1] * arrow_length, cy + moon_dir[2] * arrow_length + 3,
                cz + moon_dir[3] * arrow_length)
        end
    end

    love.graphics.pop()
end

function RBX:_draw_debug_overlay(target_width, target_height)
    self:_draw_lighting_debug_visualizations(target_width, target_height)
    if not self:_is_debug_overlay_enabled() then
        return
    end

    local lines = _get_debug_draw().legend(self)
    if #lines == 0 then
        return
    end

    local font = RBX._get_debug_font(self.debug_font_size)
    local pad_x = 8
    local pad_y = 6
    local line_gap = 2
    local text_width = 0
    local line_height = font and font:getHeight() or 12
    for i = 1, #lines do
        text_width = math.max(text_width, font:getWidth(lines[i]))
    end

    local panel_width = math.max(1, math.min(target_width - pad_x * 2, text_width + pad_x * 2))
    local panel_height = (#lines * line_height) + math.max(0, #lines - 1) * line_gap + pad_y * 2

    love.graphics.push("all")
    love.graphics.origin()
    love.graphics.setShader()
    love.graphics.setMeshCullMode("none")
    love.graphics.setDepthMode("always", false)
    love.graphics.setFont(font)
    love.graphics.setColor(0, 0, 0, 0.72)
    love.graphics.rectangle("fill", 6, 6, panel_width, panel_height, 3, 3)
    love.graphics.setColor(0.92, 0.97, 1.0, 1)

    local text_y = 6 + pad_y
    for i = 1, #lines do
        love.graphics.printf(lines[i], 6 + pad_x, text_y, math.max(1, panel_width - pad_x * 2), "left")
        text_y = text_y + line_height + line_gap
    end
    love.graphics.pop()
end

-- shared stubs, allocating these closures per frame was pure garbage
local scene_pass_hotspot_start_noop = function() return nil end
local scene_pass_hotspot_add_noop = function() end
local scene_pass_note_slow_path_noop = function() end

-- only individual opaque cube color/prepass consumers use this decision
-- Bounds follow the retained render pose, including deliberate jitter suppression;
-- shadows and child layers retain their own selection/publication rules
function RBX:_individual_cube_color_outside(chunk, planes)
    return chunk.dynamic_chunk == true and self.use_instancing == true
        and chunk.cube_draw_mesh ~= nil and #(chunk.cube_instances or {}) > 0
        and bounds_outside_frustum(chunk.bounds, planes, 4)
end

function RBX:_prepare_scene_frame_packet(hotspot_start, hotspot_add, hotspots)
    local depth_clip_recompute_count = 0
    local cull_start = hotspot_start()
    self:_update_visible_scene()
    hotspot_add("cull_ms", cull_start)
    local culling_for_clip = self._culling_stats or {}
    local scene_opaque_count_for_clip = math.max(1, tonumber(self._opaque_part_count) or 0)
    local visible_opaque_count_for_clip = tonumber(culling_for_clip.visible_opaque_part_count) or 0
    local chunk_count_for_clip = math.max(1, tonumber(culling_for_clip.chunk_count) or 0)
    local visible_chunk_count_for_clip = tonumber(culling_for_clip.visible_opaque_chunk_count) or 0
    local suspicious_visible_clip_bounds = culling_for_clip.invalid_culling_input == true
        or (visible_opaque_count_for_clip <= math.max(2, scene_opaque_count_for_clip * 0.02)
            and visible_chunk_count_for_clip <= math.max(1, chunk_count_for_clip * 0.02))
    if self.auto_depth_clip
        and not suspicious_visible_clip_bounds
        and self._visible_scene_bounds
        and self._active_far_clip
        and self._active_near_clip then
        local motion_state = self._camera_motion_state or "steady"
        local depth_clip_interval = 1
        if motion_state == "moving" then
            depth_clip_interval = 4
        elseif motion_state == "settling" then
            depth_clip_interval = 2
        end
        if depth_clip_interval <= 1 or ((self._draw_scene_pass_id - 1) % depth_clip_interval) == 0 then
            local refined_far = RBX._compute_dynamic_far_clip_for_bounds(
                self.camera.cframe,
                self._visible_scene_bounds,
                self._active_near_clip,
                self._active_far_clip,
                self.depth_clip_margin
            )
            local refined_near = RBX._compute_dynamic_near_clip_for_bounds(
                self.camera.cframe,
                self._visible_scene_bounds,
                self._active_near_clip,
                refined_far,
                self.depth_clip_margin
            )
            local near_delta_ratio = relative_clip_change(self._active_near_clip, refined_near)
            local far_delta_ratio = relative_clip_change(self._active_far_clip, refined_far)
            if near_delta_ratio >= DEPTH_CLIP_REFINEMENT_MIN_DELTA_RATIO
                or far_delta_ratio >= DEPTH_CLIP_REFINEMENT_MIN_DELTA_RATIO then
                self:_apply_projection_clips(
                    self._last_width or 1,
                    self._last_height or 1,
                    self._projection_flip_y or 1,
                    refined_near,
                    refined_far
                )
                local recull_start = hotspot_start()
                self:_update_visible_scene()
                hotspot_add("cull_ms", recull_start)
                depth_clip_recompute_count = depth_clip_recompute_count + 1
            end
        end
    end

    local opaque_chunks = self._visible_opaque_chunks or {}
    local opaque_static_items = self._visible_static_draw_items or {}
    local opaque_textured_batches = self._visible_textured_batches or {}
    local opaque_overlay_textured_batches = self._visible_overlay_textured_batches or {}
    local visible_surface_gui_batches = self._visible_surface_gui_batches or {}
    local transparent_items = self._visible_transparent_draw_items or {}
    local empty_draw_list = self._empty_draw_list or {}
    self._empty_draw_list = empty_draw_list
    local mega_local_light_safe = self.enable_local_lights == false
        or (tonumber(self.local_light_count) or 0)
            <= math.max(0, tonumber(self.max_lights_per_batch) or 0)
    local mega_cube_path_active = self._mega_cube_path_active == true
        and mega_local_light_safe
        and self.use_instancing == true
        and self._mega_cube_draw_mesh ~= nil
        and (self._mega_instance_count or 0) > 0
    local primitive_mega_path_active = self._mega_primitive_path_active == true
        and mega_local_light_safe
        and self.use_instancing == true
        and type(self._mega_static_draw_items) == "table"
        and #self._mega_static_draw_items > 0
        and (self._mega_primitive_instance_count or 0) > 0
    -- deliberately not gated on mega_cube_path_active (static-only), dynamic-only scenes would never draw
    local dynamic_mega_active = self.use_instancing == true
        and mega_local_light_safe
        and self.dynamic_mega_dynamic_cubes == true
        and self._mega_dynamic_cube_draw_mesh ~= nil
        and (self._mega_dynamic_instance_count or 0) > 0
    if not dynamic_mega_active then
        -- static visibility may reuse a camera-tolerant result. always derive
        -- this cheap color decision from the current view, after clip refinement
        -- Lateral planes only: preserve the existing near/far and shadow domains
        local planes
        if self.enable_frustum_culling ~= false
            and RBX._matrix_is_finite(self._projection_matrix)
            and RBX._matrix_is_finite(self._view_matrix) then
            planes = extract_frustum_planes(multiply_matrices(
                self._projection_matrix, self._view_matrix))
        end
        local tested, rejected, pending = 0, 0, 0
        for i = 1, #opaque_chunks do
            local chunk = opaque_chunks[i]
            local outside = self:_individual_cube_color_outside(chunk, planes)
            chunk._cube_color_outside = outside
            if chunk.dynamic_chunk == true and #(chunk.cube_instances or {}) > 0 then
                tested = tested + 1
                if outside then
                    rejected = rejected + 1
                    if chunk._cube_pose_dirty then pending = pending + 1 end
                end
            end
            -- Re-entry publishes even without a new pose update. Rejection
            -- leaves the dirty flag pending, shadow fallback may still need it
            if not outside then self:_ensure_dynamic_chunk_cube_pose(chunk) end
        end
        self._individual_color_tests = (self._individual_color_tests or 0) + tested
        self._individual_color_rejected = (self._individual_color_rejected or 0) + rejected
        self._individual_color_deferred = (self._individual_color_deferred or 0) + pending
    end
    local local_light_pack_sorting_active =
        self.enable_local_light_pack_sorting ~= false
        and self.enable_local_lights ~= false
        and (tonumber(self.local_light_count) or 0) > 0
    local static_local_light_clusters_valid =
        self:_static_local_light_clusters_are_valid()
    local static_local_light_clusters =
        static_local_light_clusters_valid
            and self._static_local_light_clusters or nil
    -- must not follow the cube flag: per-chunk textured meshes are nil under locked config, would blank them
    local textured_mega_active = (mega_cube_path_active or self._textured_mega_locked == true)
    -- the composed lists only change when culling produced a new visible set (recompute
    -- or dynamic refresh), the scene rebuilt, or a mega flag flipped. Steady frames with
    -- a still camera used to re-copy all three lists every frame
    local cs1 = self._cull_recompute_count or 0
    local cs2 = self._cull_dynamic_refresh_count or 0
    local cs3 = self._scene_revision or 0
    local cs4 = local_light_pack_sorting_active
        and (self._local_light_revision or 0) or 0
    local composition_dirty = self._compose_sig1 ~= cs1
        or self._compose_sig2 ~= cs2
        or self._compose_sig3 ~= cs3
        or self._compose_sig4 ~= cs4
        or self._compose_mega_flag ~= mega_cube_path_active
        or self._compose_primitive_flag ~= primitive_mega_path_active
        or self._compose_tex_flag ~= textured_mega_active
        or self._compose_light_sort_flag ~= local_light_pack_sorting_active
        or self._compose_light_cluster_generation
            ~= static_local_light_clusters
    self._compose_sig1, self._compose_sig2, self._compose_sig3, self._compose_sig4 =
        cs1, cs2, cs3, cs4
    self._compose_mega_flag = mega_cube_path_active
    self._compose_primitive_flag = primitive_mega_path_active
    self._compose_tex_flag = textured_mega_active
    self._compose_light_sort_flag = local_light_pack_sorting_active
    self._compose_light_cluster_generation =
        static_local_light_clusters

    if primitive_mega_path_active and self._mega_static_draw_items then
        if composition_dirty or not self._mega_visible_static_draw_items_buffer then
            opaque_static_items = self:_compose_mega_static_draw_list(
                self._mega_static_draw_items,
                opaque_static_items,
                self._mega_visible_static_draw_items_buffer
            )
            self._mega_visible_static_draw_items_buffer = opaque_static_items
        else
            opaque_static_items = self._mega_visible_static_draw_items_buffer
        end
    end
    if textured_mega_active and self._mega_textured_batches then
        if composition_dirty or not self._mega_visible_textured_batches_buffer then
            opaque_textured_batches = self:_compose_mega_textured_draw_list(
                self._mega_textured_batches,
                opaque_textured_batches,
                self._mega_visible_textured_batches_buffer
            )
            self._mega_visible_textured_batches_buffer = opaque_textured_batches
        else
            opaque_textured_batches = self._mega_visible_textured_batches_buffer
        end
    end
    if textured_mega_active and self._mega_overlay_textured_batches then
        if composition_dirty or not self._mega_visible_overlay_textured_batches_buffer then
            opaque_overlay_textured_batches = self:_compose_mega_textured_draw_list(
                self._mega_overlay_textured_batches,
                opaque_overlay_textured_batches,
                self._mega_visible_overlay_textured_batches_buffer
            )
            self._mega_visible_overlay_textured_batches_buffer = opaque_overlay_textured_batches
        else
            opaque_overlay_textured_batches = self._mega_visible_overlay_textured_batches_buffer
        end
    end
    if self.disable_static_pass then
        opaque_static_items = empty_draw_list
    end
    if self.disable_textured_pass then
        opaque_textured_batches = empty_draw_list
        opaque_overlay_textured_batches = empty_draw_list
        visible_surface_gui_batches = empty_draw_list
    end
    if self.disable_transparent_pass then
        transparent_items = empty_draw_list
    end
    local light_cluster_stats = self._static_local_light_clusters
        and self._static_local_light_clusters.stats or nil
    local light_sort_stats = self._opaque_local_light_sort_stats
    if not light_sort_stats then
        light_sort_stats = {}
        self._opaque_local_light_sort_stats = light_sort_stats
    end
    -- sort the unclustered sources first. the exact payload/geometry/spatial
    -- order is shared by the A/B fallback and makes every aggregate's source
    -- rows contiguous and deterministic before a draw boundary is removed
    if local_light_pack_sorting_active and #opaque_static_items > 1 then
        if composition_dirty
            or not self._opaque_light_sorted_static_items_buffer then
            opaque_static_items, light_sort_stats.static_pack_count =
                self:_copy_and_sort_opaque_draw_list_by_local_light_pack(
                    opaque_static_items,
                    self._opaque_light_sorted_static_items_buffer)
            self._opaque_light_sorted_static_items_buffer =
                opaque_static_items
            light_sort_stats.static_item_count = #opaque_static_items
        else
            opaque_static_items =
                self._opaque_light_sorted_static_items_buffer
        end
    elseif local_light_pack_sorting_active then
        light_sort_stats.static_pack_count = #opaque_static_items
    else
        light_sort_stats.static_pack_count = 0
    end
    if static_local_light_clusters
        and not primitive_mega_path_active
        and #opaque_static_items > 0 then
        if composition_dirty
            or not self._clustered_opaque_static_items_buffer then
            local primitive_draws_saved
            local primitive_cluster_draw_count
            opaque_static_items,
                primitive_draws_saved,
                primitive_cluster_draw_count =
                self:_compose_static_local_light_cluster_draw_list(
                    opaque_static_items,
                    static_local_light_clusters.primitive_by_source,
                    self._clustered_opaque_static_items_buffer)
            self._clustered_opaque_static_items_buffer =
                opaque_static_items
            light_cluster_stats.active_primitive_draws_saved =
                primitive_draws_saved
            light_cluster_stats.active_primitive_cluster_draw_count =
                primitive_cluster_draw_count
        else
            opaque_static_items =
                self._clustered_opaque_static_items_buffer
        end
    elseif light_cluster_stats then
        light_cluster_stats.active_primitive_draws_saved = 0
        light_cluster_stats.active_primitive_cluster_draw_count = 0
    end
    light_sort_stats.static_item_count =
        local_light_pack_sorting_active and #opaque_static_items or 0
    -- per-chunk cube-draw lists, precomposed so the prepass/opaque loops only touch
    -- chunks that actually issue a draw (O(active draws), not O(visible chunks)), under
    -- the full mega path both lists are empty and the loops vanish. Chunks keep their
    -- live instance_count/mesh guards at draw time, only membership rides the compose
    local raw_chunk_cube_draw_list =
        self._raw_chunk_cube_draw_list_buffer
    local raw_chunk_static_cube_list =
        self._raw_chunk_static_cube_list_buffer
    local chunk_cube_draw_list = self._chunk_cube_draw_list_buffer
    local chunk_static_cube_list = self._chunk_static_cube_list_buffer
    if composition_dirty
        or not raw_chunk_cube_draw_list
        or not raw_chunk_static_cube_list
        or not chunk_cube_draw_list
        or not chunk_static_cube_list
        or self._chunk_draw_lists_mega_flag ~= mega_cube_path_active
        or self._chunk_draw_lists_dyn_flag ~= dynamic_mega_active
        or self._chunk_draw_lists_instancing_flag ~= (self.use_instancing == true) then
        raw_chunk_cube_draw_list = raw_chunk_cube_draw_list or {}
        raw_chunk_static_cube_list =
            raw_chunk_static_cube_list or {}
        chunk_cube_draw_list = chunk_cube_draw_list or {}
        chunk_static_cube_list = chunk_static_cube_list or {}
        clear_draw_list(raw_chunk_cube_draw_list)
        clear_draw_list(raw_chunk_static_cube_list)
        local use_instancing = self.use_instancing == true
        for i = 1, #opaque_chunks do
            local chunk = opaque_chunks[i]
            if chunk.instance_count > 0 then
                if chunk.cube_draw_mesh
                    and not (dynamic_mega_active and chunk.dynamic_chunk == true)
                    and (not mega_cube_path_active or chunk.dynamic_chunk == true) then
                    raw_chunk_cube_draw_list[
                        #raw_chunk_cube_draw_list + 1] = chunk
                end
                if (not use_instancing or not chunk.instance_mesh)
                    and chunk.static_cube_mesh
                    and not (mega_cube_path_active and chunk.dynamic_chunk ~= true)
                    and not (dynamic_mega_active and chunk.dynamic_chunk == true) then
                    raw_chunk_static_cube_list[
                        #raw_chunk_static_cube_list + 1] = chunk
                end
            end
        end
        if local_light_pack_sorting_active then
            raw_chunk_cube_draw_list,
                light_sort_stats.cube_pack_count =
                self:_sort_opaque_draw_list_by_local_light_pack(
                    raw_chunk_cube_draw_list)
            raw_chunk_static_cube_list,
                light_sort_stats.static_cube_pack_count =
                self:_sort_opaque_draw_list_by_local_light_pack(
                    raw_chunk_static_cube_list)
        else
            light_sort_stats.cube_pack_count = 0
            light_sort_stats.static_cube_pack_count = 0
        end
        if static_local_light_clusters
            and not mega_cube_path_active then
            local cube_draws_saved
            local cube_cluster_draw_count
            chunk_cube_draw_list,
                cube_draws_saved,
                cube_cluster_draw_count =
                self:_compose_static_local_light_cluster_draw_list(
                    raw_chunk_cube_draw_list,
                    static_local_light_clusters.cube_by_source,
                    chunk_cube_draw_list)
            light_cluster_stats.active_cube_draws_saved =
                cube_draws_saved
            light_cluster_stats.active_cube_cluster_draw_count =
                cube_cluster_draw_count
        else
            clear_draw_list(chunk_cube_draw_list)
            for index = 1, #raw_chunk_cube_draw_list do
                chunk_cube_draw_list[index] =
                    raw_chunk_cube_draw_list[index]
            end
            if light_cluster_stats then
                light_cluster_stats.active_cube_draws_saved = 0
                light_cluster_stats.active_cube_cluster_draw_count = 0
            end
        end
        clear_draw_list(chunk_static_cube_list)
        for index = 1, #raw_chunk_static_cube_list do
            chunk_static_cube_list[index] =
                raw_chunk_static_cube_list[index]
        end
        if local_light_pack_sorting_active then
            light_sort_stats.cube_draw_count = #chunk_cube_draw_list
            light_sort_stats.static_cube_draw_count =
                #chunk_static_cube_list
        else
            light_sort_stats.cube_draw_count = 0
            light_sort_stats.cube_pack_count = 0
            light_sort_stats.static_cube_draw_count = 0
            light_sort_stats.static_cube_pack_count = 0
        end
        self._raw_chunk_cube_draw_list_buffer =
            raw_chunk_cube_draw_list
        self._raw_chunk_static_cube_list_buffer =
            raw_chunk_static_cube_list
        self._chunk_cube_draw_list_buffer = chunk_cube_draw_list
        self._chunk_static_cube_list_buffer = chunk_static_cube_list
        self._chunk_draw_lists_mega_flag = mega_cube_path_active
        self._chunk_draw_lists_dyn_flag = dynamic_mega_active
        self._chunk_draw_lists_instancing_flag = use_instancing
    end
    local opaque_surface_geometry_batches = self._opaque_surface_geometry_batches_buffer or {}
    local opaque_base_textured_batches = self._opaque_base_textured_batches_buffer or {}
    local surface_gui_overlay_batches = self._surface_gui_overlay_batches_buffer or {}
    local decal_overlay_textured_batches = self._decal_overlay_textured_batches_buffer or {}
    local transparent_surface_gui_items = self._transparent_surface_gui_items_buffer or {}
    local transparent_regular_items = self._transparent_regular_items_buffer or {}
    self._opaque_surface_geometry_batches_buffer = opaque_surface_geometry_batches
    self._opaque_base_textured_batches_buffer = opaque_base_textured_batches
    self._surface_gui_overlay_batches_buffer = surface_gui_overlay_batches
    self._decal_overlay_textured_batches_buffer = decal_overlay_textured_batches
    self._transparent_surface_gui_items_buffer = transparent_surface_gui_items
    self._transparent_regular_items_buffer = transparent_regular_items
    -- opaque splits ride the same dirtiness as the compose above, the transparent split
    -- below must run every frame (it doubles as the reset for the billboard appends)
    if composition_dirty or (self._opaque_split_valid ~= true)
        or self.disable_textured_pass then
        opaque_textured_batches, opaque_surface_geometry_batches = split_draw_list_by_source_kind(
            opaque_textured_batches,
            "SurfaceGeometry",
            opaque_base_textured_batches,
            opaque_surface_geometry_batches
        )
        opaque_overlay_textured_batches, surface_gui_overlay_batches = split_draw_list_by_source_kind(
            opaque_overlay_textured_batches,
            "SurfaceGui",
            decal_overlay_textured_batches,
            surface_gui_overlay_batches
        )
        self:_order_same_face_surface_gui_items(surface_gui_overlay_batches)
        self._opaque_split_valid = not self.disable_textured_pass
    else
        opaque_textured_batches = opaque_base_textured_batches
        -- opaque_surface_geometry_batches / surface_gui_overlay_batches /
        -- decal_overlay_textured_batches already hold last frame's split results
        opaque_overlay_textured_batches = decal_overlay_textured_batches
    end
    transparent_items, transparent_surface_gui_items = split_draw_list_by_source_kind(
        transparent_items,
        "SurfaceGui",
        transparent_regular_items,
        transparent_surface_gui_items
    )
    local surface_gui_update_start = love.timer.getTime()
    self:_update_surface_gui_canvases(visible_surface_gui_batches)
    -- rebuilt from camera basis each frame, ride the transparent surfacegui pass
    if self._update_billboard_quads then
        local billboard_items = self:_update_billboard_quads()
        for index = 1, #(billboard_items or {}) do
            transparent_surface_gui_items[#transparent_surface_gui_items + 1] = billboard_items[index]
        end
    end
    -- raw-texture quads, same transparent pass
    if self._update_sprite_billboard_quads then
        local sprite_items = self:_update_sprite_billboard_quads()
        for index = 1, #(sprite_items or {}) do
            transparent_surface_gui_items[#transparent_surface_gui_items + 1] = sprite_items[index]
        end
    end
    transparent_items,transparent_surface_gui_items=self:_compose_world_gui_draw_items(
        transparent_items,surface_gui_overlay_batches,transparent_surface_gui_items)
    surface_gui_overlay_batches=empty_draw_list
    local transparent_gui_sort_start = hotspot_start()
    self:_sort_transparent_gui_draw_items(transparent_surface_gui_items)
    hotspot_add("transparent_sort_ms", transparent_gui_sort_start)
    local surface_gui_update_ms = math.max(0, (love.timer.getTime() - surface_gui_update_start) * 1000)
    if hotspots then
        hotspots.surfacegui_update_ms = surface_gui_update_ms
    end
    self._surface_gui_last_update_ms = surface_gui_update_ms
    local has_opaque = #opaque_chunks > 0
        or #opaque_static_items > 0
        or #opaque_textured_batches > 0
        or #opaque_surface_geometry_batches > 0
        or #opaque_overlay_textured_batches > 0
        or #surface_gui_overlay_batches > 0
    local has_transparent = #transparent_items > 0 or #transparent_surface_gui_items > 0
    local active_opaque_depth_prepass_mode = has_opaque and self:_get_active_opaque_depth_prepass_mode() or "off"

    local packet = self._scene_frame_packet
    if not packet then
        packet = {}
        self._scene_frame_packet = packet
    end
    packet.depth_clip_recompute_count = depth_clip_recompute_count
    packet.opaque_chunks = opaque_chunks
    packet.opaque_static_items = opaque_static_items
    packet.opaque_textured_batches = opaque_textured_batches
    packet.opaque_surface_geometry_batches = opaque_surface_geometry_batches
    packet.opaque_overlay_textured_batches = opaque_overlay_textured_batches
    packet.surface_gui_overlay_batches = surface_gui_overlay_batches
    packet.transparent_items = transparent_items
    packet.transparent_surface_gui_items = transparent_surface_gui_items
    packet.chunk_cube_draw_list = chunk_cube_draw_list
    packet.chunk_static_cube_list = chunk_static_cube_list
    packet.mega_cube_path_active = mega_cube_path_active
    packet.dynamic_mega_active = dynamic_mega_active
    packet.surface_gui_update_ms = surface_gui_update_ms
    packet.has_opaque = has_opaque
    packet.has_transparent = has_transparent
    packet.active_opaque_depth_prepass_mode = active_opaque_depth_prepass_mode
    return packet
end

function RBX:_draw_scene_pass()
    local submission_start = love.timer.getTime()
    local collect_hotspot_stats = self.collect_hotspot_stats == true
    local hotspots = collect_hotspot_stats and {} or nil
    self._frame_hotspots = hotspots
    self._frame_fallback_slow_path_count = 0
    -- reused, cleared in place, only ever describes the current frame
    local slow_path_reasons = self._frame_fallback_slow_path_reasons
    if slow_path_reasons then
        for key in pairs(slow_path_reasons) do slow_path_reasons[key] = nil end
    else
        slow_path_reasons = {}
        self._frame_fallback_slow_path_reasons = slow_path_reasons
    end
    local hotspot_start
    local hotspot_add
    local note_slow_path
    if collect_hotspot_stats then
        hotspot_start = function()
            return love.timer.getTime()
        end
        hotspot_add = function(field, started_at)
            if started_at then
                hotspots[field] = (hotspots[field] or 0) + math.max(0, (love.timer.getTime() - started_at) * 1000)
            end
        end
        note_slow_path = function(reason)
            self._frame_fallback_slow_path_count = (self._frame_fallback_slow_path_count or 0) + 1
            local reasons = self._frame_fallback_slow_path_reasons
            reasons[reason] = (reasons[reason] or 0) + 1
        end
    else
        hotspot_start = scene_pass_hotspot_start_noop
        hotspot_add = scene_pass_hotspot_add_noop
        note_slow_path = scene_pass_note_slow_path_noop
    end
    self._surface_gui_frame_id = (self._surface_gui_frame_id or 0) + 1
    self._draw_scene_pass_id = (self._draw_scene_pass_id or 0) + 1
    self._frame_instance_attribute_attach_count = 0
    self._frame_uniform_send_count = 0
    self._frame_lighting_uniform_send_count = 0
    self._frame_local_light_uniform_send_count = 0
    self._frame_local_light_uniform_packet_send_count = 0
    self._frame_local_light_uniform_legacy_send_count = 0
    self._frame_local_light_uniform_packet_fallback_send_count = 0
    self._frame_local_light_uniform_packet_failure_count = 0
    self._frame_local_light_uniform_packet_sanitized_value_count = 0
    self._frame_instanced_mesh_uniform_send_count = 0
    -- fixed key set rebuilt every frame: reuse table in place
    local light_stats = self._local_light_stats
    if not light_stats then
        light_stats = {}
        self._local_light_stats = light_stats
    end
    light_stats.max_lights_per_batch = self.max_lights_per_batch or 4
    light_stats.max_dynamic_shadow_lights = self.max_dynamic_shadow_lights or 0
    light_stats.lights_considered = 0
    light_stats.lights_selected = 0
    light_stats.lights_culled_by_range = 0
    light_stats.lights_culled_by_frustum = 0
    light_stats.light_grid_update_ms = light_stats.light_grid_update_ms or 0
    light_stats.local_light_uniform_sends = 0
    light_stats.local_light_uniform_packet_sends = 0
    light_stats.local_light_uniform_legacy_sends = 0
    light_stats.local_light_uniform_packet_fallback_sends = 0
    light_stats.local_light_uniform_packet_failures = 0
    light_stats.local_light_uniform_packet_sanitized_values = 0
    light_stats.overflow_lights_ambient_approximated = 0
    light_stats.compact_packs_built = 0
    self:_update_dirty_local_lights()
    self:_sync_local_light_pack_configuration()
    self:_maintain_static_local_light_clusters()
    self._frame_skybox_draw_call_count = 0
    self._frame_celestial_draw_count = 0
    self._frame_celestial_draw_ms = 0
    self._frame_sky_draw_ms = 0
    self._mesh_uploads_this_frame = 0
    local pass_timings = {}
    local skybox_pass_start = love.timer.getTime()
    self:_draw_skybox()
    pass_timings.skybox_ms = math.max(0, (love.timer.getTime() - skybox_pass_start) * 1000)

    local shader_switch_count = 0
    local depth_mode_switch_count = 0
    local cull_mode_switch_count = 0
    local blend_mode_switch_count = 0
    local shader_set_attempt_count = 0
    local depth_mode_set_attempt_count = 0
    local cull_mode_set_attempt_count = 0
    local blend_mode_set_attempt_count = 0
    local active_shader = false
    local active_depth_compare = nil
    local active_depth_write = nil
    local active_cull_mode = nil
    local active_blend_mode = nil
    local active_blend_alpha_mode = nil

    local set_shader
    local set_depth_mode
    local set_cull_mode
    local set_blend_mode
    if collect_hotspot_stats then
        set_shader = function(shader)
            shader_set_attempt_count = shader_set_attempt_count + 1
            if not rawequal(active_shader, shader) then
                local state_start = love.timer.getTime()
                love.graphics.setShader(shader)
                hotspot_add("state_change_ms", state_start)
                active_shader = shader
                shader_switch_count = shader_switch_count + 1
            end
        end
        set_depth_mode = function(compare, write)
            depth_mode_set_attempt_count = depth_mode_set_attempt_count + 1
            if active_depth_compare ~= compare or active_depth_write ~= write then
                local state_start = love.timer.getTime()
                love.graphics.setDepthMode(compare, write)
                hotspot_add("state_change_ms", state_start)
                active_depth_compare = compare
                active_depth_write = write
                depth_mode_switch_count = depth_mode_switch_count + 1
            end
        end
        set_cull_mode = function(mode)
            cull_mode_set_attempt_count = cull_mode_set_attempt_count + 1
            if active_cull_mode ~= mode then
                local state_start = love.timer.getTime()
                love.graphics.setMeshCullMode(mode)
                hotspot_add("state_change_ms", state_start)
                active_cull_mode = mode
                cull_mode_switch_count = cull_mode_switch_count + 1
            end
        end
        set_blend_mode = function(mode, alpha_mode)
            mode = mode or "alpha"
            alpha_mode = alpha_mode or "alphamultiply"
            blend_mode_set_attempt_count = blend_mode_set_attempt_count + 1
            if active_blend_mode ~= mode or active_blend_alpha_mode ~= alpha_mode then
                local state_start = love.timer.getTime()
                love.graphics.setBlendMode(mode, alpha_mode)
                hotspot_add("state_change_ms", state_start)
                active_blend_mode = mode
                active_blend_alpha_mode = alpha_mode
                blend_mode_switch_count = blend_mode_switch_count + 1
            end
        end
    else
        set_shader = function(shader)
            shader_set_attempt_count = shader_set_attempt_count + 1
            if not rawequal(active_shader, shader) then
                love.graphics.setShader(shader)
                active_shader = shader
                shader_switch_count = shader_switch_count + 1
            end
        end
        set_depth_mode = function(compare, write)
            depth_mode_set_attempt_count = depth_mode_set_attempt_count + 1
            if active_depth_compare ~= compare or active_depth_write ~= write then
                love.graphics.setDepthMode(compare, write)
                active_depth_compare = compare
                active_depth_write = write
                depth_mode_switch_count = depth_mode_switch_count + 1
            end
        end
        set_cull_mode = function(mode)
            cull_mode_set_attempt_count = cull_mode_set_attempt_count + 1
            if active_cull_mode ~= mode then
                love.graphics.setMeshCullMode(mode)
                active_cull_mode = mode
                cull_mode_switch_count = cull_mode_switch_count + 1
            end
        end
        set_blend_mode = function(mode, alpha_mode)
            mode = mode or "alpha"
            alpha_mode = alpha_mode or "alphamultiply"
            blend_mode_set_attempt_count = blend_mode_set_attempt_count + 1
            if active_blend_mode ~= mode or active_blend_alpha_mode ~= alpha_mode then
                love.graphics.setBlendMode(mode, alpha_mode)
                active_blend_mode = mode
                active_blend_alpha_mode = alpha_mode
                blend_mode_switch_count = blend_mode_switch_count + 1
            end
        end
    end

    -- Textured shader output representation is a shader contract, not a pass
    -- property. the overlay shader emits premultiplied RGB, every other
    -- textured shader emits straight RGB. Selecting the alpha mode from the
    -- live shader prevents both alpha-squared overlays and bright fringes when
    -- SurfaceOverlay/full-material draws share an overlay queue
    local function set_textured_output_blend(shader)
        set_blend_mode(
            "alpha",
            self:_get_textured_shader_alpha_mode(shader))
    end

    local frame_packet = self:_prepare_scene_frame_packet(hotspot_start, hotspot_add, hotspots)
    local depth_clip_recompute_count = frame_packet.depth_clip_recompute_count
    local opaque_chunks = frame_packet.opaque_chunks
    local opaque_static_items = frame_packet.opaque_static_items
    local opaque_textured_batches = frame_packet.opaque_textured_batches
    local opaque_surface_geometry_batches = frame_packet.opaque_surface_geometry_batches
    local opaque_overlay_textured_batches = frame_packet.opaque_overlay_textured_batches
    local surface_gui_overlay_batches = frame_packet.surface_gui_overlay_batches
    local transparent_items = RBX._world_mesh.collect(self, frame_packet.transparent_items)
    local transparent_surface_gui_items = frame_packet.transparent_surface_gui_items
    local chunk_cube_draw_list = frame_packet.chunk_cube_draw_list
    local chunk_static_cube_list = frame_packet.chunk_static_cube_list
    local mega_cube_path_active = frame_packet.mega_cube_path_active
    local dynamic_mega_active = frame_packet.dynamic_mega_active
    local surface_gui_update_ms = frame_packet.surface_gui_update_ms
    local has_opaque = frame_packet.has_opaque
    local has_transparent = frame_packet.has_transparent or #transparent_items > 0
    local active_opaque_depth_prepass_mode = frame_packet.active_opaque_depth_prepass_mode
    local directional_shadow_start = love.timer.getTime()
    self:_update_directional_shadow_atlas()
    pass_timings.directional_shadow_ms = math.max(
        0, (love.timer.getTime() - directional_shadow_start) * 1000)
    -- LÃƒÆ’Ã¢â‚¬â€œVE 11.5 discards temporary depth=true attachments on a Canvas switch
    -- SurfaceGui preparation and shadow-atlas refresh can therefore invalidate
    -- the entry-point clear. initialize scene depth only after those passes,
    -- before any world geometry, preserve the already-rendered sky color
    love.graphics.clear(false, false, 1)
    local constraint_visuals = RBX._constraint_visuals.prepare(self)
    if not has_opaque and not has_transparent and not constraint_visuals then
        self._draw_stats = {
            draw_call_count = 0,
            opaque_depth_prepass_draw_call_count = 0,
            textured_variant_draw_counts = {},
            texture_array_batch_count = 0,
            legacy_textured_batch_count = 0,
            surface_appearance_batch_count = 0,
            surface_gui_visible_batch_count = 0,
            surface_gui_updated_batch_count = 0,
            surface_gui_deferred_batch_count = (self._surface_gui_stats and self._surface_gui_stats.deferred_batch_count) or
                0,
            surface_gui_catchup_batch_count = (self._surface_gui_stats and self._surface_gui_stats.catchup_batch_count) or
                0,
            surface_gui_dirty_count = (self._surface_gui_stats and self._surface_gui_stats.dirty_count) or 0,
            surface_gui_update_ms = surface_gui_update_ms,
            depth_clip_recompute_count = depth_clip_recompute_count,
            instanced_cube_draw_call_count = 0,
            instanced_primitive_draw_call_count = 0,
            static_mesh_draw_call_count = 0,
            textured_draw_call_count = 0,
            transparent_draw_call_count = 0,
            skybox_draw_call_count = self._frame_skybox_draw_call_count or 0,
            shader_switch_count = shader_switch_count,
            depth_mode_switch_count = depth_mode_switch_count,
            cull_mode_switch_count = cull_mode_switch_count,
            blend_mode_switch_count = blend_mode_switch_count,
            shader_set_attempt_count = shader_set_attempt_count,
            depth_mode_set_attempt_count = depth_mode_set_attempt_count,
            cull_mode_set_attempt_count = cull_mode_set_attempt_count,
            blend_mode_set_attempt_count = blend_mode_set_attempt_count,
            uniform_send_count = self._frame_uniform_send_count or 0,
            lighting_uniform_send_count = self._frame_lighting_uniform_send_count or 0,
            local_light_uniform_send_count = self._frame_local_light_uniform_send_count or 0,
            local_light_uniform_packet_send_count =
                self._frame_local_light_uniform_packet_send_count or 0,
            local_light_uniform_legacy_send_count =
                self._frame_local_light_uniform_legacy_send_count or 0,
            local_light_uniform_packet_fallback_send_count =
                self._frame_local_light_uniform_packet_fallback_send_count or 0,
            local_light_uniform_packet_failure_count =
                self._frame_local_light_uniform_packet_failure_count or 0,
            local_light_uniform_packet_sanitized_value_count =
                self._frame_local_light_uniform_packet_sanitized_value_count or 0,
            local_light_uniform_packet_available =
                self._local_light_uniform_packet_available == true,
            local_light_uniform_packet_allocation_count =
                self._local_light_uniform_packet_allocation_count or 0,
            local_light_uniform_packet_shader_fallback_count =
                self._local_light_uniform_packet_shader_fallback_count or 0,
            local_light_uniform_packet_global_fallback_reason =
                self._local_light_uniform_packet_global_fallback_reason,
            local_light_uniform_packet_last_shader_error =
                self._local_light_uniform_packet_last_shader_error,
            instanced_mesh_uniform_send_count =
                self._frame_instanced_mesh_uniform_send_count or 0,
            local_light_stats = self._local_light_stats or {},
            texture_switch_count = 0,
            draw_packet_build_ms = self._last_draw_packet_build_ms or 0,
            pass_timings = pass_timings,
            hotspots = hotspots,
            fallback_slow_path_count = self._frame_fallback_slow_path_count or 0,
            fallback_slow_path_reasons = self._frame_fallback_slow_path_reasons or {},
            textured_full_shader_draw_call_count = 0,
            textured_fast_shader_draw_call_count = 0,
            textured_constant_shader_draw_call_count = 0,
            textured_constant_unlit_draw_call_count = 0,
            textured_basic_opaque_draw_call_count = 0,
            textured_lit_nomaps_draw_call_count = 0,
            textured_overlay_decal_draw_call_count = 0,
            textured_full_material_draw_call_count = 0,
            textured_transparent_variant_draw_call_count = 0,
            alpha_like_draw_call_count = 0,
            shader_discard_draw_call_count = 0,
            attach_attribute_draw_count = self._frame_instance_attribute_attach_count or 0,
            attach_attribute_build_count = self._instance_attribute_attach_build_count or 0,
            mega_cube_path_active = mega_cube_path_active,
            submitted_chunk_count = #opaque_chunks,
            submitted_cube_instance_count = 0,
            submitted_static_item_count = #opaque_static_items,
            submitted_textured_batch_count = #opaque_textured_batches + #opaque_surface_geometry_batches,
            submitted_overlay_textured_batch_count = #opaque_overlay_textured_batches + #surface_gui_overlay_batches,
            submitted_transparent_item_count = #transparent_items + #transparent_surface_gui_items,
            opaque_depth_prepass_mode = active_opaque_depth_prepass_mode or "off",
        }
        self._last_draw_submission_ms = (love.timer.getTime() - submission_start) * 1000
        return
    end

    local draw_call_count = 0
    local opaque_depth_prepass_draw_call_count = 0
    local collect_detailed_draw_stats = self.collect_detailed_draw_stats == true or self:_is_debug_overlay_enabled()
    local textured_variant_draw_counts = collect_detailed_draw_stats and {} or nil
    local texture_array_batch_count = 0
    local legacy_textured_batch_count = 0
    local surface_appearance_batch_count = 0
    local instanced_cube_draw_call_count = 0
    local instanced_primitive_draw_call_count = 0
    local instanced_mesh_draw_call_count = 0
    local static_mesh_draw_call_count = 0
    local textured_draw_call_count = 0
    local transparent_draw_call_count = 0
    local textured_full_shader_draw_call_count = 0
    local textured_fast_shader_draw_call_count = 0
    local textured_constant_shader_draw_call_count = 0
    local textured_constant_unlit_draw_call_count = 0
    local textured_basic_opaque_draw_call_count = 0
    local textured_lit_nomaps_draw_call_count = 0
    local textured_overlay_decal_draw_call_count = 0
    local textured_full_material_draw_call_count = 0
    local textured_transparent_variant_draw_call_count = 0
    local alpha_like_draw_call_count = 0
    local shader_discard_draw_call_count = 0
    local texture_switch_count = 0
    local active_texture = nil
    local has_instanced_primitive_items = false
    for index = 1, #opaque_static_items do
        local item = opaque_static_items[index]
        if item.kind == "instanced_primitive"
            and item.draw_mesh
            and (item.count or 0) > 0 then
            has_instanced_primitive_items = true
            break
        end
    end

    local function note_textured_draw(shader, texture, item)
        if type(item) == "table" and item.face_array_texture ~= nil then
            texture = item.face_array_texture
        end
        local counter_key = item and item.shader_counter_key or nil
        if not counter_key then
            note_slow_path("missing_shader_counter_key")
            counter_key = "full"
        end
        if counter_key == "constant" then
            textured_constant_shader_draw_call_count = textured_constant_shader_draw_call_count + 1
        elseif counter_key == "fast" then
            textured_fast_shader_draw_call_count = textured_fast_shader_draw_call_count + 1
        else
            textured_full_shader_draw_call_count = textured_full_shader_draw_call_count + 1
        end
        if texture ~= nil and not rawequal(texture, active_texture) then
            texture_switch_count = texture_switch_count + 1
            active_texture = texture
        end
        if type(item) == "table" then
            local variant_counter_id = item.variant_counter_id or 0
            if variant_counter_id == 1 then
                textured_constant_unlit_draw_call_count = textured_constant_unlit_draw_call_count + 1
            elseif variant_counter_id == 2 then
                textured_basic_opaque_draw_call_count = textured_basic_opaque_draw_call_count + 1
            elseif variant_counter_id == 3 then
                textured_lit_nomaps_draw_call_count = textured_lit_nomaps_draw_call_count + 1
            elseif variant_counter_id == 4 then
                textured_overlay_decal_draw_call_count = textured_overlay_decal_draw_call_count + 1
            elseif variant_counter_id == 5 then
                textured_full_material_draw_call_count = textured_full_material_draw_call_count + 1
            elseif variant_counter_id == 6 then
                textured_transparent_variant_draw_call_count = textured_transparent_variant_draw_call_count + 1
            end
            if item.alpha_like == true then
                alpha_like_draw_call_count = alpha_like_draw_call_count + 1
            end
            if item.uses_shader_discard == true then
                shader_discard_draw_call_count = shader_discard_draw_call_count + 1
            end
        end
    end

    local function get_textured_shader(item)
        if type(item) == "table" and item.shader then
            return item.shader
        end
        note_slow_path("missing_precomputed_shader")
        local shader_select_start = hotspot_start()
        local shader = self:_get_textured_shader_for_item(item)
        hotspot_add("shader_select_ms", shader_select_start)
        return shader
    end

    local draw_textured_mesh
    local draw_static_mesh
    local draw_instanced_mesh
    local send_depth_common_uniforms
    local send_instanced_depth_uniforms
    local send_static_depth_uniforms
    local send_textured_depth_uniforms
    local send_common_uniforms
    local send_instanced_draw_uniforms
    local send_static_draw_uniforms
    local send_textured_common_uniforms
    local send_textured_draw_uniforms
    local send_local_light_uniforms
    if collect_hotspot_stats then
        local function add_uniform_hotspot(field, started_at)
            local elapsed_ms = math.max(
                0,
                (love.timer.getTime() - started_at) * 1000)
            hotspots.uniform_send_ms =
                (hotspots.uniform_send_ms or 0) + elapsed_ms
            hotspots[field] =
                (hotspots[field] or 0) + elapsed_ms
        end
        local function textured_submit_hotspot_field(item)
            if type(item) ~= "table" then
                return "basepart_submit_ms"
            end
            if item.source_kind == "SurfaceGui" then
                return "surfacegui_draw_ms"
            end
            if (tonumber(item.union_part_count) or 0) > 0 then
                return "union_submit_ms"
            end
            if (tonumber(item.specialmesh_count) or 0) > 0 then
                return "specialmesh_submit_ms"
            end
            if (tonumber(item.mesh_part_count) or 0) > 0 then
                return "mesh_submit_ms"
            end
            if (tonumber(item.surface_geometry_face_count) or 0) > 0 then
                return "surface_detail_draw_ms"
            end
            if (tonumber(item.surface_shader_face_count) or 0) > 0 then
                return "surface_detail_draw_ms"
            end
            return "basepart_submit_ms"
        end
        draw_textured_mesh = function(
            item, range_first, range_count)
            if not item.mesh then return end -- deferred, mega path draws the mega copy
            if item.runtime_sampler_wrap_mode and item.texture
                and item.texture.setWrap then
                item.texture:setWrap(
                    item.runtime_sampler_wrap_mode,
                    item.runtime_sampler_wrap_mode)
            end
            range_first =
                range_first or item._transparent_range_first
            range_count =
                range_count or item._transparent_range_count
            if range_first and range_count then
                item.mesh:setDrawRange(
                    range_first, range_count)
            end
            local draw_start = love.timer.getTime()
            love.graphics.draw(item.mesh)
            hotspot_add(textured_submit_hotspot_field(item), draw_start)
        end
        draw_static_mesh = function(mesh)
            local draw_start = love.timer.getTime()
            love.graphics.draw(mesh)
            hotspot_add("basepart_submit_ms", draw_start)
        end
        draw_instanced_mesh = function(mesh, count)
            local draw_start = love.timer.getTime()
            love.graphics.drawInstanced(mesh, count)
            hotspot_add("basepart_submit_ms", draw_start)
        end
        send_depth_common_uniforms = function(shader)
            local uniform_start = love.timer.getTime()
            self:_send_depth_common_uniforms(shader)
            add_uniform_hotspot("depth_uniform_ms", uniform_start)
        end
        send_instanced_depth_uniforms = function(depth_bias)
            local uniform_start = love.timer.getTime()
            self:_send_instanced_depth_uniforms(depth_bias)
            add_uniform_hotspot("depth_uniform_ms", uniform_start)
        end
        send_static_depth_uniforms = function(depth_bias)
            local uniform_start = love.timer.getTime()
            self:_send_static_depth_uniforms(depth_bias)
            add_uniform_hotspot("depth_uniform_ms", uniform_start)
        end
        send_textured_depth_uniforms = function(depth_bias)
            local uniform_start = love.timer.getTime()
            self:_send_textured_depth_uniforms(depth_bias)
            add_uniform_hotspot("depth_uniform_ms", uniform_start)
        end
        send_common_uniforms = function(shader)
            local uniform_start = love.timer.getTime()
            self:_send_common_uniforms(shader)
            add_uniform_hotspot("common_uniform_ms", uniform_start)
        end
        send_instanced_draw_uniforms = function(depth_bias)
            local uniform_start = love.timer.getTime()
            self:_send_instanced_draw_uniforms(depth_bias)
            add_uniform_hotspot("primitive_draw_uniform_ms", uniform_start)
        end
        send_static_draw_uniforms = function(depth_bias, mesh, item)
            local uniform_start = love.timer.getTime()
            self:_send_static_draw_uniforms(depth_bias, mesh, item)
            add_uniform_hotspot("primitive_draw_uniform_ms", uniform_start)
        end
        send_textured_common_uniforms = function(shader)
            local uniform_start = love.timer.getTime()
            self:_send_textured_common_uniforms(shader)
            add_uniform_hotspot("common_uniform_ms", uniform_start)
        end
        send_textured_draw_uniforms = function(item, shader)
            local uniform_start = love.timer.getTime()
            self:_send_textured_draw_uniforms(item, shader)
            add_uniform_hotspot("textured_draw_uniform_ms", uniform_start)
        end
        send_local_light_uniforms = function(shader, item)
            local uniform_start = love.timer.getTime()
            self:_send_local_light_uniforms_for_item(
                shader, item, true)
            add_uniform_hotspot("local_light_uniform_ms", uniform_start)
        end
    else
        draw_textured_mesh = function(
            item, range_first, range_count)
            if item.mesh then
                if item.runtime_sampler_wrap_mode and item.texture
                    and item.texture.setWrap then
                    item.texture:setWrap(
                        item.runtime_sampler_wrap_mode,
                        item.runtime_sampler_wrap_mode)
                end
                range_first =
                    range_first
                        or item._transparent_range_first
                range_count =
                    range_count
                        or item._transparent_range_count
                if range_first and range_count then
                    item.mesh:setDrawRange(
                        range_first, range_count)
                end
                love.graphics.draw(item.mesh)
            end
        end
        draw_static_mesh = function(mesh) love.graphics.draw(mesh) end
        draw_instanced_mesh = function(mesh, count) love.graphics.drawInstanced(mesh, count) end
        send_depth_common_uniforms = function(shader) self:_send_depth_common_uniforms(shader) end
        send_instanced_depth_uniforms = function(depth_bias) self:_send_instanced_depth_uniforms(depth_bias) end
        send_static_depth_uniforms = function(depth_bias) self:_send_static_depth_uniforms(depth_bias) end
        send_textured_depth_uniforms = function(depth_bias) self:_send_textured_depth_uniforms(depth_bias) end
        send_common_uniforms = function(shader) self:_send_common_uniforms(shader) end
        send_instanced_draw_uniforms = function(depth_bias) self:_send_instanced_draw_uniforms(depth_bias) end
        send_static_draw_uniforms = function(depth_bias, mesh, item) self:_send_static_draw_uniforms(depth_bias, mesh, item) end
        send_textured_common_uniforms = function(shader) self:_send_textured_common_uniforms(shader) end
        send_textured_draw_uniforms = function(item, shader) self:_send_textured_draw_uniforms(item, shader) end
        send_local_light_uniforms = function(shader, item)
            self:_send_local_light_uniforms_for_item(
                shader, item, true)
        end
    end

    local use_opaque_depth_prepass = active_opaque_depth_prepass_mode ~= "off"
    local prepass_draw_static = use_opaque_depth_prepass
        and (active_opaque_depth_prepass_mode == "full" or active_opaque_depth_prepass_mode == "static")
    local prepass_draw_textured = use_opaque_depth_prepass
        and (active_opaque_depth_prepass_mode == "full" or active_opaque_depth_prepass_mode == "textured")
    -- Arbitrary imported meshes retain their conservative global opt-in. closed
    -- primitive batches instead resolve from their homogeneous transform
    -- handedness and the active target's projection-Y convention
    local opaque_back_cull_mode = self:_resolve_cull_mode("back", true)
    local transparent_static_cull_mode = "none"
    local function set_closed_primitive_cull_mode(item_or_handedness)
        local handedness = type(item_or_handedness) == "table"
            and item_or_handedness.closed_primitive_handedness
            or item_or_handedness
        set_cull_mode(
            self:_resolve_closed_primitive_cull_mode(handedness))
    end

    set_blend_mode("alpha", "alphamultiply")

    if use_opaque_depth_prepass then
        local depth_prepass_start = love.timer.getTime()
        love.graphics.setColorMask(false, false, false, false)
        set_depth_mode("less", true)

        if prepass_draw_static
            and (self.use_instancing or has_instanced_primitive_items) then
            set_shader(self._instanced_depth_shader)
            send_depth_common_uniforms(self._instanced_depth_shader)
            send_instanced_depth_uniforms(0)
            if self.use_instancing and not self.disable_cube_pass then
                if dynamic_mega_active then
                    set_closed_primitive_cull_mode(
                        self._mega_dynamic_cube_handedness)
                    draw_instanced_mesh(self._mega_dynamic_cube_draw_mesh, self._mega_dynamic_instance_count)
                    opaque_depth_prepass_draw_call_count = opaque_depth_prepass_draw_call_count + 1
                    instanced_cube_draw_call_count = instanced_cube_draw_call_count + 1
                end
                if mega_cube_path_active then
                    set_closed_primitive_cull_mode(
                        self._mega_cube_handedness)
                    draw_instanced_mesh(self._mega_cube_draw_mesh, self._mega_instance_count)
                    opaque_depth_prepass_draw_call_count = opaque_depth_prepass_draw_call_count + 1
                    instanced_cube_draw_call_count = instanced_cube_draw_call_count + 1
                end
                for i = 1, #chunk_cube_draw_list do
                    local chunk = chunk_cube_draw_list[i]
                    if chunk.instance_count > 0 and chunk.cube_draw_mesh and not chunk._cube_color_outside then
                        set_closed_primitive_cull_mode(chunk)
                        draw_instanced_mesh(chunk.cube_draw_mesh, chunk.instance_count)
                        opaque_depth_prepass_draw_call_count = opaque_depth_prepass_draw_call_count + 1
                        instanced_cube_draw_call_count = instanced_cube_draw_call_count + 1
                    end
                end
            end
            send_instanced_depth_uniforms(self.static_shape_depth_bias or 0)
            for i = 1, #opaque_static_items do
                local item = opaque_static_items[i]
                if item.kind == "instanced_primitive"
                    and item.draw_mesh
                    and (item.count or 0) > 0 then
                    set_closed_primitive_cull_mode(item)
                    draw_instanced_mesh(item.draw_mesh, item.count)
                    opaque_depth_prepass_draw_call_count = opaque_depth_prepass_draw_call_count + 1
                    instanced_primitive_draw_call_count = instanced_primitive_draw_call_count + 1
                end
            end
        end

        if prepass_draw_static then
            set_shader(self._static_depth_shader)
            send_depth_common_uniforms(self._static_depth_shader)
            send_static_depth_uniforms(0)
            if not self.disable_cube_pass then
                for i = 1, #chunk_static_cube_list do
                    local chunk = chunk_static_cube_list[i]
                    if chunk.static_cube_mesh then
                        set_closed_primitive_cull_mode(chunk)
                        draw_static_mesh(chunk.static_cube_mesh)
                        opaque_depth_prepass_draw_call_count = opaque_depth_prepass_draw_call_count + 1
                        static_mesh_draw_call_count = static_mesh_draw_call_count + 1
                    end
                end
            end
            send_static_depth_uniforms(self.static_shape_depth_bias or 0)
            for i = 1, #opaque_static_items do
                local item = opaque_static_items[i]
                if item.kind ~= "instanced_primitive" and item.mesh then
                    set_closed_primitive_cull_mode(item)
                    draw_static_mesh(item.mesh)
                    opaque_depth_prepass_draw_call_count = opaque_depth_prepass_draw_call_count + 1
                    static_mesh_draw_call_count = static_mesh_draw_call_count + 1
                end
            end
        end

        if prepass_draw_textured and #opaque_textured_batches > 0 then
            set_shader(self._textured_depth_shader)
            send_depth_common_uniforms(self._textured_depth_shader)
            local active_cull_mode = nil
            local active_depth_bias = nil
            for i = 1, #opaque_textured_batches do
                local batch = opaque_textured_batches[i]
                if batch.skip_depth_prepass ~= true then
                    local wanted_cull_mode = batch.resolved_cull_mode or self:_resolve_cull_mode(
                        batch.cull_mode or "none",
                        batch.mirror_cull_swap == true,
                        batch.force_cull == true
                    )
                    if wanted_cull_mode ~= active_cull_mode then
                        set_cull_mode(wanted_cull_mode)
                        active_cull_mode = wanted_cull_mode
                    end
                    local wanted_depth_bias = batch.depth_bias or 0
                    self:_send_rigid_chunk_uniforms(self._textured_depth_shader,batch)
                    if wanted_depth_bias ~= active_depth_bias then
                        send_textured_depth_uniforms(wanted_depth_bias)
                        active_depth_bias = wanted_depth_bias
                    end
                    draw_textured_mesh(batch)
                    opaque_depth_prepass_draw_call_count = opaque_depth_prepass_draw_call_count + 1
                end
            end
        end

        -- groups must write prepass depth too, else the color pass leaves them punch-through
        if prepass_draw_textured then
            local groups = self._instanced_mesh_groups
            local default_depth_shader = self._instanced_mesh_depth_shader
            if groups and #groups > 0 and default_depth_shader then
                local camera_cframe = self.camera and self.camera.cframe or nil
                local active_group_shader = nil
                local active_group_cull = nil
                local active_group_ignore_alpha = nil
                local active_group_flip_u = nil
                local active_group_flip_v = nil
                for i = 1, #groups do
                    local group = groups[i]
                    -- must mirror the color pass's frustum skip
                    if group.frustum_visible ~= false then
                        local shared_pose = self:_get_shared_instance_pose(group)
                        local use_shared_pose = shared_pose
                            and self._instanced_mesh_shared_pose_depth_shader ~= nil
                        local depth_shader = use_shared_pose
                            and self._instanced_mesh_shared_pose_depth_shader
                            or default_depth_shader
                        if not rawequal(depth_shader, active_group_shader) then
                            set_shader(depth_shader)
                            depth_shader:send("uCameraPos", {
                                camera_cframe and camera_cframe.x or 0,
                                camera_cframe and camera_cframe.y or 0,
                                camera_cframe and camera_cframe.z or 0,
                            })
                            send_depth_common_uniforms(depth_shader)
                            active_group_shader = depth_shader
                            active_group_ignore_alpha = nil
                            active_group_flip_u = nil
                            active_group_flip_v = nil
                        end
                        local wanted_cull = self:_resolve_cull_mode(
                            group.cull_mode or "none", group.cull_swap == true, false)
                        if wanted_cull ~= active_group_cull then
                            set_cull_mode(wanted_cull)
                            active_group_cull = wanted_cull
                        end
                        depth_shader:send("uDepthBias", group.depth_bias or 0)
                        local ignore_alpha = group.ignore_texture_alpha
                            and 1 or 0
                        if ignore_alpha ~= active_group_ignore_alpha then
                            depth_shader:send(
                                "uIgnoreTextureAlpha", ignore_alpha)
                            active_group_ignore_alpha = ignore_alpha
                        end
                        local flip_u = group.flip_u and 1 or 0
                        if flip_u ~= active_group_flip_u then
                            depth_shader:send("uFlipU", flip_u)
                            active_group_flip_u = flip_u
                        end
                        local flip_v = group.flip_v and 1 or 0
                        if flip_v ~= active_group_flip_v then
                            depth_shader:send("uFlipV", flip_v)
                            active_group_flip_v = flip_v
                        end
                        if use_shared_pose then
                            self:_send_shared_instance_pose_uniforms(
                                depth_shader, group)
                        end
                        draw_instanced_mesh(group.draw_mesh, group.count)
                        opaque_depth_prepass_draw_call_count = opaque_depth_prepass_draw_call_count + 1
                    end
                end
            end
        end

        love.graphics.setColorMask(true, true, true, true)
        pass_timings.opaque_depth_prepass_ms = math.max(0, (love.timer.getTime() - depth_prepass_start) * 1000)
    end

    local function draw_textured_batch_sequence(batch_list, options)
        options = options or {}
        if #(batch_list or {}) <= 0 then
            return
        end
        set_blend_mode(options.blend_mode or "alpha", options.alpha_mode or "alphamultiply")
        local active_cull_mode = nil
        local active_depth_compare = options.initial_depth_compare or "less"
        local active_depth_write = options.depth_write == true
            and active_depth_compare ~= "always"
        -- this helper is entered from several passes. its caller-provided state
        -- is the state it WANTS, not proof of what the previous pass left live
        -- Prime the tracked GL state explicitly so the first matching item does
        -- not incorrectly skip a required less/lequal or depth-write change
        set_depth_mode(active_depth_compare, active_depth_write)
        local active_uniform_state_key = nil
        local active_textured_shader = nil
        for i = 1, #batch_list do
            local batch = batch_list[i]
            local textured_shader = get_textured_shader(batch)
            if not rawequal(textured_shader, active_textured_shader) then
                set_textured_output_blend(textured_shader)
                set_shader(textured_shader)
                send_textured_common_uniforms(textured_shader)
                active_textured_shader = textured_shader
                active_uniform_state_key = nil
            end
            local wanted_depth_compare = batch.depth_compare or options.default_depth_compare or "less"
            if wanted_depth_compare ~= "always" then
                if options.allow_prepass_lequal and use_opaque_depth_prepass and wanted_depth_compare == "less" then
                    wanted_depth_compare = "lequal"
                elseif wanted_depth_compare ~= "lequal" then
                    wanted_depth_compare = "less"
                end
            end
            local wanted_depth_write = options.depth_write == true and wanted_depth_compare ~= "always"
            if wanted_depth_compare ~= active_depth_compare or wanted_depth_write ~= active_depth_write then
                set_depth_mode(wanted_depth_compare, wanted_depth_write)
                active_depth_compare = wanted_depth_compare
                active_depth_write = wanted_depth_write
            end
            local wanted_cull_mode = batch.resolved_cull_mode or self:_resolve_cull_mode(
                batch.cull_mode or "none",
                batch.mirror_cull_swap == true,
                batch.force_cull == true
            )
            if wanted_cull_mode ~= active_cull_mode then
                set_cull_mode(wanted_cull_mode)
                active_cull_mode = wanted_cull_mode
            end
            -- Alpha proof belongs to the resource, not its
            -- material key. its sender publishes that proof before returning
            -- through the existing material-uniform cache
            self:_send_rigid_chunk_uniforms(textured_shader,batch)
            if batch.uniform_state_key ~= active_uniform_state_key
                or rawequal(textured_shader, self._textured_shader)
                or rawequal(textured_shader, self._opaque_fast_textured_shader) then
                send_textured_draw_uniforms(batch, textured_shader)
                active_uniform_state_key = batch.uniform_state_key
            end
            send_local_light_uniforms(textured_shader, batch)
            draw_textured_mesh(batch)
            draw_call_count = draw_call_count + 1
            textured_draw_call_count = textured_draw_call_count + 1
            if options.transparent_count == true then
                transparent_draw_call_count = transparent_draw_call_count + 1
            end
            note_textured_draw(textured_shader, batch.texture, batch)
            if batch.surface_appearance == true then
                surface_appearance_batch_count =
                    surface_appearance_batch_count + 1
            end
            if collect_detailed_draw_stats then
                local variant_id = batch.shader_variant_id or RBX._resolve_textured_shader_variant_id(batch)
                textured_variant_draw_counts[variant_id] = (textured_variant_draw_counts[variant_id] or 0) + 1
                if batch.surface_appearance ~= true
                    and batch.legacy_textured == false then
                    texture_array_batch_count = texture_array_batch_count + 1
                elseif batch.surface_appearance ~= true then
                    legacy_textured_batch_count = legacy_textured_batch_count + 1
                end
            end
        end
    end

    if has_opaque then
        local opaque_pass_start = love.timer.getTime()
        set_depth_mode(use_opaque_depth_prepass and "lequal" or "less", not use_opaque_depth_prepass)

        if self.use_instancing or has_instanced_primitive_items then
            set_shader(self._instanced_shader)
            send_common_uniforms(self._instanced_shader)
            send_instanced_draw_uniforms(0)
            if self.use_instancing and not self.disable_cube_pass then
                if dynamic_mega_active then
                    -- one scene-bounds pack for the whole set, per-chunk packs defeat the single-draw win
                    local dyn_light_item = self._scene_dynamic_local_light_item or {}
                    dyn_light_item.bounds = self._scene_bounds
                    self._scene_dynamic_local_light_item = dyn_light_item
                    send_local_light_uniforms(self._instanced_shader, dyn_light_item)
                    set_closed_primitive_cull_mode(
                        self._mega_dynamic_cube_handedness)
                    draw_instanced_mesh(self._mega_dynamic_cube_draw_mesh, self._mega_dynamic_instance_count)
                    draw_call_count = draw_call_count + 1
                    instanced_cube_draw_call_count = instanced_cube_draw_call_count + 1
                end
                if mega_cube_path_active then
                    local scene_light_item = self._scene_local_light_item or {}
                    scene_light_item.bounds = self._scene_bounds
                    self._scene_local_light_item = scene_light_item
                    send_local_light_uniforms(self._instanced_shader, scene_light_item)
                    set_closed_primitive_cull_mode(
                        self._mega_cube_handedness)
                    draw_instanced_mesh(self._mega_cube_draw_mesh, self._mega_instance_count)
                    draw_call_count = draw_call_count + 1
                    instanced_cube_draw_call_count = instanced_cube_draw_call_count + 1
                end
                for i = 1, #chunk_cube_draw_list do
                    local chunk = chunk_cube_draw_list[i]
                    if chunk.instance_count > 0 and chunk.cube_draw_mesh and not chunk._cube_color_outside then
                        send_local_light_uniforms(self._instanced_shader, chunk)
                        set_closed_primitive_cull_mode(chunk)
                        draw_instanced_mesh(chunk.cube_draw_mesh, chunk.instance_count)
                        draw_call_count = draw_call_count + 1
                        instanced_cube_draw_call_count = instanced_cube_draw_call_count + 1
                    end
                end
            end
            send_instanced_draw_uniforms(self.static_shape_depth_bias or 0)
            for i = 1, #opaque_static_items do
                local item = opaque_static_items[i]
                if item.kind == "instanced_primitive"
                    and item.draw_mesh
                    and (item.count or 0) > 0 then
                    send_local_light_uniforms(self._instanced_shader, item)
                    set_closed_primitive_cull_mode(item)
                    draw_instanced_mesh(item.draw_mesh, item.count)
                    draw_call_count = draw_call_count + 1
                    instanced_primitive_draw_call_count = instanced_primitive_draw_call_count + 1
                end
            end
        end

        set_shader(self._static_shader)
        send_common_uniforms(self._static_shader)
        send_static_draw_uniforms(0)
        if not self.disable_cube_pass then
            for i = 1, #chunk_static_cube_list do
                local chunk = chunk_static_cube_list[i]
                if chunk.static_cube_mesh then
                    send_local_light_uniforms(self._static_shader, chunk)
                    send_static_draw_uniforms(0, chunk.static_cube_mesh, chunk)
                    set_closed_primitive_cull_mode(chunk)
                    draw_static_mesh(chunk.static_cube_mesh)
                    draw_call_count = draw_call_count + 1
                    static_mesh_draw_call_count = static_mesh_draw_call_count + 1
                end
            end
        end
        send_static_draw_uniforms(self.static_shape_depth_bias or 0)
        for i = 1, #opaque_static_items do
            local item = opaque_static_items[i]
            if item.kind ~= "instanced_primitive" and item.mesh then
                send_local_light_uniforms(self._static_shader, item)
                send_static_draw_uniforms(self.static_shape_depth_bias or 0, item.mesh, item)
                set_closed_primitive_cull_mode(item)
                draw_static_mesh(item.mesh)
                draw_call_count = draw_call_count + 1
                static_mesh_draw_call_count = static_mesh_draw_call_count + 1
            end
        end

        -- 1 drawInstanced per (geometry sig x render state), pre-sorted by variant = <=2 shader switches/frame
        local instanced_mesh_groups = self._instanced_mesh_groups
        if instanced_mesh_groups and #instanced_mesh_groups > 0 then
            local active_group_shader = nil
            local active_group_cull = nil
            local active_group_bias = nil
            local active_group_fu = nil
            local active_group_fv = nil
            local active_group_ignore_alpha = nil
            local active_group_unit_alpha = nil
            local active_material_textures = nil
            local active_primitive_material = nil
            local active_use_material_maps = nil
            local active_use_normal_map = nil
            local active_texture_color_mix = nil
            -- Value-owned, pass-local projection snapshots. Groups own distinct
            -- vec3 tables even when their primitive bounds/signs are identical
            -- Scalar lanes also avoid aliasing a subsequently mutated payload
            local active_projection_studs, active_projection_tiling
            local active_projection_min_x, active_projection_min_y, active_projection_min_z
            local active_projection_max_x, active_projection_max_y, active_projection_max_z
            local active_projection_em_x, active_projection_em_y, active_projection_em_z
            local active_projection_sign_x, active_projection_sign_y, active_projection_sign_z
            local group_cull_saved_draws = 0
            local group_cull_saved_instances = 0
            local group_uniform_send_count = 0
            for i = 1, #instanced_mesh_groups do
                local group = instanced_mesh_groups[i]
                local shader, shared_pose
                if group.frustum_visible == false then
                    shader = nil
                    group_cull_saved_draws = group_cull_saved_draws + 1
                    group_cull_saved_instances = group_cull_saved_instances + (group.count or 0)
                elseif group.variant == "material_projected" then
                    shader = self._instanced_mesh_material_shader
                else
                    shared_pose = self:_get_shared_instance_pose(group)
                    if shared_pose
                        and self._instanced_mesh_shared_pose_fast_shader ~= nil then
                        shader = self._instanced_mesh_shared_pose_fast_shader
                    else
                        shared_pose = nil
                        shader = self._instanced_mesh_fast_shader
                    end
                end
                if shader then
                    if not rawequal(shader, active_group_shader) then
                        set_shader(shader)
                        send_textured_common_uniforms(shader)
                        -- must match baked batches, only what the fragment reads -- glsl prunes the rest and send() throws
                        shader:send("uBrightness", 1)
                        group_uniform_send_count =
                            group_uniform_send_count + 1
                        if group.variant ~= "material_projected" then
                            shader:send("uTextureColorMix", 1)
                            shader:send("uLightInfluence", 1)
                            group_uniform_send_count =
                                group_uniform_send_count + 2
                        elseif group.variant == "material_projected" then
                            -- per-material map flags are sent below. Curved
                            -- primitive bases intentionally use the flat
                            -- material route even when the descriptor has maps
                            shader:send("uLightInfluence", 1)
                            shader:send("uUseTexturedLighting", 1)
                            shader:send("uDetailNormalMix", 0)
                            shader:send("uDetailContrast", 1)
                            shader:send("uIgnoreTextureAlpha", 1)
                            shader:send("uMeshDebugMode", 0)
                            group_uniform_send_count =
                                group_uniform_send_count + 6
                        end
                        active_group_shader = shader
                        active_group_bias = nil
                        active_group_fu = nil
                        active_group_fv = nil
                        active_group_ignore_alpha = nil
                        active_group_unit_alpha = nil
                        active_material_textures = nil
                        active_primitive_material = nil
                        active_use_material_maps = nil
                        active_use_normal_map = nil
                        active_texture_color_mix = nil
                        active_projection_studs, active_projection_tiling = nil, nil
                        active_projection_min_x, active_projection_min_y, active_projection_min_z = nil, nil, nil
                        active_projection_max_x, active_projection_max_y, active_projection_max_z = nil, nil, nil
                        active_projection_em_x, active_projection_em_y, active_projection_em_z = nil, nil, nil
                        active_projection_sign_x, active_projection_sign_y, active_projection_sign_z = nil, nil, nil
                    end
                    -- both indexed color families consume the same immutable
                    -- payload proof, mutable and legacy groups publish false
                    local unit_alpha = group.vertex_alpha_is_one == true
                    if active_group_unit_alpha ~= unit_alpha then
                        shader:send("uVertexAlphaIsOne", unit_alpha)
                        group_uniform_send_count = group_uniform_send_count + 1
                        active_group_unit_alpha = unit_alpha
                    end
                    -- each spatially partitioned group is an independent
                    -- four-light consumer. Payload caching suppresses identical
                    -- adjacent sends without reverting to a scene-wide top-four
                    -- pack that misses lights near distant repeated meshes
                    send_local_light_uniforms(shader, group)
                    local wanted_cull = self:_resolve_cull_mode(
                        group.cull_mode or "none", group.cull_swap == true, false)
                    if wanted_cull ~= active_group_cull then
                        set_cull_mode(wanted_cull)
                        active_group_cull = wanted_cull
                    end
                    -- change-only sends, groups pre-sorted by this exact state
                    local wanted_bias = group.depth_bias or 0
                    if wanted_bias ~= active_group_bias then
                        shader:send("uDepthBias", wanted_bias)
                        group_uniform_send_count =
                            group_uniform_send_count + 1
                        active_group_bias = wanted_bias
                    end
                    local wanted_fu = group.flip_u and 1 or 0
                    if wanted_fu ~= active_group_fu then
                        shader:send("uFlipU", wanted_fu)
                        group_uniform_send_count =
                            group_uniform_send_count + 1
                        active_group_fu = wanted_fu
                    end
                    local wanted_fv = group.flip_v and 1 or 0
                    if wanted_fv ~= active_group_fv then
                        shader:send("uFlipV", wanted_fv)
                        group_uniform_send_count =
                            group_uniform_send_count + 1
                        active_group_fv = wanted_fv
                    end
                    local wanted_ignore_alpha =
                        group.ignore_texture_alpha and 1 or 0
                    if wanted_ignore_alpha
                        ~= active_group_ignore_alpha then
                        shader:send(
                            "uIgnoreTextureAlpha",
                            wanted_ignore_alpha)
                        group_uniform_send_count =
                            group_uniform_send_count + 1
                        active_group_ignore_alpha =
                            wanted_ignore_alpha
                    end
                    local projected = group.projected
                    if projected then
                        -- a material can be shared by imported geometry,
                        -- mapped primitive faces and flat curved primitives
                        -- Texture identity alone cannot identify that state
                        local primitive_material = projected.primitive == true and 1 or 0
                        if active_primitive_material ~= primitive_material then
                            shader:send("uPrimitiveMaterial", primitive_material)
                            group_uniform_send_count = group_uniform_send_count + 1
                            active_primitive_material = primitive_material
                        end
                        local use_material_maps = projected.use_material_maps ~= false and 1 or 0
                        if active_use_material_maps ~= use_material_maps then
                            shader:send("uUseMaterialMaps", use_material_maps)
                            group_uniform_send_count = group_uniform_send_count + 1
                            active_use_material_maps = use_material_maps
                        end
                        local use_normal_map = projected.use_normal_map ~= false and 1 or 0
                        if active_use_normal_map ~= use_normal_map then
                            shader:send("uUseNormalMap", use_normal_map)
                            group_uniform_send_count = group_uniform_send_count + 1
                            active_use_normal_map = use_normal_map
                        end
                        local texture_color_mix = projected.texture_color_mix or 1
                        if active_texture_color_mix ~= texture_color_mix then
                            shader:send("uTextureColorMix", texture_color_mix)
                            group_uniform_send_count = group_uniform_send_count + 1
                            active_texture_color_mix = texture_color_mix
                        end
                        -- dedup compares ALL maps: materials share the flat-normal fallback but differ in roughness/metalness
                        local mats = active_material_textures
                        if not (mats
                            and mats.material_key == projected.material_key
                            and mats.normal_texture == projected.normal_texture
                            and mats.roughness_texture == projected.roughness_texture
                            and mats.metalness_texture == projected.metalness_texture) then
                            local defaults = RBX._material_uniform_defaults
                            shader:send("uNormalMap", projected.normal_texture or self._flat_normal_texture)
                            shader:send("uDetailNormalMap", self._flat_normal_texture)
                            shader:send("uRoughnessMap", projected.roughness_texture or self._white_texture)
                            shader:send("uMetalnessMap", projected.metalness_texture or self._black_texture)
                            shader:send("uMaterialSurface",
                                projected.material_surface or defaults.surface)
                            shader:send("uMaterialMapMask",
                                projected.material_map_mask or defaults.maps_disabled)
                            group_uniform_send_count =
                                group_uniform_send_count + 6
                            active_material_textures = projected
                        end
                        if active_projection_studs ~= projected.studs_per_tile then
                            shader:send("uStudsPerTile", projected.studs_per_tile)
                            active_projection_studs = projected.studs_per_tile
                            group_uniform_send_count = group_uniform_send_count + 1
                        end
                        if active_projection_tiling ~= projected.tiling then
                            shader:send("uMaterialTiling", projected.tiling)
                            active_projection_tiling = projected.tiling
                            group_uniform_send_count = group_uniform_send_count + 1
                        end
                        local value = projected.bounds_min
                        if active_projection_min_x ~= value[1] or active_projection_min_y ~= value[2]
                            or active_projection_min_z ~= value[3] then
                            shader:send("uProjBoundsMin", value)
                            active_projection_min_x, active_projection_min_y, active_projection_min_z = value[1], value[2], value[3]
                            group_uniform_send_count = group_uniform_send_count + 1
                        end
                        value = projected.bounds_max
                        if active_projection_max_x ~= value[1] or active_projection_max_y ~= value[2]
                            or active_projection_max_z ~= value[3] then
                            shader:send("uProjBoundsMax", value)
                            active_projection_max_x, active_projection_max_y, active_projection_max_z = value[1], value[2], value[3]
                            group_uniform_send_count = group_uniform_send_count + 1
                        end
                        value = projected.em_sign
                        if active_projection_em_x ~= value[1] or active_projection_em_y ~= value[2]
                            or active_projection_em_z ~= value[3] then
                            shader:send("uProjEmSign", value)
                            active_projection_em_x, active_projection_em_y, active_projection_em_z = value[1], value[2], value[3]
                            group_uniform_send_count = group_uniform_send_count + 1
                        end
                        value = projected.bounds_sign
                        if active_projection_sign_x ~= value[1] or active_projection_sign_y ~= value[2]
                            or active_projection_sign_z ~= value[3] then
                            shader:send("uProjBoundsSign", value)
                            active_projection_sign_x, active_projection_sign_y, active_projection_sign_z = value[1], value[2], value[3]
                            group_uniform_send_count = group_uniform_send_count + 1
                        end
                    end
                    if shared_pose then
                        group_uniform_send_count = group_uniform_send_count
                            + self:_send_shared_instance_pose_uniforms(
                                shader, group)
                    end
                    draw_instanced_mesh(group.draw_mesh, group.count)
                    draw_call_count = draw_call_count + 1
                    instanced_mesh_draw_call_count = instanced_mesh_draw_call_count + 1
                end
            end
            -- restore cull state the textured section below assumes
            set_cull_mode(opaque_back_cull_mode)
            self._instanced_group_cull_saved_draws = group_cull_saved_draws
            self._instanced_group_cull_saved_instances = group_cull_saved_instances
            self._frame_instanced_mesh_uniform_send_count =
                group_uniform_send_count
            self:_note_uniform_send(group_uniform_send_count)
        end

        if #opaque_textured_batches > 0 then
            local active_cull_mode = nil
            local active_depth_compare = use_opaque_depth_prepass and "lequal" or "less"
            local active_depth_write = not use_opaque_depth_prepass
            local active_uniform_state_key = nil
            local active_textured_shader = nil
            for i = 1, #opaque_textured_batches do
                local batch = opaque_textured_batches[i]
                local textured_shader = get_textured_shader(batch)
                if not rawequal(textured_shader, active_textured_shader) then
                    set_textured_output_blend(textured_shader)
                    set_shader(textured_shader)
                    send_textured_common_uniforms(textured_shader)
                    active_textured_shader = textured_shader
                    active_uniform_state_key = nil
                end
                local wanted_depth_compare = batch.depth_compare or "less"
                if wanted_depth_compare ~= "always" then
                    if use_opaque_depth_prepass
                        and batch.skip_depth_prepass ~= true
                        and wanted_depth_compare == "less" then
                        wanted_depth_compare = "lequal"
                    elseif wanted_depth_compare ~= "lequal" then
                        wanted_depth_compare = "less"
                    end
                end
                local wanted_depth_write = wanted_depth_compare == "always"
                    and false
                    or (batch.skip_depth_prepass == true
                        or not use_opaque_depth_prepass)
                if wanted_depth_compare ~= active_depth_compare or wanted_depth_write ~= active_depth_write then
                    set_depth_mode(wanted_depth_compare, wanted_depth_write)
                    active_depth_compare = wanted_depth_compare
                    active_depth_write = wanted_depth_write
                end
                local wanted_cull_mode = batch.resolved_cull_mode or self:_resolve_cull_mode(
                    batch.cull_mode or "none",
                    batch.mirror_cull_swap == true,
                    batch.force_cull == true
                )
                if wanted_cull_mode ~= active_cull_mode then
                    set_cull_mode(wanted_cull_mode)
                    active_cull_mode = wanted_cull_mode
                end
                self:_send_rigid_chunk_uniforms(textured_shader,batch)
                if batch.uniform_state_key ~= active_uniform_state_key
                    or rawequal(textured_shader, self._textured_shader)
                    or rawequal(textured_shader, self._opaque_fast_textured_shader) then
                    send_textured_draw_uniforms(batch, textured_shader)
                    active_uniform_state_key = batch.uniform_state_key
                end
                send_local_light_uniforms(textured_shader, batch)
                draw_textured_mesh(batch)
                draw_call_count = draw_call_count + 1
                textured_draw_call_count = textured_draw_call_count + 1
                note_textured_draw(textured_shader, batch.texture, batch)
                if batch.surface_appearance == true then
                    surface_appearance_batch_count =
                        surface_appearance_batch_count + 1
                end
                if collect_detailed_draw_stats then
                    local variant_id = batch.shader_variant_id or RBX._resolve_textured_shader_variant_id(batch)
                    textured_variant_draw_counts[variant_id] = (textured_variant_draw_counts[variant_id] or 0) + 1
                    if batch.surface_appearance ~= true
                        and batch.legacy_textured == false then
                        texture_array_batch_count = texture_array_batch_count + 1
                    elseif batch.surface_appearance ~= true then
                        legacy_textured_batch_count = legacy_textured_batch_count + 1
                    end
                end
            end
        end

        draw_textured_batch_sequence(opaque_surface_geometry_batches, {
            depth_write = true,
            allow_prepass_lequal = true,
            initial_depth_compare = use_opaque_depth_prepass and "lequal" or "less",
        })
        pass_timings.opaque_ms = math.max(0, (love.timer.getTime() - opaque_pass_start) * 1000)
    end

    -- Mechanical ropes/rods join the ordinary depth-tested world pass. their
    -- single lit batch writes depth before alpha geometry and overlay GUIs
    if constraint_visuals then
        local constraint_pass_start = love.timer.getTime()
        set_shader(self._static_shader)
        set_depth_mode("less", true)
        set_cull_mode("none")
        set_blend_mode("alpha", "alphamultiply")
        send_common_uniforms(self._static_shader)
        send_static_draw_uniforms(0, self._constraint_visual_mesh)
        send_local_light_uniforms(self._static_shader, constraint_visuals)
        draw_static_mesh(self._constraint_visual_mesh)
        draw_call_count = draw_call_count + 1
        static_mesh_draw_call_count = static_mesh_draw_call_count + 1
        pass_timings.constraints_ms = (love.timer.getTime() - constraint_pass_start) * 1000
    end
    if #opaque_overlay_textured_batches > 0 then
        local overlay_pass_start = love.timer.getTime()
        set_blend_mode("alpha", "premultiplied")
        set_depth_mode(use_opaque_depth_prepass and "lequal" or "less", false)
        local active_cull_mode = nil
        local active_depth_compare = use_opaque_depth_prepass and "lequal" or "less"
        local active_depth_write = false
        local active_uniform_state_key = nil
        local active_textured_shader = nil

        for i = 1, #opaque_overlay_textured_batches do
            local batch = opaque_overlay_textured_batches[i]
            local textured_shader = get_textured_shader(batch)
            if not rawequal(textured_shader, active_textured_shader) then
                set_textured_output_blend(textured_shader)
                set_shader(textured_shader)
                send_textured_common_uniforms(textured_shader)
                active_textured_shader = textured_shader
                active_uniform_state_key = nil
            end
            local wanted_depth_compare = batch.depth_compare or "less"
            if wanted_depth_compare ~= "always" then
                if use_opaque_depth_prepass and wanted_depth_compare == "less" then
                    wanted_depth_compare = "lequal"
                elseif wanted_depth_compare ~= "lequal" then
                    wanted_depth_compare = "less"
                end
            end
            local wanted_depth_write = false
            if wanted_depth_compare ~= active_depth_compare or wanted_depth_write ~= active_depth_write then
                set_depth_mode(wanted_depth_compare, wanted_depth_write)
                active_depth_compare = wanted_depth_compare
                active_depth_write = wanted_depth_write
            end
            local wanted_cull_mode = batch.resolved_cull_mode or self:_resolve_cull_mode(
                batch.cull_mode or "none",
                batch.mirror_cull_swap == true,
                batch.force_cull == true
            )
            if wanted_cull_mode ~= active_cull_mode then
                set_cull_mode(wanted_cull_mode)
                active_cull_mode = wanted_cull_mode
            end
            self:_send_rigid_chunk_uniforms(textured_shader,batch)
            if batch.uniform_state_key ~= active_uniform_state_key
                or rawequal(textured_shader, self._textured_shader)
                or rawequal(textured_shader, self._opaque_fast_textured_shader) then
                send_textured_draw_uniforms(batch, textured_shader)
                active_uniform_state_key = batch.uniform_state_key
            end
            send_local_light_uniforms(textured_shader, batch)
            draw_textured_mesh(batch)
            draw_call_count = draw_call_count + 1
            textured_draw_call_count = textured_draw_call_count + 1
            note_textured_draw(textured_shader, batch.texture, batch)
            if batch.surface_appearance == true then
                surface_appearance_batch_count =
                    surface_appearance_batch_count + 1
            end
            if collect_detailed_draw_stats then
                local variant_id = batch.shader_variant_id or RBX._resolve_textured_shader_variant_id(batch)
                textured_variant_draw_counts[variant_id] = (textured_variant_draw_counts[variant_id] or 0) + 1
                if batch.surface_appearance ~= true
                    and batch.legacy_textured == false then
                    texture_array_batch_count = texture_array_batch_count + 1
                elseif batch.surface_appearance ~= true then
                    legacy_textured_batch_count = legacy_textured_batch_count + 1
                end
            end
        end
        pass_timings.overlay_ms = math.max(0, (love.timer.getTime() - overlay_pass_start) * 1000)
    end

    -- transparent pass: back-to-front, depth test on, no depth writes
    self._transparent_textured_range_active_saved_draw_count = 0
    self._transparent_textured_range_active_merged_source_draw_count = 0
    if not has_transparent
        and self.measure_transparent_adjacency_candidates == true
        and self._transparent_adjacency_stats then
        for key in pairs(self._transparent_adjacency_stats) do
            self._transparent_adjacency_stats[key] = nil
        end
    end
    if not has_transparent
        and self._transparent_textured_range_groups_pending == true
        and (self.disable_transparent_pass == true
            or self.disable_textured_pass == true
            or (tonumber(self._transparent_part_count) or 0)
                <= 0) then
        self:_build_transparent_textured_range_groups(
            {}, get_textured_shader)
    end
    if has_transparent then
        local transparent_pass_start = love.timer.getTime()
        local transparent_sort_start = hotspot_start()
        self:_sort_transparent_draw_items(transparent_items)
        hotspot_add("transparent_sort_ms", transparent_sort_start)
        if self._transparent_textured_range_groups_pending == true then
            if #transparent_items > 0
                and self.disable_textured_pass ~= true then
                self:_build_transparent_textured_range_groups(
                    transparent_items, get_textured_shader, true)
            elseif self.disable_textured_pass == true then
                self:_build_transparent_textured_range_groups(
                    {}, get_textured_shader)
            end
        elseif self._transparent_textured_range_build_state
            and self.disable_textured_pass ~= true then
            self:_advance_transparent_textured_range_build(
                transparent_items, false)
        elseif self._transparent_textured_range_build_state
            and self.disable_textured_pass == true
            and self._cancel_transparent_textured_range_build then
            self:_cancel_transparent_textured_range_build(
                "textured_pass_disabled")
        elseif self.disable_textured_pass ~= true then
            self:_refresh_transparent_textured_range_vertex_maps(
                transparent_items, false)
        end
        if collect_detailed_draw_stats
            and self.measure_transparent_adjacency_candidates == true then
            self:_measure_transparent_adjacency_candidates(
                transparent_items,
                get_textured_shader,
                self.disable_textured_pass ~= true)
        end
        set_blend_mode("alpha", "alphamultiply")
        set_depth_mode("less", false)
        set_cull_mode("none")

        local active_transparent_shader = nil
        local active_cull_mode = "none"
        local active_depth_compare = "less"
        local active_uniform_state_key = nil
        local disable_textured_transparent = self.disable_textured_pass
        local transparent_static_fallback_bias = self.transparent_depth_bias or 0
        local transparent_range_saved_draw_count = 0
        local transparent_range_merged_source_draw_count = 0
        local i = 1
        while i <= #transparent_items do
            local item = transparent_items[i]
            if disable_textured_transparent and item.kind ~= "static" then
                i = i + 1
            else
                local wanted_depth_compare =
                    item.depth_compare == "always"
                        and "always"
                    or (item.depth_compare == "lequal"
                        and "lequal"
                        or "less")
                if wanted_depth_compare
                    ~= active_depth_compare then
                    set_depth_mode(
                        wanted_depth_compare, false)
                    active_depth_compare =
                        wanted_depth_compare
                end
                if item.kind == "world_mesh" then
                    set_blend_mode("alpha", "premultiplied")
                    set_cull_mode("none")
                    active_cull_mode = "none"
                    local shader = RBX._world_mesh.shader(self, item)
                    shader:send('uLightEmission',item.light_emission or 0)
                    shader:send('uBrightness',item.brightness or 1)
                    if shader:hasUniform('uLightInfluence')then
                        shader:send('uLightInfluence',item.light_influence or 0)
                        self:_send_local_light_uniforms_for_item(shader,item,true)
                    end
                    set_shader(shader)
                    active_transparent_shader = shader
                    active_uniform_state_key = nil
                    love.graphics.setColor(1,1,1,1)
                    love.graphics.draw(item.mesh)
                    draw_call_count = draw_call_count + 1
                    transparent_draw_call_count = transparent_draw_call_count + 1
                    i = i + 1
                elseif item.kind == "static" then
                    set_blend_mode(
                        "alpha", "alphamultiply")
                    if active_cull_mode
                        ~= transparent_static_cull_mode then
                        set_cull_mode(
                            transparent_static_cull_mode)
                        active_cull_mode =
                            transparent_static_cull_mode
                    end
                    if active_transparent_shader
                        ~= "static" then
                        set_shader(self._static_shader)
                        send_common_uniforms(
                            self._static_shader)
                        active_transparent_shader =
                            "static"
                    end
                    active_uniform_state_key = nil
                    send_static_draw_uniforms(
                        item.depth_bias
                            or transparent_static_fallback_bias, item.mesh, item)
                    send_local_light_uniforms(
                        self._static_shader, item)
                    draw_static_mesh(item.mesh)
                    draw_call_count = draw_call_count + 1
                    static_mesh_draw_call_count =
                        static_mesh_draw_call_count + 1
                    transparent_draw_call_count =
                        transparent_draw_call_count + 1
                    i = i + 1
                else
                    local range_last, range_count =
                        self:_transparent_textured_range_span(
                            transparent_items, i)
                    range_last = math.max(
                        i, tonumber(range_last) or i)
                    local merged_source_count =
                        range_last - i + 1
                    local wanted_cull_mode =
                        item.resolved_cull_mode
                        or self:_resolve_cull_mode(
                            item.cull_mode or "none",
                            item.mirror_cull_swap == true,
                            item.force_cull == true
                        )
                    if wanted_cull_mode
                        ~= active_cull_mode then
                        set_cull_mode(wanted_cull_mode)
                        active_cull_mode =
                            wanted_cull_mode
                    end
                    local textured_shader =
                        get_textured_shader(item)
                    if active_transparent_shader
                        ~= textured_shader then
                        set_shader(textured_shader)
                        send_textured_common_uniforms(
                            textured_shader)
                        active_transparent_shader =
                            textured_shader
                        active_uniform_state_key = nil
                    end
                    -- a static item may have changed blend state between two
                    -- textured items that share a shader, so reassert this per
                    -- transparent draw rather than only on shader switches
                    set_textured_output_blend(
                        textured_shader)
                    self:_send_rigid_chunk_uniforms(textured_shader,item)
                    if item.uniform_state_key
                        ~= active_uniform_state_key
                        or rawequal(textured_shader, self._textured_shader)
                        or rawequal(textured_shader, self._opaque_fast_textured_shader) then
                        send_textured_draw_uniforms(
                            item, textured_shader)
                        active_uniform_state_key =
                            item.uniform_state_key
                    end
                    send_local_light_uniforms(
                        textured_shader, item)
                    draw_textured_mesh(
                        item,
                        item._transparent_range_first,
                        range_count)
                    draw_call_count = draw_call_count + 1
                    textured_draw_call_count =
                        textured_draw_call_count + 1
                    transparent_draw_call_count =
                        transparent_draw_call_count + 1
                    note_textured_draw(
                        textured_shader, item.texture, item)
                    if merged_source_count > 1 then
                        transparent_range_saved_draw_count =
                            transparent_range_saved_draw_count
                                + merged_source_count - 1
                        transparent_range_merged_source_draw_count =
                            transparent_range_merged_source_draw_count
                                + merged_source_count
                    end
                    if item.surface_appearance == true then
                        surface_appearance_batch_count =
                            surface_appearance_batch_count + 1
                    end
                    if collect_detailed_draw_stats then
                        local variant_id =
                            item.shader_variant_id
                            or RBX._resolve_textured_shader_variant_id(
                                item)
                        textured_variant_draw_counts[
                            variant_id] =
                            (textured_variant_draw_counts[
                                variant_id] or 0) + 1
                        if item.surface_appearance ~= true
                            and item.legacy_textured == false then
                            texture_array_batch_count =
                                texture_array_batch_count + 1
                        elseif item.surface_appearance ~= true then
                            legacy_textured_batch_count =
                                legacy_textured_batch_count + 1
                        end
                    end
                    i = range_last + 1
                end
            end
        end
        self._transparent_textured_range_active_saved_draw_count =
            transparent_range_saved_draw_count
        self._transparent_textured_range_active_merged_source_draw_count =
            transparent_range_merged_source_draw_count
        pass_timings.transparent_ms = math.max(0, (love.timer.getTime() - transparent_pass_start) * 1000)
    end

    local surface_gui_pass_start = nil
    if #surface_gui_overlay_batches > 0 then
        surface_gui_pass_start = surface_gui_pass_start or love.timer.getTime()
        draw_textured_batch_sequence(surface_gui_overlay_batches, {
            depth_write = false,
            default_depth_compare = "lequal",
            initial_depth_compare = "lequal",
            blend_mode = "alpha",
            alpha_mode = "premultiplied",
        })
    end

    if #transparent_surface_gui_items > 0 then
        surface_gui_pass_start = surface_gui_pass_start or love.timer.getTime()
        draw_textured_batch_sequence(transparent_surface_gui_items, {
            depth_write = false,
            default_depth_compare = "lequal",
            initial_depth_compare = "lequal",
            blend_mode = "alpha",
            alpha_mode = "premultiplied",
            transparent_count = true,
        })
    end
    if surface_gui_pass_start then
        pass_timings.surface_gui_ms = math.max(0, (love.timer.getTime() - surface_gui_pass_start) * 1000)
    end

    set_shader()
    set_cull_mode("none")
    set_depth_mode("always", false)
    set_blend_mode("alpha", "alphamultiply")
    local draw_culling_stats = self._culling_stats or {}
    self._draw_stats = {
        draw_call_count = draw_call_count,
        opaque_depth_prepass_draw_call_count = opaque_depth_prepass_draw_call_count,
        textured_variant_draw_counts = textured_variant_draw_counts or {},
        texture_array_batch_count = texture_array_batch_count,
        legacy_textured_batch_count = legacy_textured_batch_count,
        surface_appearance_batch_count = surface_appearance_batch_count,
        surface_gui_visible_batch_count = (self._surface_gui_stats and self._surface_gui_stats.visible_batch_count) or 0,
        surface_gui_updated_batch_count = (self._surface_gui_stats and self._surface_gui_stats.updated_batch_count) or 0,
        surface_gui_deferred_batch_count = (self._surface_gui_stats and self._surface_gui_stats.deferred_batch_count) or
            0,
        surface_gui_catchup_batch_count = (self._surface_gui_stats and self._surface_gui_stats.catchup_batch_count) or 0,
        surface_gui_dirty_count = (self._surface_gui_stats and self._surface_gui_stats.dirty_count) or 0,
        surface_gui_update_ms = surface_gui_update_ms,
        depth_clip_recompute_count = depth_clip_recompute_count,
        instanced_cube_draw_call_count = instanced_cube_draw_call_count,
        instanced_primitive_draw_call_count = instanced_primitive_draw_call_count,
        instanced_mesh_draw_call_count = instanced_mesh_draw_call_count,
        static_mesh_draw_call_count = static_mesh_draw_call_count,
        textured_draw_call_count = textured_draw_call_count,
        transparent_draw_call_count = transparent_draw_call_count,
        skybox_draw_call_count = self._frame_skybox_draw_call_count or 0,
        shader_switch_count = shader_switch_count,
        depth_mode_switch_count = depth_mode_switch_count,
        cull_mode_switch_count = cull_mode_switch_count,
        blend_mode_switch_count = blend_mode_switch_count,
        shader_set_attempt_count = shader_set_attempt_count,
        depth_mode_set_attempt_count = depth_mode_set_attempt_count,
        cull_mode_set_attempt_count = cull_mode_set_attempt_count,
        blend_mode_set_attempt_count = blend_mode_set_attempt_count,
        uniform_send_count = self._frame_uniform_send_count or 0,
        lighting_uniform_send_count = self._frame_lighting_uniform_send_count or 0,
        local_light_uniform_send_count = self._frame_local_light_uniform_send_count or 0,
        local_light_uniform_packet_send_count =
            self._frame_local_light_uniform_packet_send_count or 0,
        local_light_uniform_legacy_send_count =
            self._frame_local_light_uniform_legacy_send_count or 0,
        local_light_uniform_packet_fallback_send_count =
            self._frame_local_light_uniform_packet_fallback_send_count or 0,
        local_light_uniform_packet_failure_count =
            self._frame_local_light_uniform_packet_failure_count or 0,
        local_light_uniform_packet_sanitized_value_count =
            self._frame_local_light_uniform_packet_sanitized_value_count or 0,
        local_light_uniform_packet_available =
            self._local_light_uniform_packet_available == true,
        local_light_uniform_packet_allocation_count =
            self._local_light_uniform_packet_allocation_count or 0,
        local_light_uniform_packet_shader_fallback_count =
            self._local_light_uniform_packet_shader_fallback_count or 0,
        local_light_uniform_packet_global_fallback_reason =
            self._local_light_uniform_packet_global_fallback_reason,
        local_light_uniform_packet_last_shader_error =
            self._local_light_uniform_packet_last_shader_error,
        instanced_mesh_uniform_send_count =
            self._frame_instanced_mesh_uniform_send_count or 0,
        local_light_stats = self._local_light_stats or {},
        texture_switch_count = texture_switch_count,
        draw_packet_build_ms = self._last_draw_packet_build_ms or 0,
        pass_timings = pass_timings,
        hotspots = hotspots,
        fallback_slow_path_count = self._frame_fallback_slow_path_count or 0,
        fallback_slow_path_reasons = self._frame_fallback_slow_path_reasons or {},
        textured_full_shader_draw_call_count = textured_full_shader_draw_call_count,
        textured_fast_shader_draw_call_count = textured_fast_shader_draw_call_count,
        textured_constant_shader_draw_call_count = textured_constant_shader_draw_call_count,
        textured_constant_unlit_draw_call_count = textured_constant_unlit_draw_call_count,
        textured_basic_opaque_draw_call_count = textured_basic_opaque_draw_call_count,
        textured_lit_nomaps_draw_call_count = textured_lit_nomaps_draw_call_count,
        textured_overlay_decal_draw_call_count = textured_overlay_decal_draw_call_count,
        textured_full_material_draw_call_count = textured_full_material_draw_call_count,
        textured_transparent_variant_draw_call_count = textured_transparent_variant_draw_call_count,
        alpha_like_draw_call_count = alpha_like_draw_call_count,
        shader_discard_draw_call_count = shader_discard_draw_call_count,
        attach_attribute_draw_count = self._frame_instance_attribute_attach_count or 0,
        attach_attribute_build_count = self._instance_attribute_attach_build_count or 0,
        mega_cube_path_active = mega_cube_path_active,
        submitted_chunk_count = #opaque_chunks,
        submitted_cube_instance_count = (mega_cube_path_active
            and (self._mega_instance_count or 0)
            or (draw_culling_stats.visible_cube_instance_count or 0))
            + (dynamic_mega_active and (self._mega_dynamic_instance_count or 0) or 0),
        submitted_static_item_count = #opaque_static_items,
        submitted_textured_batch_count = #opaque_textured_batches + #opaque_surface_geometry_batches,
        submitted_overlay_textured_batch_count = #opaque_overlay_textured_batches + #surface_gui_overlay_batches,
        submitted_transparent_item_count = #transparent_items + #transparent_surface_gui_items,
        opaque_depth_prepass_mode = active_opaque_depth_prepass_mode,
    }
    self._last_draw_submission_ms = (love.timer.getTime() - submission_start) * 1000
    self:_draw_world_debug()
end

function RBX:draw()
    if self:_should_draw_via_render_canvas() then
        local target_width, target_height = RBX._get_active_surface_dimensions()
        self:draw_to_rect(0, 0, target_width, target_height, {
            fit = self.letterbox_resolution and "contain" or "stretch",
            use_projection_size = true,
            background_color = self.letterbox_resolution and { 0, 0, 0, 1 } or nil,
        })
        return
    end

    self._last_surface_path = "draw"
    self._last_render_to_canvas_used = false
    self._last_draw_to_rect_used = false
    self._last_fullscreen_canvas_copy = false
    self._last_canvas_blit_ms = 0
    self:_prepare_frame_state()

    local draw_start = love.timer.getTime()
    local projection_width, projection_height = self:_get_projection_dimensions()
    self._last_render_target_width = projection_width
    self._last_render_target_height = projection_height

    -- Scene depth is initialized after preparatory offscreen passes below
    love.graphics.clear(0, 0, 0, 0, true, false)
    self:_update_camera_matrices(projection_width, projection_height)
    self:_draw_scene_pass()
    -- 2d overlay on scene output, under the debug text
    if self._draw_screen_guis then
        self:_draw_screen_guis(projection_width, projection_height)
    end
    self:_draw_debug_overlay(projection_width, projection_height)
    self:_record_draw_time(draw_start)
end

local function add_render_category_stats(out, item)
    if type(item) ~= "table" then
        return
    end

    out.visible_mesh_parts = out.visible_mesh_parts + (tonumber(item.mesh_part_count) or 0)

    local union_count = tonumber(item.union_part_count) or 0
    if union_count > 0 then
        out.visible_unions = out.visible_unions + union_count
        out.union_draw_calls = out.union_draw_calls + 1
    end
    if (tonumber(item.union_material_part_count) or 0) > 0 then
        out.union_material_batches = out.union_material_batches + 1
    end
    out.union_use_part_color_count = out.union_use_part_color_count + (tonumber(item.union_use_part_color_count) or 0)
    out.union_smoothing_angle_used = out.union_smoothing_angle_used +
        (tonumber(item.union_smoothing_angle_used_count) or 0)
    out.union_fallback_count = out.union_fallback_count + (tonumber(item.union_fallback_count) or 0)

    out.surface_detail_faces = out.surface_detail_faces + (tonumber(item.surface_detail_face_count) or 0)
    out.surface_studs_faces = out.surface_studs_faces + (tonumber(item.surface_studs_face_count) or 0)
    out.surface_inlet_faces = out.surface_inlet_faces + (tonumber(item.surface_inlet_face_count) or 0)
    out.surface_universal_faces = out.surface_universal_faces + (tonumber(item.surface_universal_face_count) or 0)
    out.surface_geometry_faces = out.surface_geometry_faces + (tonumber(item.surface_geometry_face_count) or 0)
    out.surface_shader_faces = out.surface_shader_faces + (tonumber(item.surface_shader_face_count) or 0)
    out.surface_lod_geometry_count = out.surface_lod_geometry_count + (tonumber(item.surface_lod_geometry_count) or 0)
    out.surface_lod_shader_count = out.surface_lod_shader_count + (tonumber(item.surface_lod_shader_count) or 0)
    out.surface_fallback_count = out.surface_fallback_count + (tonumber(item.surface_fallback_count) or 0)
    out.stud_diffuse_bound_count = out.stud_diffuse_bound_count + (tonumber(item.stud_diffuse_bound_count) or 0)
    out.stud_normal_bound_count = out.stud_normal_bound_count + (tonumber(item.stud_normal_bound_count) or 0)
    if (tonumber(item.surface_geometry_face_count) or 0) > 0 then
        out.surface_geometry_draws = out.surface_geometry_draws + 1
    end
    if (tonumber(item.surface_shader_face_count) or 0) > 0 then
        out.surface_shader_draws = out.surface_shader_draws + 1
    end

    out.specialmesh_count = out.specialmesh_count + (tonumber(item.specialmesh_count) or 0)
    out.specialmesh_head_count = out.specialmesh_head_count + (tonumber(item.specialmesh_head_count) or 0)
    out.specialmesh_axis_fixups = out.specialmesh_axis_fixups + (tonumber(item.specialmesh_axis_fixup_count) or 0)
    out.specialmesh_fallback_count = out.specialmesh_fallback_count + (tonumber(item.specialmesh_fallback_count) or 0)

    out.mesh_texture_hits = out.mesh_texture_hits + (tonumber(item.mesh_texture_hit_count) or 0)
    out.mesh_texture_misses = out.mesh_texture_misses + (tonumber(item.mesh_texture_miss_count) or 0)
    out.mesh_uv_missing = out.mesh_uv_missing + (tonumber(item.mesh_uv_missing_count) or 0)
    out.mesh_doublesided_count = out.mesh_doublesided_count + (tonumber(item.mesh_doublesided_count) or 0)
    out.mesh_axis_conversion_count = out.mesh_axis_conversion_count + (tonumber(item.mesh_axis_conversion_count) or 0)
    out.mesh_winding_flip_count = out.mesh_winding_flip_count + (tonumber(item.mesh_winding_flip_count) or 0)
    out.mesh_uv_flip_u_count = out.mesh_uv_flip_u_count + (tonumber(item.mesh_uv_flip_u_count) or 0)
    out.mesh_uv_flip_v_count = out.mesh_uv_flip_v_count + (tonumber(item.mesh_uv_flip_v_count) or 0)
    out.mesh_debug_axis_count = out.mesh_debug_axis_count + (tonumber(item.mesh_debug_axis_count) or 0)
    out.mesh_debug_bounds_count = out.mesh_debug_bounds_count + (tonumber(item.mesh_debug_bounds_count) or 0)
    out.z_bias_overlay_count = out.z_bias_overlay_count + (tonumber(item.z_bias_overlay_count) or 0)
    out.z_bias_decal_count = out.z_bias_decal_count + (tonumber(item.z_bias_decal_count) or 0)
    out.z_bias_surface_detail_count = out.z_bias_surface_detail_count +
        (tonumber(item.z_bias_surface_detail_count) or 0)
end

function RBX._collect_visible_render_category_stats(renderer)
    local out = {
        visible_unions = 0,
        union_draw_calls = 0,
        union_material_batches = 0,
        union_use_part_color_count = 0,
        union_smoothing_angle_used = 0,
        union_fallback_count = 0,
        surface_detail_faces = 0,
        surface_studs_faces = 0,
        surface_inlet_faces = 0,
        surface_universal_faces = 0,
        surface_geometry_faces = 0,
        surface_shader_faces = 0,
        surface_geometry_draws = 0,
        surface_shader_draws = 0,
        surface_lod_geometry_count = 0,
        surface_lod_shader_count = 0,
        surface_fallback_count = 0,
        stud_diffuse_bound_count = 0,
        stud_normal_bound_count = 0,
        visible_mesh_parts = 0,
        specialmesh_count = 0,
        specialmesh_head_count = 0,
        specialmesh_axis_fixups = 0,
        specialmesh_fallback_count = 0,
        mesh_texture_hits = 0,
        mesh_texture_misses = 0,
        mesh_uv_missing = 0,
        mesh_doublesided_count = 0,
        mesh_axis_conversion_count = 0,
        mesh_winding_flip_count = 0,
        mesh_uv_flip_u_count = 0,
        mesh_uv_flip_v_count = 0,
        mesh_debug_axis_count = 0,
        mesh_debug_bounds_count = 0,
        z_bias_overlay_count = 0,
        z_bias_decal_count = 0,
        z_bias_surface_detail_count = 0,
    }

    local lists = {
        renderer and renderer._visible_textured_batches or nil,
        renderer and renderer._visible_overlay_textured_batches or nil,
        renderer and renderer._visible_transparent_draw_items or nil,
    }
    if renderer and renderer._mega_cube_path_active == true and (renderer._mega_instance_count or 0) > 0 then
        lists[#lists + 1] = renderer._mega_textured_batches
        lists[#lists + 1] = renderer._mega_overlay_textured_batches
    end
    for list_index = 1, #lists do
        local list = lists[list_index]
        for item_index = 1, #(list or {}) do
            add_render_category_stats(out, list[item_index])
        end
    end
    out.zfight_risk_count = (out.z_bias_overlay_count or 0)
        + (out.z_bias_decal_count or 0)
        + (out.z_bias_surface_detail_count or 0)
        + (tonumber(renderer and renderer.zfight_risk_count) or 0)
    return out
end

function RBX:get_stats()
    self:_prepare_frame_state()

    local culling = self._culling_stats or {}
    local draw_stats = self._draw_stats or {}
    local local_light_stats = draw_stats.local_light_stats or self._local_light_stats or {}
    local opaque_light_sort_stats =
        self._opaque_local_light_sort_stats or {}
    local static_light_clusters =
        self._static_local_light_clusters or {}
    local static_light_cluster_stats =
        static_light_clusters.stats
            or self._static_local_light_cluster_last_build_stats
            or {}
    local transparent_adjacency_stats =
        self._transparent_adjacency_stats or {}
    local transparent_range_stats =
        self._transparent_textured_range_stats or {}
    local category_stats = RBX._collect_visible_render_category_stats(self)
    local cache_stats = self._load_cache_stats or {}
    local embedded_mesh_cache_stats = self.get_embedded_mesh_cache_stats
        and self:get_embedded_mesh_cache_stats() or {}
    local texture_prefetch_stats = {}
    for key, value in pairs(self._texture_prefetch_stats or {}) do
        texture_prefetch_stats[key] = value
    end
    local instanced_mesh_light_partition_group_count = 0
    for index = 1, #(self._instanced_mesh_groups or {}) do
        if self._instanced_mesh_groups[index].light_cell_key ~= nil then
            instanced_mesh_light_partition_group_count =
                instanced_mesh_light_partition_group_count + 1
        end
    end
    local render_backend_stats = {}
    if self._render_backend and self._render_backend.get_stats then
        local ok, stats = pcall(self._render_backend.get_stats, self._render_backend)
        if ok and type(stats) == "table" then
            render_backend_stats = stats
        end
    end
    local source_index_stats = self._instanced_mesh_index_stats or {}
    local instanced_mesh_index_stats = {
        indexed_group_count = source_index_stats.indexed_group_count or 0,
        uint16_group_count = source_index_stats.uint16_group_count or 0,
        uint32_group_count = source_index_stats.uint32_group_count or 0,
        flat_group_count = source_index_stats.flat_group_count or 0,
        backend_failure_fallback_count =
            source_index_stats.backend_failure_fallback_count or 0,
        source_vertex_count = source_index_stats.source_vertex_count or 0,
