local function count_debug_instance_graph(root)
    if type(root) ~= "table" then
        return 0, 0
    end
    local stack = { root }
    local total = 0
    local max_depth = 0
    local depths = { [root] = 0 }
    while #stack > 0 do
        local node = stack[#stack]
        stack[#stack] = nil
        total = total + 1
        local depth = depths[node] or 0
        if depth > max_depth then
            max_depth = depth
        end
        local children = rawget(node, "_children")
        if type(children) == "table" then
            for index = 1, #children do
                local child = children[index]
                if type(child) == "table" then
                    depths[child] = depth + 1
                    stack[#stack + 1] = child
                end
            end
        end
    end
    return total, max_depth
end

function count_debug_table_keys(value)
    if type(value) ~= "table" then
        return 0
    end
    local count = 0
    for _ in pairs(value) do
        count = count + 1
    end
    return count
end

function RBX:get_debug_report()
    local graphics_stats = {}
    if love and love.graphics and love.graphics.getStats then
        local ok, stats = pcall(love.graphics.getStats)
        if ok and type(stats) == "table" then
            graphics_stats = stats
        end
    end

    local stats = self:get_stats()
    local dirty_marks = self._debug_dirty_marks or {}
    local sync_counts = self._debug_sync_counts or {}
    local instance_count, instance_max_depth = count_debug_instance_graph(self._datamodel)
    local transform_dirty_part_count = count_debug_table_keys(self._transform_dirty_parts)
    local active_camera = self._current_camera_instance
    local camera_cframe = self.camera and self.camera.cframe or CFrame.new()
    local camera_look = camera_cframe.LookVector

    return {
        stats = stats,
        graphics = graphics_stats,
        dirty = {
            parts_dirty = self._parts_dirty == true,
            mode = self._parts_dirty_mode,
            scene_revision = self._scene_revision or 0,
            transform_dirty_part_count = transform_dirty_part_count,
            full_dirty_mark_count = dirty_marks.full or 0,
            transform_dirty_mark_count = dirty_marks.transform or 0,
            full_sync_count = sync_counts.full or 0,
            transform_sync_count = sync_counts.transform or 0,
            last_sync_mode = self._debug_last_sync_mode,
            last_transform_sync_part_count = self._debug_last_transform_sync_part_count or 0,
            mesh_uploads_total = self._mesh_uploads_total or 0,
            mesh_uploads_this_build = self._mesh_uploads_this_build or 0,
            mesh_uploads_this_frame = self._mesh_uploads_this_frame or 0,
            texture_uploads_this_frame = self._texture_uploads_this_frame or 0,
        },
        instances = {
            count = instance_count,
            max_depth = instance_max_depth,
            services = self._datamodel and count_debug_table_keys(rawget(self._datamodel, "_services_by_name")) or 0,
            core_part_count = #(self.parts or {}),
            linked_core_part_count = self._datamodel and count_debug_table_keys(rawget(self._datamodel, "_instance_by_core_id")) or 0,
            referent_index_count = self._datamodel and count_debug_table_keys(rawget(self._datamodel, "_instance_by_referent")) or 0,
        },
        camera = {
            active_camera_class = type(active_camera) == "table"
                and (rawget(active_camera, "_class_name") or active_camera.ClassName) or nil,
            active_camera_name = type(active_camera) == "table"
                and (rawget(active_camera, "_name") or active_camera.Name) or nil,
            camera_cframe_position = {
                x = camera_cframe.x or 0,
                y = camera_cframe.y or 0,
                z = camera_cframe.z or 0,
            },
            camera_look_vector = {
                x = camera_look.x or 0,
                y = camera_look.y or 0,
                z = camera_look.z or 0,
            },
            camera_update_count = self._debug_camera_cframe_update_count or 0,
        },
        physics = self.get_physics_diagnostics and self:get_physics_diagnostics() or nil,
        memory = {
            lua_kb = collectgarbage("count"),
            texture_memory_bytes = graphics_stats.texturememory or graphics_stats.textureMemory or 0,
        },
    }
end

function RBX:get_script_errors()
    return {}
end

function RBX.load_scene(path, options)
    local modern = require("engine/graphics/rbx")
    return modern.load_scene(path, options)
end

return RBX
